bool HasFVGAtPOC(bool bullish, double poc, double atr)
{
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      double mid = 0.0;
      if(bullish && BullishFVG(i, mid))
      {
         if(MathAbs(mid - poc) / atr <= FVG_POC_OVERLAP_ATR)
            return true;
      }
      if(!bullish && BearishFVG(i, mid))
      {
         if(MathAbs(mid - poc) / atr <= FVG_POC_OVERLAP_ATR)
            return true;
      }
   }
   return false;
}

double LinearRegressionSlope(int period)
{
   double xMean = (period - 1.0) / 2.0;
   double yMean = 0.0;
   for(int i = 0; i < period; i++) yMean += Close[i];
   yMean /= period;
   double num = 0.0, den = 0.0;
   for(int i = 0; i < period; i++)
   {
      double x = i;
      num += (x - xMean) * (Close[i] - yMean);
      den += (x - xMean) * (x - xMean);
   }
   if(den == 0.0) return 0.0;
   return num / den;
}

double LinearRegressionR2(int period)
{
   double xMean = (period - 1.0) / 2.0;
   double yMean = 0.0;
   for(int i = 0; i < period; i++) yMean += Close[i];
   yMean /= period;
   double ssTot = 0.0, ssRes = 0.0;
   double slope = LinearRegressionSlope(period);
   double intercept = yMean - slope * xMean;
   for(int i = 0; i < period; i++)
   {
      double yPred = slope * i + intercept;
      ssTot += (Close[i] - yMean) * (Close[i] - yMean);
      ssRes += (Close[i] - yPred) * (Close[i] - yPred);
   }
   if(ssTot == 0.0) return 0.0;
   return 1.0 - ssRes / ssTot;
}

void OnTick()
{
   if(!InTradeSession(TimeCurrent())) return;

   double atr = iATR(_Symbol, PERIOD_CURRENT, 14, 0);
   if(atr < MIN_ATR) return;

   double poc = GetSessionPOC(
      StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30"),
      StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 11:30")
   );
   double vwap = GetVWAP();
   if(poc <= 0.0) return;

   double anchor = (MathAbs(poc - vwap) / atr < 0.25) ? poc : vwap;
   double extension = MathAbs(Close[0] - anchor) / atr;
   if(extension < EXTENSION_ATR) return;

   double slope = LinearRegressionSlope(20);
   double r2 = LinearRegressionR2(20);
   double normSlope = MathAbs(slope) / atr;
   if(r2 > LR_R2_LIMIT && normSlope > LR_NORM_SLOPE_LIMIT) return;

   // Macro gate: if strongly inverse to DXY, do not trade against DXY momentum.
   double dxyBeta = iCustom(_Symbol, PERIOD_H1, "DXY_Beta", 0, 0);
   double dxyMom = iCustom(_Symbol, PERIOD_H1, "DXY_Momentum", 0, 0);
   if(dxyBeta < -0.75 && dxyMom > 0.0 && Close[0] > anchor) return; // block DE40 longs against dollar rally
   if(dxyBeta < -0.75 && dxyMom < 0.0 && Close[0] < anchor) return; // block DE40 shorts against dollar drop

   double sessionHigh = High[iHighest(_Symbol, PERIOD_CURRENT, MODE_HIGH, iBarShift(_Symbol, PERIOD_CURRENT, StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30"), false), 1)];
   double sessionLow  = Low[iLowest(_Symbol, PERIOD_CURRENT, MODE_LOW, iBarShift(_Symbol, PERIOD_CURRENT, StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30"), false), 1)];

   bool bearishSweep = (High[0] > sessionHigh && Close[0] < sessionHigh && Close[0] > anchor);
   bool bullishSweep = (Low[0] < sessionLow && Close[0] > sessionLow && Close[0] < anchor);

   bool bearishFVG = HasFVGAtPOC(false, anchor, atr);
   bool bullishFVG = HasFVGAtPOC(true, anchor, atr);

   if(bearishSweep && bearishFVG)
   {
      // Execute SELL: SL above sessionHigh, TP at anchor or next HVN/LVN target.
      OpenSellOrder();
   }
   else if(bullishSweep && bullishFVG)
   {
      // Execute BUY: SL below sessionLow, TP at anchor or next HVN/LVN target.
      OpenBuyOrder();
   }
}
