Replace the failed POC/VWAP fade with an Initial Balance Sweep + LVN-Embedded FVG Reversion. Use ADX<=20 as a hard regime gate, enforce 09:35-10:55 UTC entry window, require an IB high/low sweep with close back inside, and require a fresh FVG whose midpoint is inside an LVN between entry and the developing session POC. Rejection volume must be above its 20-bar average and spread must be <=15 points.

// MQL5 self-healing logic
input int    SESSION_START_HOUR    = 9;
input int    SESSION_START_MIN     = 30;
input int    BUFFER_MINUTES        = 5;
input int    IB_END_MINUTE         = 15;
input int    NO_NEW_ENTRY_HOUR     = 10;
input int    NO_NEW_ENTRY_MIN      = 55;
input double MIN_ATR               = 15.0;
input double MAX_SPREAD_POINTS     = 15;
input double ADX_MAX               = 20.0;
input double POC_MIGRATION_MAX_ATR = 0.25;
input double LVN_RATIO             = 0.30;
input double FVG_LVN_BAND_ATR      = 0.20;
input double SWEEP_WICK_ATR        = 0.20;
input double REJECT_BODY_ATR       = 0.10;
input double SL_ATR_MULT           = 1.2;
input double TP_ATR_MULT           = 2.0;

datetime SessionStart()
{
   return StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
}

bool InTradeWindow(datetime t)
{
   datetime noNew = StringToTime(TimeToString(t, TIME_DATE) + " 10:55");
   return (t >= SessionStart() + BUFFER_MINUTES * 60 && t < noNew);
}

double GetATR()
{
   return iATR(_Symbol, _Period, 14, 0);
}

double GetADX()
{
   return iADX(_Symbol, _Period, 14, PRICE_CLOSE, MODE_MAIN, 0);
}

double GetPOC(datetime start, datetime end)
{
   double poc[1];
   if(CopyBuffer(iCustom(_Symbol, _Period, "VolumeProfile", start, end), 0, 0, 1, poc) <= 0)
      return 0.0;
   return poc[0];
}

double GetVPVolumeAtPrice(datetime start, datetime end, double price)
{
   double vol[1];
   // VolumeProfile buffer 2 returns volume at the requested price.
   if(CopyBuffer(iCustom(_Symbol, _Period, "VolumeProfile", start, end, price), 2, 0, 1, vol) <= 0)
      return 1.0;
   return vol[0];
}

bool IsLVN(double price, double poc, datetime start, datetime end)
{
   double vPoc = GetVPVolumeAtPrice(start, end, poc);
   double vPrice = GetVPVolumeAtPrice(start, end, price);
   if(vPoc <= 0.0) return false;
   return (vPrice / vPoc < LVN_RATIO);
}

bool HasLVNBetween(double price, double poc, datetime start, datetime end)
{
   int steps = 10;
   for(int i = 1; i < steps; i++)
   {
      double level = price + (poc - price) * i / steps;
      if(IsLVN(level, poc, start, end))
         return true;
   }
   return false;
}

bool BullishFVG(int shift, double &mid)
{
   if(shift + 2 >= Bars(_Symbol, _Period)) return false;
   mid = (High[shift + 2] + Low[shift]) / 2.0;
   return (High[shift + 2] < Low[shift]);
}

bool BearishFVG(int shift, double &mid)
{
   if(shift + 2 >= Bars(_Symbol, _Period)) return false;
   mid = (Low[shift + 2] + High[shift]) / 2.0;
   return (Low[shift + 2] > High[shift]);
}

void OnTick()
{
   if(!InTradeWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   double adx = GetADX();
   if(adx > ADX_MAX) return;

   datetime s = SessionStart();
   datetime ibEnd = s + IB_END_MINUTE * 60;
   if(TimeCurrent() < ibEnd) return;

   double pocIB = GetPOC(s, ibEnd);
   double pocNow = GetPOC(s, TimeCurrent());
   if(pocIB <= 0.0 || pocNow <= 0.0) return;

   if(MathAbs(pocNow - pocIB) / atr > POC_MIGRATION_MAX_ATR) return;

   double ibHigh = -1e9, ibLow = 1e9;
   int startShift = iBarShift(_Symbol, _Period, ibEnd, false);
   int endShift   = iBarShift(_Symbol, _Period, s, false);

   for(int i = startShift; i <= endShift; i++)
   {
      if(High[i] > ibHigh) ibHigh = High[i];
      if(Low[i] < ibLow)   ibLow  = Low[i];
   }

   double volMA = iMA(_Symbol, _Period, 20, 0, MODE_SMA, VOLUME_TICK, 0);
   if(Volume[0] < volMA) return;

   double mid;

   // SELL: stop-hunt above IB high and close back inside with bearish FVG in LVN.
   if(High[0] > ibHigh && Close[0] < ibHigh && BearishFVG(1, mid))
   {
      if((High[0] - ibHigh) / atr < SWEEP_WICK_ATR) return;
      if((ibHigh - Close[0]) / atr < REJECT_BODY_ATR) return;

      bool lvnZone = IsLVN(mid, pocNow, s, TimeCurrent())
                     || HasLVNBetween(Close[0], pocNow, s, TimeCurrent());

      if(lvnZone && MathAbs(mid - Close[0]) / atr < FVG_LVN_BAND_ATR)
      {
         double sl = High[0] + SL_ATR_MULT * atr;
         double tp = MathMin(pocNow, Close[0] - TP_ATR_MULT * atr);
         // OpenSellOrder(sl, tp);
      }
   }

   // BUY: stop-hunt below IB low and close back inside with bullish FVG in LVN.
   if(Low[0] < ibLow && Close[0] > ibLow && BullishFVG(1, mid))
   {
      if((ibLow - Low[0]) / atr < SWEEP_WICK_ATR) return;
      if((Close[0] - ibLow) / atr < REJECT_BODY_ATR) return;

      bool lvnZone = IsLVN(mid, pocNow, s, TimeCurrent())
                     || HasLVNBetween(Close[0], pocNow, s, TimeCurrent());

      if(lvnZone && MathAbs(mid - Close[0]) / atr < FVG_LVN_BAND_ATR)
      {
         double sl = Low[0] - SL_ATR_MULT * atr;
         double tp = MathMax(pocNow, Close[0] + TP_ATR_MULT * atr);
         // OpenBuyOrder(sl, tp);
      }
   }
}

//| Module_1_DE40_VPPOC Self-Healing v1
//| Orthogonal entry: Prior-Day POC + Displacement FVG + Volume Climax + H1 Trend Alignment
input group "Module 1 DE40 VPPOC Self-Healing"
input int    SESSION_START_HOUR    = 9;
