input double POC_ALIGN_ATR         = 0.30;    // prior-day POC must agree with current VWAP
input int    MAX_FVG_AGE_BARS      = 12;       // M5 bars
input double FVG_POC_OVERLAP_ATR   = 0.25;    // FVG midpoint must sit near prior-day POC
input double DISPLACEMENT_ATR_MULT = 1.20;    // FVG origin must be a displacement candle
input double VOLUME_CLIMAX_MULT    = 1.40;    // retest bar must show stopping volume
input double STOP_ATR_MULT         = 1.20;
input double TARGET_ATR_MULT       = 0.80;

bool InTradeWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime noNew = StringToTime(TimeToString(t, TIME_DATE) + " 10:20");
   return (t >= start + OPENING_BUFFER_MIN * 60 && t < noNew);
}

double GetATR()
{
   double a[];
   if(CopyBuffer(iATR(_Symbol, PERIOD_CURRENT, 14), 0, 0, 1, a) <= 0) return 0.0;
   return a[0];
}

double GetVWAP()
{
   double v[];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VWAP"), 0, 0, 1, v) <= 0) return 0.0;
   return v[0];
