double GetPriorDayPOC(datetime t)
{
   datetime prevDay = t - PeriodSeconds(PERIOD_D1);
   datetime ps = StringToTime(TimeToString(prevDay, TIME_DATE) + " 08:00");
   datetime pe = StringToTime(TimeToString(prevDay, TIME_DATE) + " 16:30");
