double GetAverageVolume(int shift)
{
   double sum = 0.0;
   for(int i = shift; i < shift + 20; i++)
      sum += iVolume(_Symbol, PERIOD_CURRENT, i);
   return sum / 20.0;
}

bool H1BullishTrend()
{
   double e20_0 = iMA(_Symbol, PERIOD_H1, 20, 0, MODE_EMA, PRICE_CLOSE, 0);
   double e50_0 = iMA(_Symbol, PERIOD_H1, 50, 0, MODE_EMA, PRICE_CLOSE, 0);
   return (e20_0 > e50_0);
}

bool H1BearishTrend()
{
   double e20_0 = iMA(_Symbol, PERIOD_H1, 20, 0, MODE_EMA, PRICE_CLOSE, 0);
   double e50_0 = iMA(_Symbol, PERIOD_H1, 50, 0, MODE_EMA, PRICE_CLOSE, 0);
   return (e20_0 < e50_0);
}

bool IsDisplacementUp(int shift)
{
   double range = iHigh(_Symbol, PERIOD_CURRENT, shift) - iLow(_Symbol, PERIOD_CURRENT, shift);
   return (range >= DISPLACEMENT_ATR_MULT * GetATR());
}

bool IsDisplacementDown(int shift)
{
   double range = iHigh(_Symbol, PERIOD_CURRENT, shift) - iLow(_Symbol, PERIOD_CURRENT, shift);
   return (range >= DISPLACEMENT_ATR_MULT * GetATR());
}

bool HasValidBullishFVG(double priorPOC, double atr, double &mid)
{
   for(int i = 1; i <= MAX_FVG_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      double high2 = iHigh(_Symbol, PERIOD_CURRENT, i + 2);
      double low0  = iLow(_Symbol, PERIOD_CURRENT, i);
      if(high2 < low0 && IsDisplacementUp(i + 1))
      {
         mid = (high2 + low0) / 2.0;
         if(MathAbs(mid - priorPOC) / atr <= FVG_POC_OVERLAP_ATR) return true;
      }
   }
   return false;
}

bool HasValidBearishFVG(double priorPOC, double atr, double &mid)
{
   for(int i = 1; i <= MAX_FVG_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      double low2  = iLow(_Symbol, PERIOD_CURRENT, i + 2);
      double high0 = iHigh(_Symbol, PERIOD_CURRENT, i);
      if(low2 > high0 && IsDisplacementDown(i + 1))
      {
         mid = (low2 + high0) / 2.0;
         if(MathAbs(mid - priorPOC) / atr <= FVG_POC_OVERLAP_ATR) return true;
      }
   }
   return false;
}

bool DownsideVolumeClimax()
{
   double open1  = iOpen(_Symbol, PERIOD_CURRENT, 1);
   double close1 = iClose(_Symbol, PERIOD_CURRENT, 1);
   if(close1 >= open1) return false;
   double high1 = iHigh(_Symbol, PERIOD_CURRENT, 1);
   double low1  = iLow(_Symbol, PERIOD_CURRENT, 1);
   double avgV  = GetAverageVolume(1);
   double vol1  = iVolume(_Symbol, PERIOD_CURRENT, 1);
   if(vol1 < VOLUME_CLIMAX_MULT * avgV) return false;
   double lowerWick = MathMin(open1, close1) - low1;
   double upperWick = high1 - MathMax(open1, close1);
   return (lowerWick > upperWick * 1.5);
}

bool UpsideVolumeClimax()
{
   double open1  = iOpen(_Symbol, PERIOD_CURRENT, 1);
   double close1 = iClose(_Symbol, PERIOD_CURRENT, 1);
   if(close1 <= open1) return false;
   double high1 = iHigh(_Symbol, PERIOD_CURRENT, 1);
   double low1  = iLow(_Symbol, PERIOD_CURRENT, 1);
   double avgV  = GetAverageVolume(1);
   double vol1  = iVolume(_Symbol, PERIOD_CURRENT, 1);
   if(vol1 < VOLUME_CLIMAX_MULT * avgV) return false;
   double upperWick = high1 - MathMax(open1, close1);
   double lowerWick = MathMin(open1, close1) - low1;
   return (upperWick > lowerWick * 1.5);
}

void OnTick()
{
   if(!InTradeWindow(TimeCurrent())) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   double priorPOC = GetPriorDayPOC(TimeCurrent());
