      {
         double sl = priorPOC - STOP_ATR_MULT * atr;
         double tp = vwap + TARGET_ATR_MULT * atr;
         // ExecuteBuy(sl, tp);
      }
   }
   else if(H1BearishTrend() && HasValidBearishFVG(priorPOC, atr, fvgMid))
   {
      if(High[0] > fvgMid && Close[0] < fvgMid && Close[0] < Open[0] && UpsideVolumeClimax())
      {
         double sl = priorPOC + STOP_ATR_MULT * atr;
         double tp = vwap - TARGET_ATR_MULT * atr;
         // ExecuteSell(sl, tp);
      }
   }
}

Replace the current POC/VWAP fade with a Value-Area Exhaustion Reversion (VAER) logic. Preserve the validated 09:30 UTC opening buffer. The strategy now trades only in a balanced profile when the session POC is stable. It fades only beyond the session VAH/VAL edge, after a wick beyond that edge closes back toward the value area. It requires cumulative order-flow delta absorption: the current bar delta must oppose the prior 5-bar net delta. It uses FVG as a mitigation zone below/above the value-edge, not as a POC-overlap confirmation. A liquidity-volume ratio blocks entries when recent volume is below 75% of the opening anchor volume. MQL5:

input int    SESSION_START_HOUR  = 9;
input int    SESSION_START_MIN   = 30;
input int    BUFFER_MINUTES      = 5;
input int    SESSION_END_HOUR    = 11;
input int    SESSION_END_MIN     = 30;
input double MIN_ATR             = 15.0;
input double POC_STABILITY_ATR   = 0.10;
input double VALUE_EDGE_ATR      = 0.45;
input double ABSORPTION_RATIO    = 0.30;
input int    DELTA_LOOKBACK      = 5;
input int    FVG_MAX_AGE_BARS    = 12;
input double TP_ATR_MULT         = 1.5;
input double SL_ATR_MULT         = 0.8;
input double MIN_VOLUME_RATIO    = 0.75;

datetime sessionStart, sessionEnd;

bool InTradeWindow(datetime t)
{
   sessionStart = StringToTime(TimeToString(t, TIME_DATE) + "09:30");
   sessionEnd   = StringToTime(TimeToString(t, TIME_DATE) + "11:30");
   return (t >= sessionStart + BUFFER_MINUTES * 60 && t < sessionEnd);
}

double GetATR()
{
   double buf[1];
   ArraySetAsSeries(buf, true);
   if(CopyBuffer(iATR(_Symbol, PERIOD_CURRENT, 14), 0, 0, 1, buf) <= 0) return 0.0;
   return buf[0];
}

void GetValueArea(datetime start, datetime end, double &poc, double &vah, double &val)
{
   int h = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(h == INVALID_HANDLE) { poc = vah = val = 0.0; return; }
   double pocBuf[1], vahBuf[1], valBuf[1];
   ArraySetAsSeries(pocBuf, true);
   ArraySetAsSeries(vahBuf, true);
   ArraySetAsSeries(valBuf, true);
   if(CopyBuffer(h, 0, 0, 1, pocBuf) <= 0) poc = 0.0; else poc = pocBuf[0];
   if(CopyBuffer(h, 1, 0, 1, vahBuf) <= 0) vah = 0.0; else vah = vahBuf[0];
   if(CopyBuffer(h, 2, 0, 1, valBuf) <= 0) val = 0.0; else val = valBuf[0];
}

double GetDelta(int shift)
{
   int h = iCustom(_Symbol, PERIOD_CURRENT, "CumulativeDelta");
   if(h == INVALID_HANDLE) return 0.0;
   double buf[1];
   ArraySetAsSeries(buf, true);
   if(CopyBuffer(h, 0, shift, 1, buf) <= 0) return 0.0;
   return buf[0];
}

double SumDelta(int startShift, int count)
{
   double sum = 0.0;
   for(int i = startShift; i < startShift + count; i++) sum += GetDelta(i);
   return sum;
}

bool BullishFVG(int shift, double &mid)
{
   if(shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   if(High[shift + 2] < Low[shift])
   {
      mid = (High[shift + 2] + Low[shift]) / 2.0;
      return true;
   }
   return false;
}

bool BearishFVG(int shift, double &mid)
{
   if(shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   if(Low[shift + 2] > High[shift])
   {
      mid = (Low[shift + 2] + High[shift]) / 2.0;
      return true;
   }
   return false;
}

double AverageVolume(int startShift, int count)
{
   double sum = 0.0;
   for(int i = startShift; i < startShift + count; i++)
   {
      long vol = iVolume(_Symbol, PERIOD_CURRENT, i);
      sum += (double)vol;
   }
   return sum / count;
}

bool HasSufficientLiquidity()
{
   int barNow = iBarShift(_Symbol, PERIOD_CURRENT, TimeCurrent(), false);
   int barSession = iBarShift(_Symbol, PERIOD_CURRENT, sessionStart + BUFFER_MINUTES * 60, false);
   if(barSession < 12) return true;
   double recentVol = AverageVolume(barNow, 5);
   double anchorVol = AverageVolume(barSession, 10);
   if(anchorVol <= 0.0) return true;
   return (recentVol / anchorVol) >= MIN_VOLUME_RATIO;
}

void OnTick()
{
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);

   if(!InTradeWindow(TimeCurrent())) return;
   if(!HasSufficientLiquidity()) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   double pocNow, vahNow, valNow;
   GetValueArea(sessionStart, TimeCurrent(), pocNow, vahNow, valNow);
   if(pocNow <= 0.0 || vahNow <= 0.0 || valNow <= 0.0) return;

   double pocPrev, vahPrev, valPrev;
   GetValueArea(sessionStart, TimeCurrent() - 5 * PeriodSeconds(PERIOD_CURRENT), pocPrev, vahPrev, valPrev);
   if(pocPrev <= 0.0) return;

   double migration = (pocNow - pocPrev) / atr;
   if(MathAbs(migration) > POC_STABILITY_ATR) return;

   double lowerEdge = valNow - VALUE_EDGE_ATR * atr;
   double upperEdge = vahNow + VALUE_EDGE_ATR * atr;

   double delta0 = GetDelta(0);
   double prevDeltaSum = SumDelta(1, DELTA_LOOKBACK);

   bool longSetup = false;
   double sl = 0.0;
   double tp = 0.0;

   if(Low[0] < lowerEdge && Close[0] > lowerEdge && Close[0] > Open[0] && Close[0] < valNow)
   {
      bool absorption = (delta0 > 0 && prevDeltaSum < 0 && delta0 >= ABSORPTION_RATIO * MathAbs(prevDeltaSum));
      if(absorption)
      {
         for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
         {
            double mid = 0.0;
            if(BullishFVG(i, mid) && mid < lowerEdge)
            {
               if(Low[0] <= mid && Close[0] > mid)
               {
                  longSetup = true;
                  break;
               }
            }
         }
      }
      if(longSetup)
      {
         sl = Low[0] - SL_ATR_MULT * atr;
         tp = pocNow;
         // OpenBuyOrder(sl, tp);
      }
   }

   bool shortSetup = false;

   if(High[0] > upperEdge && Close[0] < upperEdge && Close[0] < Open[0] && Close[0] > vahNow)
   {
      bool absorption = (delta0 < 0 && prevDeltaSum > 0 && MathAbs(delta0) >= ABSORPTION_RATIO * prevDeltaSum);
      if(absorption)
      {
         for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
         {
            double mid = 0.0;
            if(BearishFVG(i, mid) && mid > upperEdge)
            {
               if(High[0] >= mid && Close[0] < mid)
               {
                  shortSetup = true;
                  break;
               }
            }
         }
      }
      if(shortSetup)
      {
         sl = High[0] + SL_ATR_MULT * atr;
         tp = pocNow;
         // OpenSellOrder(sl, tp);
      }
   }
}

// Module_1_DE40_VPPOC Self-Healing Logic
// Orthogonal alpha: trade only a true failed auction at POC extension, confirmed by volume surge and fresh FVG.
// Preserved validated brain fix: enforce 09:30 UTC opening buffer.
// Loss-cluster repair: no new entries after 10:30 UTC.
input int SESSION_START_HOUR = 9;
input int SESSION_START_MIN = 30;
input int OPENING_BUFFER_MINUTES = 5;
input int NO_NEW_HOUR = 10;
input int NO_NEW_MIN = 30;
input double MIN_ATR = 12.0;
input double MAX_SPREAD = 12.0;
input double POC_VWAP_ALIGN_ATR = 0.25;
input double MIN_EXT_ATR = 0.80;
input double MAX_EXT_ATR = 1.80;
input double REJECTION_BODY_ATR = 0.08;
input double REJECTION_WICK_ATR = 0.15;
input double FVG_ATR_MAX = 0.25;
input int FVG_MAX_AGE_BARS = 12;
input double ADX_MAX = 20.0;
input double LR_R2_MAX = 0.45;
input double SL_ATR_MULT = 0.8;
input double TP_ATR_MULT = 1.0;
input int REGRESSION_PERIOD = 20;
input double VOL_SURGE_RATIO = 1.5;
input string VP_NAME = "VolumeProfile";
input string VWAP_NAME = "VWAP";

bool InTradeWindow(datetime t)
{
   datetime day = t - t % 86400;
   datetime start = day + SESSION_START_HOUR * 3600 + SESSION_START_MIN * 60;
   datetime noNew = day + NO_NEW_HOUR * 3600 + NO_NEW_MIN * 60;
   return (t >= start + OPENING_BUFFER_MINUTES * 60 && t < noNew);
}

double GetATR()
{
   return iATR(_Symbol, _Period, 14, 0);
}

double LR_Slope(int period)
{
   double xMean = (period - 1.0) / 2.0;
   double yMean = 0.0;
   for(int i = 0; i < period; i++) yMean += Close[i];
   yMean /= period;
   double num = 0.0, den = 0.0;
   for(int i = 0; i < period; i++)
   {
      double x = i;
      num += (x - xMean) * (Close[i] - yMean);
      den += (x - xMean) * (x - xMean);
   }
   if(den == 0.0) return 0.0;
   return num / den;
}

double LR_R2(int period)
{
   double xMean = (period - 1.0) / 2.0;
   double yMean = 0.0;
   for(int i = 0; i < period; i++) yMean += Close[i];
   yMean /= period;
   double ssTot = 0.0, ssRes = 0.0;
   double slope = LR_Slope(period);
   double intercept = yMean - slope * xMean;
   for(int i = 0; i < period; i++)
   {
      double yPred = slope * i + intercept;
      ssTot += (Close[i] - yMean) * (Close[i] - yMean);
      ssRes += (Close[i] - yPred) * (Close[i] - yPred);
   }
   if(ssTot == 0.0) return 0.0;
   return 1.0 - ssRes / ssTot;
}

double GetSessionPOC(datetime start, datetime end)
{
   int h = iCustom(_Symbol, _Period, VP_NAME, start, end);
   double poc[1];
   if(CopyBuffer(h, 0, 0, 1, poc) <= 0) return EMPTY_VALUE;
   return poc[0];
}

double GetVWAP()
{
   int h = iCustom(_Symbol, _Period, VWAP_NAME);
   double vw[1];
   if(CopyBuffer(h, 0, 0, 1, vw) <= 0) return EMPTY_VALUE;
   return vw[0];
}

double GetAverageVolume(int lookback)
{
   double sum = 0.0;
   for(int i = 1; i <= lookback; i++) sum += (double)iVolume(_Symbol, _Period, i);
   if(lookback <= 0) return 0.0;
   return sum / lookback;
}

bool BullishFVG(int shift, double &mid)
{
   if(shift + 2 >= Bars(_Symbol, _Period)) return false;
   mid = (High[shift + 2] + Low[shift]) / 2.0;
   return (High[shift + 2] < Low[shift]);
}

bool BearishFVG(int shift, double &mid)
{
   if(shift + 2 >= Bars(_Symbol, _Period)) return false;
   mid = (Low[shift + 2] + High[shift]) / 2.0;
   return (Low[shift + 2] > High[shift]);
}

bool HasBullishFVGAtAnchor(double anchor, double atr)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      double mid = 0.0;
      if(BullishFVG(i, mid) && MathAbs(mid - anchor) / atr <= FVG_ATR_MAX)
         return true;
   }
   return false;
}

bool HasBearishFVGAtAnchor(double anchor, double atr)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      double mid = 0.0;
      if(BearishFVG(i, mid) && MathAbs(mid - anchor) / atr <= FVG_ATR_MAX)
         return true;
   }
   return false;
}

void OnTick()
{
   ArraySetAsSeries(Close, true);
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);

   datetime t = TimeCurrent();
   if(!InTradeWindow(t)) return;

   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   datetime day = t - t % 86400;
   datetime start = day + SESSION_START_HOUR * 3600 + SESSION_START_MIN * 60;

   double poc = GetSessionPOC(start, t);
   double vwap = GetVWAP();
   if(poc <= 0 || vwap <= 0) return;

   if(MathAbs(poc - vwap) / atr > POC_VWAP_ALIGN_ATR) return;
   double anchor = poc;

   double extension = MathAbs(Close[0] - anchor) / atr;
   if(extension < MIN_EXT_ATR || extension > MAX_EXT_ATR) return;

   double adx = iADX(_Symbol, _Period, 14, PRICE_CLOSE, MODE_MAIN, 0);
   double r2 = LR_R2(REGRESSION_PERIOD);
   if(adx > ADX_MAX || r2 > LR_R2_MAX) return;

   double avgVol = GetAverageVolume(20);
   double curVol = (double)iVolume(_Symbol, _Period, 0);
   if(curVol < VOL_SURGE_RATIO * avgVol) return;

   bool longReady = false;
   bool shortReady = false;

   double lowTrigger = anchor - MIN_EXT_ATR * atr;
   double highTrigger = anchor + MIN_EXT_ATR * atr;

   if(Low[0] <= lowTrigger && Close[0] > lowTrigger && Close[0] < anchor)
   {
      double body = Close[0] - Open[0];
      double lowerWick = Open[0] - Low[0];
      if(body > REJECTION_BODY_ATR * atr && lowerWick > REJECTION_WICK_ATR * atr)
         longReady = true;
   }

   if(High[0] >= highTrigger && Close[0] < highTrigger && Close[0] > anchor)
   {
      double body = Open[0] - Close[0];
      double upperWick = High[0] - Open[0];
      if(body > REJECTION_BODY_ATR * atr && upperWick > REJECTION_WICK_ATR * atr)
         shortReady = true;
   }

   if(longReady && HasBullishFVGAtAnchor(anchor, atr))
   {
      double sl = Low[0] - SL_ATR_MULT * atr;
      double tp = anchor + TP_ATR_MULT * atr * 0.5;
      // OpenBuyOrder(sl, tp);
   }
   else if(shortReady && HasBearishFVGAtAnchor(anchor, atr))
   {
      double sl = High[0] + SL_ATR_MULT * atr;
      double tp = anchor - TP_ATR_MULT * atr * 0.5;
      // OpenSellOrder(sl, tp);
   }
}

