double CumulativeDelta(int bars)
{
   double delta = 0.0;
   for(int i = 0; i < bars; i++)
   {
      double rng = High[i] - Low[i];
      if(rng <= 0) continue;
      double buyPct = 0.5;
      if(Close[i] > Open[i]) buyPct = 0.5 + 0.5 * (Close[i] - Open[i]) / rng;
      else if(Close[i] < Open[i]) buyPct = 0.5 - 0.5 * (Open[i] - Close[i]) / rng;
      delta += iVolume(_Symbol, PERIOD_M5, i) * (buyPct > 0.5 ? 1.0 : -1.0);
   }
   return delta;
}

