   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(Close, true);

   if(!InTradeWindow(TimeCurrent())) return;

   static int tradeDate = 0;
   static int tradeCount = 0;
   if(tradeDate != TimeDay(TimeCurrent()))
   {
      tradeDate = TimeDay(TimeCurrent());
      tradeCount = 0;
   }
   if(tradeCount >= InpMaxTradesPerDay) return;

   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > InpMaxSpreadPoints) return;

   double atr = GetATR();
   if(atr < InpMinATR) return;

   double adx = GetADX();
