      double tp = Close[0] - InpTP_ATR * atr;
      // OpenSellOrder(sl, tp);
      tradeCount++;
   }
}

Replace the static POC/VWAP fade with a 70% Value Area boundary rejection structural entry. Use tick-level volume aggregation to compute session POC/VAH/VAL, require a bullish FVG between VAL and POC for longs, and a bearish FVG between POC and VAH for shorts. Require a close back inside the value area after a wick through the boundary. Enforce the validated 09:30 opening buffer and stop new entries at 11:05 UTC to avoid the 11:00 loss cluster. Use a simple trend gate: if ADX > 20 and EMA20 > EMA50, only longs; if ADX > 20 and EMA20 < EMA50, only shorts; if ADX <= 20, allow both.

#property strict
#include <Trade\Trade.mqh>
CTrade trade;

input int    SESSION_START_HOUR = 9;
input int    SESSION_START_MIN  = 30;
input int    BUFFER_MINUTES     = 5;
input int    STOP_NEW_HOUR      = 11;
input int    STOP_NEW_MIN       = 5;
input double MIN_ATR            = 12.0;
input double VALUE_AREA_PCT     = 0.70;
input int    FVG_MAX_AGE_BARS   = 12;
input double SL_ATR_MULT        = 1.0;

bool InTradeWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime stopNew = StringToTime(TimeToString(t, TIME_DATE) + " 11:05");
   return (t >= start + BUFFER_MINUTES * 60 && t < stopNew);
}

bool GetSessionValueArea(datetime start, datetime end, double &poc, double &vah, double &val)
{
   MqlTick ticks[];
   int n = CopyTicksRange(_Symbol, ticks, COPY_TICKS_ALL, start * 1000, end * 1000);
   if(n <= 0) return false;
   double minPrice = DBL_MAX, maxPrice = -DBL_MAX;
   for(int i = 0; i < n; i++)
   {
      if(ticks[i].bid <= 0 || ticks[i].ask <= 0) continue;
      double p = (ticks[i].bid + ticks[i].ask) * 0.5;
      if(p < minPrice) minPrice = p;
      if(p > maxPrice) maxPrice = p;
   }
   if(minPrice >= maxPrice) return false;
   double step = _Point * 5;
   int levels = (int)((maxPrice - minPrice) / step) + 1;
   if(levels < 1) return false;
   double vol[];
   ArrayResize(vol, levels);
   ArrayInitialize(vol, 0.0);
   double totalVol = 0.0;
   for(int i = 0; i < n; i++)
   {
      if(ticks[i].bid <= 0 || ticks[i].ask <= 0) continue;
      double p = (ticks[i].bid + ticks[i].ask) * 0.5;
      int idx = (int)((p - minPrice) / step);
      if(idx < 0) idx = 0;
      if(idx >= levels) idx = levels - 1;
      double v = (ticks[i].volume_real > 0) ? ticks[i].volume_real : 1.0;
      vol[idx] += v;
      totalVol += v;
   }
   if(totalVol <= 0) return false;
   int pocIdx = 0;
   double maxVol = -1.0;
   for(int j = 0; j < levels; j++)
   {
      if(vol[j] > maxVol)
      {
         maxVol = vol[j];
         pocIdx = j;
      }
   }
   double target = VALUE_AREA_PCT * totalVol;
   double cum = vol[pocIdx];
   int lowIdx = pocIdx, highIdx = pocIdx;
   while(cum < target && (lowIdx > 0 || highIdx < levels - 1))
   {
      double nextLow = (lowIdx > 0) ? vol[lowIdx - 1] : -1.0;
      double nextHigh = (highIdx < levels - 1) ? vol[highIdx + 1] : -1.0;
      if(nextHigh >= nextLow && highIdx < levels - 1)
      {
         highIdx++;
         cum += vol[highIdx];
      }
      else if(lowIdx > 0)
      {
         lowIdx--;
         cum += vol[lowIdx];
      }
      else break;
   }
   poc = minPrice + (pocIdx + 0.5) * step;
   vah = minPrice + (highIdx + 0.5) * step;
   val = minPrice + (lowIdx + 0.5) * step;
   return true;
}

bool HasBullishFVGInsideVA(double val, double poc)
{
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      double fvg_lower = High[i + 2];
      double fvg_upper = Low[i];
      if(fvg_lower < fvg_upper)
      {
         double mid = (fvg_lower + fvg_upper) * 0.5;
         if(fvg_lower >= val && fvg_upper <= poc && mid > val && mid < poc)
            return true;
      }
   }
   return false;
}

bool HasBearishFVGInsideVA(double poc, double vah)
{
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      double fvg_lower = High[i];
      double fvg_upper = Low[i + 2];
      if(fvg_upper > fvg_lower)
      {
         double mid = (fvg_upper + fvg_lower) * 0.5;
         if(fvg_lower >= poc && fvg_upper <= vah && mid > poc && mid < vah)
            return true;
      }
   }
   return false;
}

void OnTick()
{
   if(!InTradeWindow(TimeCurrent())) return;
   double atr = iATR(_Symbol, PERIOD_CURRENT, 14, 0);
   if(atr < MIN_ATR) return;
   datetime start = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   double poc, vah, val;
   if(!GetSessionValueArea(start, TimeCurrent(), poc, vah, val)) return;

   double ema20 = iMA(_Symbol, PERIOD_CURRENT, 20, 0, MODE_EMA, PRICE_CLOSE, 0);
   double ema50 = iMA(_Symbol, PERIOD_CURRENT, 50, 0, MODE_EMA, PRICE_CLOSE, 0);
   double adx = iADX(_Symbol, PERIOD_CURRENT, 14, PRICE_CLOSE, MODE_MAIN, 0);

   bool trendUp = ema20 > ema50;
   bool trendDown = ema20 < ema50;
   bool choppy = adx <= 20;

   bool longSignal = false;
   bool shortSignal = false;

   if(choppy || trendUp)
   {
      bool valReject = (Low[0] < val && Close[0] > val && Close[0] > Open[0]);
      bool fvg = HasBullishFVGInsideVA(val, poc);
      longSignal = valReject && fvg;
   }

   if(choppy || trendDown)
   {
      bool vahReject = (High[0] > vah && Close[0] < vah && Close[0] < Open[0]);
      bool fvg = HasBearishFVGInsideVA(poc, vah);
      shortSignal = vahReject && fvg;
   }

   if(longSignal && shortSignal) return;

   if(longSignal)
   {
      double sl = val - SL_ATR_MULT * atr;
      double tp = poc;
      trade.Buy(0.01, _Symbol, 0, sl, tp, "DE40_VPPOC_VA_LONG");
   }
   else if(shortSignal)
   {
      double sl = vah + SL_ATR_MULT * atr;
      double tp = poc;
      trade.Sell(0.01, _Symbol, 0, sl, tp, "DE40_VPPOC_VA_SHORT");
   }
}

