double LinearRegressionFair(int period)
{
   double xMean = (period - 1.0) / 2.0;
   double yMean = 0.0;
   for(int i = 0; i < period; i++)
      yMean += Close[i];
   yMean /= period;

   double num = 0.0, den = 0.0;
   for(int i = 0; i < period; i++)
   {
      double x = i;
      num += (x - xMean) * (Close[i] - yMean);
      den += (x - xMean) * (x - xMean);
   }
   if(den == 0.0)
      return Close[0];
   double slope = num / den;
   double intercept = yMean - slope * xMean;
   return intercept + slope * 0.0;
}

bool FindExhaustionBullishFVG(double poc, double atr, double &mid)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      int i2 = i + 2;
      if(i2 >= Bars(_Symbol, PERIOD_CURRENT))
         break;
      if(High[i2] < Low[i])
      {
         mid = (High[i2] + Low[i]) / 2.0;
         if(poc - mid >= FVG_EXT_ATR * atr)
