bool BullishDeltaDivergence(int bars)
{
   double recent = 0.0, prior = 0.0;
   for(int i = 0; i < bars; i++) recent += CandleDelta(i + 1);
   for(int i = 0; i < bars; i++) prior  += CandleDelta(i + bars + 1);

   int recentLowIdx = iLowest(_Symbol, PERIOD_CURRENT, MODE_LOW, bars, 1);
   int priorLowIdx  = iLowest(_Symbol, PERIOD_CURRENT, MODE_LOW, bars, bars + 1);

   return (Low[recentLowIdx] < Low[priorLowIdx] && recent > prior);
}

bool BearishDeltaDivergence(int bars)
{
   double recent = 0.0, prior = 0.0;
   for(int i = 0; i < bars; i++) recent += CandleDelta(i + 1);
   for(int i = 0; i < bars; i++) prior  += CandleDelta(i + bars + 1);

   int recentHighIdx = iHighest(_Symbol, PERIOD_CURRENT, MODE_HIGH, bars, 1);
   int priorHighIdx  = iHighest(_Symbol, PERIOD_CURRENT, MODE_HIGH, bars, bars + 1);

   return (High[recentHighIdx] > High[priorHighIdx] && recent < prior);
