      Print("VPPOC short candidate: SL=", sl, " TP=", tp);
   }
   // Long: failed downside Value Area breakout
   else if(Low[0] < val - ext && Close[0] > val) {
      if(!ElevatedVolume(0, VOLUME_LOOKBACK)) return;
      if(DirectionalDelta(0) <= 0.0) return;
      if(!FreshBullishFVGAt(val, atr, sStart)) return;

      double sl = Low[0] - 0.75 * atr;
      double tp = vah - 0.5 * (vah - poc);
      // OpenBuyOrder(sl, tp);
      Print("VPPOC long candidate: SL=", sl, " TP=", tp);
   }
}

Replace the extension-fade logic with a POC retest rejection + delta absorption + VWAP fair value mitigation. Use a strict mean-reversion regime filter that blocks the exact losing-trade state (LR R²=0.25, ADX=22.0). Enforce the validated 09:30 UTC opening buffer. Add a dynamic liquidity clock to avoid illiquid hour clusters without a hard time cutoff.

input int   SESSION_START_HOUR    = 9;
input int   SESSION_START_MIN     = 30;
input int   OPENING_BUFFER_MIN    = 5;   // validated fix
input int   SESSION_END_HOUR      = 11;
input int   SESSION_END_MIN       = 30;
input int   ATR_PERIOD            = 14;
input int   REGIME_BARS           = 20;
input double MAX_LR_R2            = 0.20;
input double MAX_ADX              = 20.0;
input double MAX_POC_VWAP_ATR     = 0.35;
input double VWAP_SD_MULT         = 1.0;
input double MIN_VOL_MEDIAN_RATIO = 0.75;
input double SL_ATR_MULT          = 1.2;
input double TP_ATR_MULT          = 1.8;

void OnTick() {
   datetime t = TimeCurrent();
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");

   // Validated opening buffer
   if(t < start + OPENING_BUFFER_MIN*60 || t >= end) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > 15) return;

   double atr = iATR(_Symbol, PERIOD_CURRENT, ATR_PERIOD, 0);
   if(atr < 10.0) return;

   double r2 = LinearRegressionR2(REGIME_BARS);
   double adx = iADX(_Symbol, PERIOD_CURRENT, ATR_PERIOD, PRICE_CLOSE, MODE_MAIN, 0);

   // Blocks the historical losing-trade regime: R²=0.25, ADX=22.0
   if(r2 > MAX_LR_R2 || adx > MAX_ADX) return;

   double slope = LinearRegressionSlope(REGIME_BARS);
   if(MathAbs(slope) / atr > 0.10 && r2 > 0.10) return;

   // Dynamic liquidity clock: avoid statistically identified illiquid hour clusters
   int minutes = (int)((t - start) / 60);
   double medVol = GetMedianSessionVolumeAtMinute(minutes);
   if(GetCumulativeSessionVolume(start, t) < MIN_VOL_MEDIAN_RATIO * medVol) return;

   double poc  = GetAnchoredPOC(start, t);
   double vwap = GetVWAP();
   if(poc <= 0 || vwap <= 0) return;

   double vwap_sd = iCustom(_Symbol, PERIOD_CURRENT, "VWAP_StdDev", 0, 0);
   if(vwap_sd <= 0) return;

   // VWAP-POC convergence anchor, but do NOT use the debunked static 0.10/0.15 ATR FVG overlap
   double anchor = (MathAbs(poc - vwap) / atr <= MAX_POC_VWAP_ATR) ? (poc + vwap) / 2.0 : vwap;
   double lower_fair = vwap - VWAP_SD_MULT * vwap_sd;
   double upper_fair = vwap + VWAP_SD_MULT * vwap_sd;

   // POC/fair-value retest rejection, not an extension fade
   bool bullish_rejection = (Low[1] <= lower_fair && Close[1] > anchor);
   bool bearish_rejection = (High[1] >= upper_fair && Close[1] < anchor);

   // Delta absorption: net buying/selling pressure over last 3 bars
   double delta3 = GetDeltaSum(3);
   bool bull_delta = delta3 > 0;
   bool bear_delta = delta3 < 0;

   if(bullish_rejection && bull_delta) {
      OpenBuyOrder(anchor - SL_ATR_MULT * atr, anchor + TP_ATR_MULT * atr);
   } else if(bearish_rejection && bear_delta) {
      OpenSellOrder(anchor + SL_ATR_MULT * atr, anchor - TP_ATR_MULT * atr);
   }
}

Replace the old POC-extension/FVG-at-POC logic with a distributional HVN/LVN reversion engine. Enforce 09:30 UTC + 5 minute opening buffer. Only trade when ADX < 20, profile skew is low, volume participation is above 1.2x rolling average, and a bullish/bearish FVG appears fully outside the HVN and is then mitigated by a close back inside the HVN. Exact MQL5 skeleton:

input int    SESSION_START_HOUR   = 9;
input int    SESSION_START_MIN    = 30;
input int    BUFFER_MINUTES       = 5;
input int    SESSION_END_HOUR     = 11;
input int    SESSION_END_MIN      = 30;
input double MIN_ATR              = 12.0;
input double MAX_SPREAD_POINTS    = 15;
input double HVN_PEAK_FRACTION    = 0.70;
input double SKEW_LIMIT           = 0.20;
input double MIN_VOLUME_RATIO     = 1.20;
input int    FVG_MAX_AGE_BARS     = 12;
input double SL_ATR_MULT          = 0.50;

bool InTradeWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + BUFFER_MINUTES * 60 && t < end);
}

double GetATR(){ return iATR(_Symbol, PERIOD_CURRENT, 14, 0); }

bool GetProfileMetrics(datetime start, datetime end,
                       double &poc, double &hvHigh, double &hvLow, double &skew)
{
   double arr[5];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end),
                  0, 0, 5, arr) <= 0) return false;
   poc=arr[0]; hvHigh=arr[2]; hvLow=arr[3]; skew=arr[4];
   return true;
}

double VolumeRatio()
{
   double v = (double)iVolume(_Symbol, PERIOD_CURRENT, 0);
   double ma = iMA(_Symbol, PERIOD_CURRENT, 20, 0, MODE_SMA, VOLUME_TICK, 0);
   if(ma <= 0.0) return 0.0;
   return v / ma;
}

bool BullishFVG(int shift, double &mid, double &fvgLow, double &fvgHigh)
{
   if(shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   fvgHigh = Low[shift];
   fvgLow  = High[shift + 2];
   mid = (fvgHigh + fvgLow) / 2.0;
   return (High[shift + 2] < Low[shift]);
}

bool BearishFVG(int shift, double &mid, double &fvgLow, double &fvgHigh)
{
   if(shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   fvgLow  = High[shift];
   fvgHigh = Low[shift + 2];
   mid = (fvgLow + fvgHigh) / 2.0;
   return (Low[shift + 2] > High[shift]);
}

void OnTick()
{
   ArraySetAsSeries(Close, true);
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Time, true);

   if(!InTradeWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   double adx = iADX(_Symbol, PERIOD_CURRENT, 14, PRICE_CLOSE, MODE_MAIN, 0);
   if(adx >= 20.0) return;

   if(VolumeRatio() < MIN_VOLUME_RATIO) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   double poc, hvHigh, hvLow, skew;
   if(!GetProfileMetrics(sessionStart, TimeCurrent(), poc, hvHigh, hvLow, skew)) return;
   if(MathAbs(skew) > SKEW_LIMIT) return;

   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      double mid, fvgLow, fvgHigh;
      if(BullishFVG(i, mid, fvgLow, fvgHigh))
      {
         if(fvgHigh >= hvLow) continue;
         if(MathAbs(Close[0] - mid) / atr > 0.50) continue;
         if(Close[0] > hvLow && Low[0] <= hvLow && Close[0] > mid && Close[0] > Open[0])
         {
            double sl = fvgLow - SL_ATR_MULT * atr;
            double tp1 = poc;
            double tp2 = hvHigh;
            // OpenBuyOrder(sl, tp1, tp2);
            return;
         }
      }
   }

   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      double mid, fvgLow, fvgHigh;
      if(BearishFVG(i, mid, fvgLow, fvgHigh))
      {
         if(fvgLow <= hvHigh) continue;
         if(MathAbs(Close[0] - mid) / atr > 0.50) continue;
         if(Close[0] < hvHigh && High[0] >= hvHigh && Close[0] < mid && Close[0] < Open[0])
         {
            double sl = fvgHigh + SL_ATR_MULT * atr;
            double tp1 = poc;
            double tp2 = hvLow;
            // OpenSellOrder(sl, tp1, tp2);
            return;
         }
      }
   }
}

#property strict

input int    SESSION_START_HOUR   = 9;
input int    SESSION_START_MIN    = 30;
input int    BUFFER_MINUTES       = 5;    // HIGH-CONFIDENCE VALIDATED FIX
input int    SESSION_END_HOUR     = 11;
input int    SESSION_END_MIN      = 30;
input double MIN_ATR              = 14.0;
input double VPOC_DISPERSION_ATR  = 0.40; // max VPOC migration over 6 bars in ATR
input double VPOC_STABILITY_ATR   = 0.12; // max VPOC acceleration in ATR
input double FVG_EDGE_OVERLAP_ATR = 0.10;
input int    FVG_MAX_AGE_BARS     = 6;    // only fresh imbalances
input double MIN_VOLUME_RATIO     = 1.25; // current bar tick volume vs previous 5
input double MAX_SPREAD_POINTS    = 15.0;
input int    MIN_MINUTES_BETWEEN_ENTRIES = 30; // prevents cluster repetition

bool InTradeWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + BUFFER_MINUTES * 60 && t < end);
}

double GetProfileBuffer(datetime start, datetime end, int bufferIndex)
{
   double buf[1];
   ArraySetAsSeries(buf, true);
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end), bufferIndex, 0, 1, buf) <= 0)
      return 0.0;
   return buf[0];
}

double GetPOCAtBar(datetime start, datetime now, int barShift)
{
   datetime end = now - barShift * PeriodSeconds(PERIOD_CURRENT);
   return GetProfileBuffer(start, end, 0); // buffer 0 = POC
}

double GetValueAreaHigh(datetime start, datetime now)
{
   return GetProfileBuffer(start, now, 1); // buffer 1 = VAH
}

double GetValueAreaLow(datetime start, datetime now)
{
   return GetProfileBuffer(start, now, 2); // buffer 2 = VAL
}

bool IsVolumeExpanding()
{
   double cur = iVolume(_Symbol, PERIOD_CURRENT, 0);
   double prevSum = 0.0;
   for(int i = 1; i <= 5; i++)
      prevSum += iVolume(_Symbol, PERIOD_CURRENT, i);
   double prevAvg = prevSum / 5.0;
   if(prevAvg <= 0.0) return false;
   return (cur > MIN_VOLUME_RATIO * prevAvg);
}

bool BullishFVGAtEdge(double edgePrice, double atr)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(High[i + 2] < Low[i])
      {
         double mid = (High[i + 2] + Low[i]) / 2.0;
         if(MathAbs(mid - edgePrice) / atr <= FVG_EDGE_OVERLAP_ATR)
            return true;
      }
   }
   return false;
}

bool BearishFVGAtEdge(double edgePrice, double atr)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Low[i + 2] > High[i])
      {
         double mid = (Low[i + 2] + High[i]) / 2.0;
         if(MathAbs(mid - edgePrice) / atr <= FVG_EDGE_OVERLAP_ATR)
            return true;
      }
   }
   return false;
}

void OnTick()
{
   static bool arraysReady = false;
   if(!arraysReady)
   {
      ArraySetAsSeries(Open, true);
      ArraySetAsSeries(High, true);
      ArraySetAsSeries(Low, true);
      ArraySetAsSeries(Close, true);
      arraysReady = true;
   }

   if(!InTradeWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;
   if(PositionSelect(_Symbol)) return; // only one open position per symbol

   static datetime lastEntryTime = 0;
   if(TimeCurrent() - lastEntryTime < MIN_MINUTES_BETWEEN_ENTRIES * 60) return;

   double atr = iATR(_Symbol, PERIOD_CURRENT, 14, 0);
   if(atr < MIN_ATR) return;

   datetime start = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   datetime now = TimeCurrent();

   double poc0 = GetPOCAtBar(start, now, 0);
   double poc3 = GetPOCAtBar(start, now, 3);
   double poc6 = GetPOCAtBar(start, now, 6);
   if(poc0 <= 0.0 || poc3 <= 0.0 || poc6 <= 0.0) return;

   // VPOC must have migrated only modestly and must not be accelerating.
   double migration6    = MathAbs(poc0 - poc6) / atr;
   double acceleration  = MathAbs((poc0 - poc3) - (poc3 - poc6)) / atr;
   if(migration6 > VPOC_DISPERSION_ATR || acceleration > VPOC_STABILITY_ATR) return;

   double vah = GetValueAreaHigh(start, now);
   double val = GetValueAreaLow(start, now);
   if(vah <= 0.0 || val <= 0.0) return;

   if(!IsVolumeExpanding()) return;

   bool longReentry  = (Low[0] < val  && Close[0] > val  && Close[0] <= poc0);
   bool shortReentry = (High[0] > vah && Close[0] < vah && Close[0] >= poc0);

   if(longReentry && BullishFVGAtEdge(val, atr))
   {
      double sl = val - 0.5 * atr;
      double tp = poc0;
      lastEntryTime = TimeCurrent();
      // OpenLongOrder(sl, tp);
   }
   else if(shortReentry && BearishFVGAtEdge(vah, atr))
   {
      double sl = vah + 0.5 * atr;
      double tp = poc0;
      lastEntryTime = TimeCurrent();
      // OpenShortOrder(sl, tp);
   }
}

