bool InOpeningLiquidityWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 10:30");
   return (t >= start + BUFFER_MINUTES * 60 && t < end);
}

double GetATR()
{
   return iATR(_Symbol, PERIOD_CURRENT, 14, 0);
}

double GetSessionPOC(datetime start, datetime end)
{
   double poc[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end), 0, 0, 1, poc) <= 0)
      return 0.0;
   return poc[0];
}

bool BullishFVG(int shift)
{
   return (High[shift + 2] < Low[shift]);
}

bool BearishFVG(int shift)
{
   return (Low[shift + 2] > High[shift]);
}

bool BullishFVGSpansPOC(int shift, double poc)
{
   if(!BullishFVG(shift)) return false;
   double gapLow = High[shift + 2];
   double gapHigh = Low[shift];
   return (gapLow <= poc && poc <= gapHigh);
}

bool BearishFVGSpansPOC(int shift, double poc)
{
   if(!BearishFVG(shift)) return false;
   double gapLow = High[shift];
   double gapHigh = Low[shift + 2];
   return (gapLow <= poc && poc <= gapHigh);
}

bool IsBullishStructure()
{
   return (High[1] > High[3] && Low[1] > Low[3] && High[2] > High[4] && Low[2] > Low[4]);
}

bool IsBearishStructure()
{
   return (High[1] < High[3] && Low[1] < Low[3] && High[2] < High[4] && Low[2] < Low[4]);
}

void OnTick()
{
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);

   if(!InOpeningLiquidityWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   double pocNow = GetSessionPOC(sessionStart, TimeCurrent());
   if(pocNow <= 0.0) return;

   double pocRef = GetSessionPOC(sessionStart, TimeCurrent() - POC_STATIONARITY_BARS * PeriodSeconds(PERIOD_CURRENT));
   if(pocRef <= 0.0) return;
   if(MathAbs(pocNow - pocRef) / atr > POC_STATIONARITY_ATR) return;

   bool bullishStruct = IsBullishStructure();
   bool bearishStruct = IsBearishStructure();
   if(!bullishStruct && !bearishStruct) return;

   bool bullishSpanFVG = false;
   bool bearishSpanFVG = false;
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(BullishFVGSpansPOC(i, pocNow)) bullishSpanFVG = true;
      if(BearishFVGSpansPOC(i, pocNow)) bearishSpanFVG = true;
   }

   if(bullishStruct && !bullishSpanFVG) return;
   if(bearishStruct && !bearishSpanFVG) return;

   if(bullishStruct && bullishSpanFVG)
   {
      if(Low[0] <= pocNow && Close[0] > pocNow && Close[0] > Open[0])
      {
         double lowerWick = MathMin(Open[0], Close[0]) - Low[0];
         if(lowerWick < REJECTION_WICK_ATR * atr) return;
         double sl = pocNow - SL_ATR_MULT * atr;
         double tp = Close[0] + TP_ATR_MULT * atr;
         // OpenBuyOrder(sl, tp);
      }
   }
   else if(bearishStruct && bearishSpanFVG)
   {
      if(High[0] >= pocNow && Close[0] < pocNow && Close[0] < Open[0])
      {
         double upperWick = High[0] - MathMax(Open[0], Close[0]);
         if(upperWick < REJECTION_WICK_ATR * atr) return;
         double sl = pocNow + SL_ATR_MULT * atr;
         double tp = Close[0] - TP_ATR_MULT * atr;
         // OpenSellOrder(sl, tp);
      }
   }
}

Replace the old POC/VWAP distance fade with a Value Area Tail Reversion + Cumulative Volume Delta Absorption + FVG-at-Value-Boundary structure. This is not a parameter tweak; it changes the entry from 'far from POC' to 'failed auction outside the value area, confirmed by delta exhaustion and an unmitigated FVG'. Exact MQL5 logic:

// Module_1_DE40_VPPOC - Healed: Value Area Tail Reversion + Delta Absorption
input int    SESSION_START_HOUR   = 9;
input int    SESSION_START_MIN    = 30;
input int    SESSION_END_HOUR     = 11;
