bool GetValueArea(datetime start, datetime end, double &poc, double &vah, double &val)
{
   // Assumes custom VolumeProfile indicator buffers: 0 = POC, 1 = VAH, 2 = VAL
   int h = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   double bufPoc[1], bufVah[1], bufVal[1];
   ResetLastError();
   if(CopyBuffer(h, 0, 0, 1, bufPoc) <= 0) return false;
   if(CopyBuffer(h, 1, 0, 1, bufVah) <= 0) return false;
   if(CopyBuffer(h, 2, 0, 1, bufVal) <= 0) return false;
   poc = bufPoc[0];
   vah = bufVah[0];
   val = bufVal[0];
   return (poc > 0.0 && vah > val);
}

bool POCStable(datetime sessionStart, double atr)
{
   datetime t1 = TimeCurrent();
   datetime t0 = t1 - 15*60;
   double pocNow = 0.0, pocPrev = 0.0, dummy1 = 0.0, dummy2 = 0.0;
   if(!GetValueArea(sessionStart, t1, pocNow, dummy1, dummy2)) return false;
   if(!GetValueArea(sessionStart, t0, pocPrev, dummy1, dummy2)) return false;
