double CVD(int startShift, int bars)
{
   double cvd = 0.0;
   for(int i = startShift; i < startShift + bars; i++)
   {
      if(i >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Close[i] > Open[i])
