   if(leg * 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   double cvd1 = CVD(1, leg);
   double cvd2 = CVD(leg + 1, leg);
   int low1Idx = iLowest(_Symbol, PERIOD_CURRENT, MODE_LOW, leg, 1);
   int low2Idx = iLowest(_Symbol, PERIOD_CURRENT, MODE_LOW, leg, leg + 1);
   double low1 = Low[low1Idx];
   double low2 = Low[low2Idx];
   return (low1 < low2 && cvd1 > cvd2);
}

bool BearishCVDDivergence()
{
   int leg = CVD_LEG_BARS;
   if(leg * 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   double cvd1 = CVD(1, leg);
   double cvd2 = CVD(leg + 1, leg);
   int high1Idx = iHighest(_Symbol, PERIOD_CURRENT, MODE_HIGH, leg, 1);
   int high2Idx = iHighest(_Symbol, PERIOD_CURRENT, MODE_HIGH, leg, leg + 1);
   double high1 = High[high1Idx];
   double high2 = High[high2Idx];
   return (high1 > high2 && cvd1 < cvd2);
}

void OnTick()
{
   ArraySetAsSeries(Close, true);
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
