      bool tailSweep = (High[1] > vah + VA_TAIL_ATR * atr && Close[0] < vah);
      if(tailSweep && BearishFVGInZone(vah, atr) && BearishCVDDivergence())
      {
         double sl = High[1] + 0.20 * atr;
         double tp = poc;
         // OpenSellOrder(sl, tp);
      }
   }
}

Replace the static extension fade with an Auction Escape-Return repair. Enforce the validated 09:30 UTC opening buffer. Dynamically block low-liquidity bars using tick-volume ratio. Compute the anchored session VPOC and VWAP; if they diverge by more than 0.25 ATR, use the VPOC as the anchor. Require price to have escaped the anchor by at least 1.0 ATR on the previous bar, then return into the anchor zone on the current bar. Entry is only on a rejection candle that closes back through the anchor: for longs, Low[0] < anchor and Close[0] > anchor with Close[0] > Open[0]; for shorts, High[0] > anchor and Close[0] < anchor with Close[0] < Open[0]. Current tick volume must be at least 1.5x the 20-bar average. Fair Value Mitigation is required as a fresh unmitigated FVG (<24 bars old) within 1.0 ATR of the anchor that is filled on the same retest. No fade is taken simply because price is far from POC. Stop-loss is beyond the rejection candle extreme; take-profit is 2.0 ATR from the anchor.

MQL5 logic:

input double MIN_ATR = 12.0;
input double MIN_VOL_RATIO = 0.60;
input double REJECTION_VOL_RATIO = 1.5;
input double RETURN_EXT_ATR = 1.0;
input double POC_ZONE_ATR = 0.25;
input int FVG_MAX_AGE_BARS = 24;

bool InTradeSession(datetime t) {
 datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
 datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
 return (t >= start + 300 && t < end);
}

double GetATR() {
 double arr[1];
 if(CopyBuffer(iATR(_Symbol, PERIOD_CURRENT, 14), 0, 0, 1, arr) <= 0) return 0.0;
 return arr[0];
}

double GetSessionPOC(datetime start, datetime end) {
 double poc[1];
 int h = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
 if(h == INVALID_HANDLE) return 0.0;
 if(CopyBuffer(h, 0, 0, 1, poc) <= 0) return 0.0;
 return poc[0];
}

double GetVWAP() {
 double vwap[1];
 int h = iCustom(_Symbol, PERIOD_CURRENT, "VWAP");
 if(h == INVALID_HANDLE) return 0.0;
 if(CopyBuffer(h, 0, 0, 1, vwap) <= 0) return 0.0;
 return vwap[0];
}

double CurrentVolumeRatio() {
 double avg = 0.0;
 for(int i = 1; i <= 20; i++) avg += iVolume(_Symbol, PERIOD_CURRENT, i);
 avg /= 20.0;
 if(avg <= 0.0) return 0.0;
 return iVolume(_Symbol, PERIOD_CURRENT, 0) / avg;
}

bool HasFreshBullishFVG(double anchor, double atr) {
 for(int i = 1; i < FVG_MAX_AGE_BARS; i++) {
  if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
  if(High[i + 2] < Low[i]) {
   double mid = (High[i + 2] + Low[i]) / 2.0;
   if(MathAbs(mid - anchor) / atr > 1.0) continue;
   if(Low[0] <= mid && Close[0] > anchor) return true;
  }
 }
 return false;
}

bool HasFreshBearishFVG(double anchor, double atr) {
 for(int i = 1; i < FVG_MAX_AGE_BARS; i++) {
  if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
  if(Low[i + 2] > High[i]) {
   double mid = (Low[i + 2] + High[i]) / 2.0;
   if(MathAbs(mid - anchor) / atr > 1.0) continue;
   if(High[0] >= mid && Close[0] < anchor) return true;
  }
 }
 return false;
}

void OnTick() {
 if(!InTradeSession(TimeCurrent())) return;
 double atr = GetATR();
 if(atr < MIN_ATR) return;
 if(CurrentVolumeRatio() < MIN_VOL_RATIO) return;

 datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
 double poc = GetSessionPOC(sessionStart, TimeCurrent());
 double vwap = GetVWAP();
 if(poc <= 0.0 || vwap <= 0.0) return;

 double anchor = (MathAbs(poc - vwap) / atr < 0.25) ? poc : vwap;
 double prevExt = (Close[1] - anchor) / atr;
 double currExt = (Close[0] - anchor) / atr;
 double volRatio = CurrentVolumeRatio();

 bool longSetup = (prevExt < -RETURN_EXT_ATR)
               && (MathAbs(currExt) <= POC_ZONE_ATR)
               && Low[0] < anchor
               && Close[0] > anchor
               && Close[0] > Open[0]
               && volRatio >= REJECTION_VOL_RATIO
               && HasFreshBullishFVG(anchor, atr);

 bool shortSetup = (prevExt > RETURN_EXT_ATR)
               && (MathAbs(currExt) <= POC_ZONE_ATR)
               && High[0] > anchor
               && Close[0] < anchor
               && Close[0] < Open[0]
               && volRatio >= REJECTION_VOL_RATIO
               && HasFreshBearishFVG(anchor, atr);

 if(longSetup) {
  double sl = Low[0] - 1.5 * atr;
  double tp = anchor + 2.0 * atr;
  // OpenBuyOrder(sl, tp);
 }
 if(shortSetup) {
  double sl = High[0] + 1.5 * atr;
  double tp = anchor - 2.0 * atr;
  // OpenSellOrder(sl, tp);
 }
}

input int    SESSION_START_HOUR   = 9;
input int    SESSION_START_MIN    = 30;
input int    BUFFER_MINUTES       = 5;
input int    SESSION_END_HOUR     = 11;
input int    SESSION_END_MIN      = 30;
input double MIN_ATR              = 12.0;
input double DISPLACEMENT_BODY_ATR = 0.8;
input double FVG_POC_ALIGN_ATR   = 0.35;
input double RETEST_TOLERANCE_ATR = 0.25;
input double SL_ATR_MULT          = 0.8;
input double TP_ATR_MULT          = 1.2;
input int    VOLUME_AVG_PERIOD    = 20;
input double MIN_PARTICIPATION_RATIO = 0.65;

double GetATR() { return iATR(_Symbol, PERIOD_CURRENT, 14, 0); }

double GetVolumeParticipationRatio() {
   double v0 = iVolume(_Symbol, PERIOD_CURRENT, 0);
   double avg = 0.0;
   for(int i=1; i<=VOLUME_AVG_PERIOD; i++) avg += iVolume(_Symbol, PERIOD_CURRENT, i);
   avg /= VOLUME_AVG_PERIOD;
   if(avg <= 0.0) return 0.0;
   return v0 / avg;
}

double GetReclaimVolumeRatio() {
   double v1 = iVolume(_Symbol, PERIOD_CURRENT, 1);
   double avg = 0.0;
   for(int i=1; i<=VOLUME_AVG_PERIOD; i++) avg += iVolume(_Symbol, PERIOD_CURRENT, i);
   avg /= VOLUME_AVG_PERIOD;
   if(avg <= 0.0) return 0.0;
   return v1 / avg;
}

double GetSessionPOC() {
   datetime sessionStart = StringToTime(StringFormat("%04d.%02d.%02d %02d:%02d", TimeYear(TimeCurrent()), TimeMonth(TimeCurrent()), TimeDay(TimeCurrent()), SESSION_START_HOUR, SESSION_START_MIN));
   datetime sessionEnd   = StringToTime(StringFormat("%04d.%02d.%02d %02d:%02d", TimeYear(TimeCurrent()), TimeMonth(TimeCurrent()), TimeDay(TimeCurrent()), SESSION_END_HOUR, SESSION_END_MIN));
   double poc[];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", sessionStart, sessionEnd), 0, 0, 1, poc) <= 0) return 0.0;
   return poc[0];
}

bool InTradeWindow() {
   datetime sessionStart = StringToTime(StringFormat("%04d.%02d.%02d %02d:%02d", TimeYear(TimeCurrent()), TimeMonth(TimeCurrent()), TimeDay(TimeCurrent()), SESSION_START_HOUR, SESSION_START_MIN));
   datetime sessionEnd   = StringToTime(StringFormat("%04d.%02d.%02d %02d:%02d", TimeYear(TimeCurrent()), TimeMonth(TimeCurrent()), TimeDay(TimeCurrent()), SESSION_END_HOUR, SESSION_END_MIN));
   return (TimeCurrent() >= sessionStart + BUFFER_MINUTES*60 && TimeCurrent() < sessionEnd);
}

bool FreshBullishFVGNearPOC(double poc, double atr, double &mid) {
   for(int i=1; i<=4; i++) {
      double high_i2 = iHigh(_Symbol, PERIOD_CURRENT, i+2);
      double low_i   = iLow(_Symbol, PERIOD_CURRENT, i);
      if(high_i2 < low_i) {
         mid = (high_i2 + low_i) / 2.0;
         if(MathAbs(mid - poc) / atr <= FVG_POC_ALIGN_ATR) return true;
      }
   }
   return false;
}

bool FreshBearishFVGNearPOC(double poc, double atr, double &mid) {
   for(int i=1; i<=4; i++) {
      double low_i2  = iLow(_Symbol, PERIOD_CURRENT, i+2);
      double high_i  = iHigh(_Symbol, PERIOD_CURRENT, i);
      if(low_i2 > high_i) {
         mid = (low_i2 + high_i) / 2.0;
         if(MathAbs(mid - poc) / atr <= FVG_POC_ALIGN_ATR) return true;
      }
   }
   return false;
}

void OnTick() {
   if(!InTradeWindow()) return;
   if(GetVolumeParticipationRatio() < MIN_PARTICIPATION_RATIO) return;
   if(GetReclaimVolumeRatio() < 0.8) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;
   double poc = GetSessionPOC();
   if(poc <= 0.0) return;

   double c0 = iClose(_Symbol, PERIOD_CURRENT, 0);
   double o1 = iOpen(_Symbol, PERIOD_CURRENT, 1);
   double c1 = iClose(_Symbol, PERIOD_CURRENT, 1);
   double c2 = iClose(_Symbol, PERIOD_CURRENT, 2);
   double l1 = iLow(_Symbol, PERIOD_CURRENT, 1);
   double h1 = iHigh(_Symbol, PERIOD_CURRENT, 1);

   double fvgMid = 0.0;

   // LONG: POC reclaimed from below by a bullish displacement candle, now pullback into fresh FVG.
   if(c2 < poc && c1 > poc && c1 > o1 && (c1 - o1) >= DISPLACEMENT_BODY_ATR * atr) {
      if(FreshBullishFVGNearPOC(poc, atr, fvgMid)) {
         if(MathAbs(c0 - fvgMid) <= RETEST_TOLERANCE_ATR * atr && c0 > fvgMid) {
            double entry = SymbolInfoDouble(_Symbol, SYMBOL_ASK);
            double sl = l1 - SL_ATR_MULT * atr;
            double tp = entry + TP_ATR_MULT * atr;
            // OpenBuyOrder(entry, sl, tp);
            return;
         }
      }
   }

   // SHORT: POC rejected from above by a bearish displacement candle, now pullback into fresh FVG.
   if(c2 > poc && c1 < poc && c1 < o1 && (o1 - c1) >= DISPLACEMENT_BODY_ATR * atr) {
      if(FreshBearishFVGNearPOC(poc, atr, fvgMid)) {
         if(MathAbs(c0 - fvgMid) <= RETEST_TOLERANCE_ATR * atr && c0 < fvgMid) {
            double entry = SymbolInfoDouble(_Symbol, SYMBOL_BID);
            double sl = h1 + SL_ATR_MULT * atr;
            double tp = entry - TP_ATR_MULT * atr;
            // OpenSellOrder(entry, sl, tp);
            return;
         }
      }
   }
}

// Module_1_DE40_VPPOC - Auction Rotation Reversion with Value Area and Delta Absorption
// Distinct from debunked failures: no 2 ATR simple fade, no FVG-POC overlap, no OBV/MFI, no VPOC migration, no hard session cutoff after 10:30.

input int    SESSION_START_HOUR   = 9;
input int    SESSION_START_MIN    = 30;
input int    BUFFER_MINUTES       = 5;
input int    SESSION_END_HOUR     = 11;
input int    SESSION_END_MIN      = 30;
input double MIN_ATR              = 10.0;
input double POC_VWAP_ALIGN_ATR   = 0.10;
input double ENTRY_EXT_MIN_ATR    = 0.60;
input double ENTRY_EXT_MAX_ATR    = 1.40;
input double VOLUME_PARTICIPATION_RATIO = 0.60;
input int    VOLUME_SHORT_BARS    = 15;
input int    VOLUME_BASELINE_BARS = 75;
input int    FVG_MAX_AGE_BARS     = 12;
input double MAX_SPREAD_POINTS    = 10.0;

bool InTradeSession(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + BUFFER_MINUTES * 60 && t < end);
}

double GetATR()
{
   double buf[];
   ArraySetAsSeries(buf, true);
   if(CopyBuffer(iATR(_Symbol, PERIOD_CURRENT, 14), 0, 1, buf) <= 0) return 0.0;
   return buf[0];
}

bool HasAdequateLiquidity()
{
   double short_sum = 0.0, baseline_sum = 0.0;
   for(int i = 0; i < VOLUME_SHORT_BARS; i++)
      short_sum += iVolume(_Symbol, PERIOD_CURRENT, i);
   for(int i = VOLUME_SHORT_BARS; i < VOLUME_SHORT_BARS + VOLUME_BASELINE_BARS; i++)
      baseline_sum += iVolume(_Symbol, PERIOD_CURRENT, i);
   if(baseline_sum <= 0.0) return false;
   double short_avg = short_sum / VOLUME_SHORT_BARS;
   double baseline_avg = baseline_sum / VOLUME_BASELINE_BARS;
   return (short_avg >= VOLUME_PARTICIPATION_RATIO * baseline_avg);
}

double GetSessionPOC(datetime start, datetime end)
{
   double poc[];
   ArraySetAsSeries(poc, true);
   int handle = iCustom(_Symbol, PERIOD_CURRENT, "AnchoredVolumeProfile", start, end);
   if(handle == INVALID_HANDLE) return 0.0;
   if(CopyBuffer(handle, 0, 0, 1, poc) <= 0) return 0.0;
   return poc[0];
}

double GetAnchoredVWAP(datetime start)
{
   double vwap[];
   ArraySetAsSeries(vwap, true);
   int handle = iCustom(_Symbol, PERIOD_CURRENT, "AnchoredVWAP", start);
   if(handle == INVALID_HANDLE) return 0.0;
   if(CopyBuffer(handle, 0, 0, 1, vwap) <= 0) return 0.0;
   return vwap[0];
}

double GetValueAreaLow(datetime start)
{
   double val[];
   ArraySetAsSeries(val, true);
   int handle = iCustom(_Symbol, PERIOD_CURRENT, "AnchoredVolumeProfile", start, TimeCurrent());
   if(handle == INVALID_HANDLE) return 0.0;
   if(CopyBuffer(handle, 2, 0, 1, val) <= 0) return 0.0;
   return val[0];
}

double GetValueAreaHigh(datetime start)
{
   double vah[];
   ArraySetAsSeries(vah, true);
   int handle = iCustom(_Symbol, PERIOD_CURRENT, "AnchoredVolumeProfile", start, TimeCurrent());
   if(handle == INVALID_HANDLE) return 0.0;
   if(CopyBuffer(handle, 1, 0, 1, vah) <= 0) return 0.0;
   return vah[0];
}

double ApproxDelta(int shift)
{
   double range = High[shift] - Low[shift];
   if(range <= 0.0) return 0.0;
   double buyVol  = Volume[shift] * (Close[shift] - Low[shift]) / range;
   double sellVol = Volume[shift] * (High[shift] - Close[shift]) / range;
   return buyVol - sellVol;
}

double DeltaBlock(int startShift, int length = 3)
{
   double sum = 0.0;
   for(int i = startShift; i < startShift + length; i++)
      sum += ApproxDelta(i);
   return sum;
}

bool IsInBullishFVG(double &fvgMid)
{
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(High[i + 2] < Low[i])
      {
         double low  = High[i + 2];
         double high = Low[i];
         if(Close[0] > low && Close[0] < high)
         {
            fvgMid = (low + high) / 2.0;
            return true;
         }
      }
   }
   return false;
}

bool IsInBearishFVG(double &fvgMid)
{
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Low[i + 2] > High[i])
      {
         double high = Low[i + 2];
         double low  = High[i];
         if(Close[0] > low && Close[0] < high)
         {
            fvgMid = (low + high) / 2.0;
            return true;
         }
      }
   }
   return false;
}

void OnTick()
{
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(Volume, true);

   if(!InTradeSession(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;
   if(!HasAdequateLiquidity()) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   double poc  = GetSessionPOC(sessionStart, TimeCurrent());
   double vwap = GetAnchoredVWAP(sessionStart);
   if(poc <= 0.0 || vwap <= 0.0) return;

   // Only trade when POC and VWAP agree: both are valid proxies for institutional fair value.
   if(MathAbs(poc - vwap) / atr > POC_VWAP_ALIGN_ATR) return;

   double anchor = (poc + vwap) / 2.0;
   double ext = (Close[0] - anchor) / atr;
   double val = GetValueAreaLow(sessionStart);
   double vah = GetValueAreaHigh(sessionStart);
   if(val <= 0.0 || vah <= 0.0) return;

   double fvgMid = 0.0;
   double d3     = DeltaBlock(0, 3);
   double d3Prev = DeltaBlock(3, 3);
   double d10    = DeltaBlock(0, 10);

   // Long: price below value-area low, inside a fresh bullish FVG, and delta shows exhaustion/absorption.
   if(ext < -ENTRY_EXT_MIN_ATR && ext > -ENTRY_EXT_MAX_ATR && Close[0] < val && IsInBullishFVG(fvgMid))
   {
      bool fvgBetween = (fvgMid > Close[0] && fvgMid < anchor + 0.1 * atr);
      bool deltaAbsorption = (d10 < 0.0 && d3 > d3Prev && d3 > 0.0);
      if(fvgBetween && deltaAbsorption)
      {
         double sl = val - 1.2 * atr;
         double tp = anchor;
         // OpenBuyOrder(sl, tp);
      }
   }
   // Short: price above value-area high, inside a fresh bearish FVG, and delta shows exhaustion/absorption.
   else if(ext > ENTRY_EXT_MIN_ATR && ext < ENTRY_EXT_MAX_ATR && Close[0] > vah && IsInBearishFVG(fvgMid))
   {
      bool fvgBetween = (fvgMid < Close[0] && fvgMid > anchor - 0.1 * atr);
      bool deltaAbsorption = (d10 > 0.0 && d3 < d3Prev && d3 < 0.0);
      if(fvgBetween && deltaAbsorption)
      {
         double sl = vah + 1.2 * atr;
         double tp = anchor;
         // OpenSellOrder(sl, tp);
      }
   }
}

// Module_1_DE40_VPPOC - Structural repair: Value-Area Sweep + Delta Absorption + FVG Mitigation
// Replaces static POC-extension fades with a liquidity/structure composite.

input int    SESSION_START_HOUR          = 9;
input int    SESSION_START_MIN           = 30;
input int    OPENING_BUFFER_SEC          = 300;   // validated after 09:30 open buffer
input int    FVG_MAX_AGE_BARS            = 20;
input double MIN_ATR                     = 12.0;
input double MAX_ADX                     = 25.0;
input double POC_MIGRATION_LIMIT         = 0.35; // ATR multiple
input double VALUE_AREA_WIDTH_MIN_ATR    = 0.40;
input double DELTA_ABSORPTION            = 0.20;
input double MAX_SPREAD_POINTS           = 15;
input double SL_ATR_MULT                 = 0.35;
input double TP_ATR_MULT                 = 1.0;

bool InTradeWindow()
{
   datetime start = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 11:30");
   if(TimeCurrent() < start + OPENING_BUFFER_SEC) return false;
   if(TimeCurrent() > end) return false;
   return true;
}

bool LiquidityScoreOK()
{
   double avg20 = 0.0, avg100 = 0.0;
   for(int i = 0; i < 100; i++)
   {
      double v = (double)iVolume(_Symbol, PERIOD_CURRENT, i);
      if(i < 20) avg20 += v;
      avg100 += v;
   }
   avg20 /= 20.0;
   avg100 /= 100.0;
   if(avg100 <= 0.0) return false;
   return (avg20 / avg100 >= 0.80);
}

bool GetSessionValueArea(datetime start, datetime end, double &poc, double &vah, double &val)
{
   int handle = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(handle == INVALID_HANDLE) return false;
   double buf[1];
   ArraySetAsSeries(buf, true);
   if(CopyBuffer(handle, 0, 0, 1, buf) <= 0) return false;
   poc = buf[0];
   if(CopyBuffer(handle, 1, 0, 1, buf) <= 0) return false;
   vah = buf[0];
   if(CopyBuffer(handle, 2, 0, 1, buf) <= 0) return false;
   val = buf[0];
   return true;
}

double GetBarDelta(int shift)
{
   double vol = (double)iVolume(_Symbol, PERIOD_CURRENT, shift);
   if(Close[shift] > Open[shift]) return vol;
   if(Close[shift] < Open[shift]) return -vol;
   return 0.0;
}

double GetSum(int startShift, int endShift, bool useDelta)
{
   double sum = 0.0;
   for(int i = startShift; i <= endShift; i++)
      sum += useDelta ? GetBarDelta(i) : (double)iVolume(_Symbol, PERIOD_CURRENT, i);
   return sum;
}

bool HasBullishFVGInLowerValue(datetime sessionStart, double poc, double val)
{
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Time[i + 2] < sessionStart) continue;
      double fvgLow  = High[i + 2]; // lower bound of bullish FVG
      double fvgHigh = Low[i];       // upper bound of bullish FVG
      if(fvgLow < fvgHigh)
      {
         double mid = (fvgLow + fvgHigh) / 2.0;
         if(mid > val && mid < poc)
         {
            bool mitigated = false;
            for(int j = i - 1; j >= 0; j--)
            {
               if(Low[j] <= fvgLow)
               {
                  mitigated = true;
                  break;
               }
            }
            if(!mitigated) return true;
         }
      }
   }
   return false;
}

bool HasBearishFVGInUpperValue(datetime sessionStart, double poc, double vah)
{
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Time[i + 2] < sessionStart) continue;
      double fvgLow  = High[i];     // lower bound of bearish FVG
      double fvgHigh = Low[i + 2];  // upper bound of bearish FVG
      if(fvgLow < fvgHigh)
      {
         double mid = (fvgLow + fvgHigh) / 2.0;
         if(mid > poc && mid < vah)
         {
            bool mitigated = false;
            for(int j = i - 1; j >= 0; j--)
            {
               if(High[j] >= fvgHigh)
               {
                  mitigated = true;
                  break;
               }
            }
            if(!mitigated) return true;
         }
      }
   }
   return false;
}

void OnTick()
{
   if(!InTradeWindow()) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = iATR(_Symbol, PERIOD_CURRENT, 14, 0);
   if(atr < MIN_ATR || atr != atr || atr <= 0.0) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   double poc, vah, val;
   if(!GetSessionValueArea(sessionStart, TimeCurrent(), poc, vah, val)) return;
   double vaw = vah - val;
   if(vaw / atr < VALUE_AREA_WIDTH_MIN_ATR) return;

   double adx = iADX(_Symbol, PERIOD_CURRENT, 14, PRICE_CLOSE, MODE_MAIN, 0);
   if(adx > MAX_ADX) return;

   // Block trend-driven POC migration
   datetime refTime = TimeCurrent() - 10 * PeriodSeconds(PERIOD_CURRENT);
   double pocRef = 0.0;
   {
      double buf[1];
      ArraySetAsSeries(buf, true);
      int h = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", sessionStart, refTime);
      if(h != INVALID_HANDLE && CopyBuffer(h, 0, 0, 1, buf) > 0)
      {
         pocRef = buf[0];
         if(MathAbs(poc - pocRef) / atr > POC_MIGRATION_LIMIT) return;
      }
      else return;
   }

   if(!LiquidityScoreOK()) return;

   double deltaPrior  = GetSum(3, 5, true);
   double volPrior    = GetSum(3, 5, false);
   double deltaRecent = GetSum(0, 2, true);

   bool longSweep      = (Low[0] < val && Close[0] > val && Close[0] < poc);
   bool longAbsorption = (deltaPrior < -DELTA_ABSORPTION * volPrior && deltaRecent > 0.0);
   bool bullishFVG     = HasBullishFVGInLowerValue(sessionStart, poc, val);

   if(longSweep && longAbsorption && bullishFVG)
   {
      double sl = Low[0] - SL_ATR_MULT * atr;
      double tp = poc;
      // OpenBuyOrder(sl, tp);
   }

   bool shortSweep      = (High[0] > vah && Close[0] < vah && Close[0] > poc);
   bool shortAbsorption = (deltaPrior > DELTA_ABSORPTION * volPrior && deltaRecent < 0.0);
   bool bearishFVG      = HasBearishFVGInUpperValue(sessionStart, poc, vah);

   if(shortSweep && shortAbsorption && bearishFVG)
   {
      double sl = High[0] + SL_ATR_MULT * atr;
      double tp = poc;
      // OpenSellOrder(sl, tp);
   }
}

