bool InTradeWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + BUFFER_MINUTES*60 && t < end);
}

double GetATR()
{
   return iATR(_Symbol, _Period, 14, 0);
}

double GetH1Bias()
{
   double ema0 = iMA(_Symbol, PERIOD_H1, 50, 0, MODE_EMA, PRICE_CLOSE, 0);
   double ema1 = iMA(_Symbol, PERIOD_H1, 50, 0, MODE_EMA, PRICE_CLOSE, 1);
   if(ema0 > ema1) return 1.0;
   if(ema0 < ema1) return -1.0;
   return 0.0;
}

void GetSessionVolumeProfile(datetime start, datetime end, double &poc, double &vah, double &val)
{
   poc = 0; vah = 0; val = 0;
   int h = iCustom(_Symbol, _Period, "VolumeProfile", start, end, VALUE_AREA_VOL);
   double bufPOC[1], bufVAH[1], bufVAL[1];
   if(CopyBuffer(h, 0, 0, 1, bufPOC) > 0) poc = bufPOC[0];
   if(CopyBuffer(h, 1, 0, 1, bufVAH) > 0) vah = bufVAH[0];
   if(CopyBuffer(h, 2, 0, 1, bufVAL) > 0) val = bufVAL[0];
}

double GetBarDelta(int shift)
{
   double vol = (double)iVolume(_Symbol, _Period, shift);
   if(Close[shift] > Open[shift]) return vol;
   if(Close[shift] < Open[shift]) return -vol;
   return 0.0;
}

double GetDeltaZScore(int period = 20)
{
   double sum = 0.0, sumSq = 0.0;
   for(int i = 0; i < period; i++)
   {
      double d = GetBarDelta(i);
      sum += d;
      sumSq += d * d;
   }
   double mean = sum / period;
   double var = (sumSq / period) - (mean * mean);
   if(var <= 0) return 0.0;
   return (GetBarDelta(0) - mean) / MathSqrt(var);
}

bool BullishFVG(int shift, double &mid, double &fvg_low, double &fvg_high)
{
   if(shift + 2 >= Bars(_Symbol, _Period)) return false;
   fvg_low = High[shift + 2];
   fvg_high = Low[shift];
   if(fvg_low < fvg_high)
   {
      mid = (fvg_low + fvg_high) / 2.0;
      return true;
   }
   return false;
}

bool BearishFVG(int shift, double &mid, double &fvg_low, double &fvg_high)
{
   if(shift + 2 >= Bars(_Symbol, _Period)) return false;
   fvg_low = High[shift];
   fvg_high = Low[shift + 2];
   if(fvg_low < fvg_high)
   {
      mid = (fvg_low + fvg_high) / 2.0;
      return true;
   }
   return false;
}

bool HasRecentBullishFVGInValueArea(double val, double poc, double atr)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      double mid, fvg_low, fvg_high;
      if(BullishFVG(i, mid, fvg_low, fvg_high))
      {
         if(fvg_low >= val - 0.5 * atr && mid <= poc)
            return true;
      }
   }
   return false;
}

bool HasRecentBearishFVGInValueArea(double vah, double poc, double atr)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      double mid, fvg_low, fvg_high;
      if(BearishFVG(i, mid, fvg_low, fvg_high))
      {
         if(fvg_high <= vah + 0.5 * atr && mid >= poc)
            return true;
      }
   }
   return false;
}

void OnTick()
{
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);

   if(!InTradeWindow(TimeCurrent())) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   double avgVol = 0.0;
   for(int i = 1; i <= 20; i++) avgVol += (double)iVolume(_Symbol, _Period, i);
   avgVol /= 20.0;
   if((double)iVolume(_Symbol, _Period, 0) < MIN_VOLUME_PARTICIPATION * avgVol) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   double poc, vah, val;
   GetSessionVolumeProfile(sessionStart, TimeCurrent(), poc, vah, val);
   if(poc <= 0 || vah <= 0 || val <= 0 || vah <= val) return;

   double h1Bias = GetH1Bias();
   double deltaZ = GetDeltaZScore(20);

   // Long: H1 bull or flat, sweep below value-area low, close back inside, absorption + recent bullish FVG
   if(Close[0] < poc && Low[0] < val && Close[0] > val && Close[0] > Open[0])
   {
      if(h1Bias >= 0 && deltaZ > DELTA_Z_LIMIT && HasRecentBullishFVGInValueArea(val, poc, atr))
      {
         double sl = Low[0] - SL_ATR_MULT * atr;
         double tp = Close[0] + TP_ATR_MULT * atr;
         // OpenBuyOrder(sl, tp);
      }
   }

   // Short: H1 bear or flat, sweep above value-area high, close back inside, absorption + recent bearish FVG
   if(Close[0] > poc && High[0] > vah && Close[0] < vah && Close[0] < Open[0])
   {
      if(h1Bias <= 0 && deltaZ < -DELTA_Z_LIMIT && HasRecentBearishFVGInValueArea(vah, poc, atr))
      {
         double sl = High[0] + SL_ATR_MULT * atr;
         double tp = Close[0] - TP_ATR_MULT * atr;
         // OpenSellOrder(sl, tp);
      }
   }
}

