bool InTradeWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + BUFFER_MINUTES * 60 && t < end);
}

double GetATR()
{
   double buf[1]; ArraySetAsSeries(buf, true);
   int h = iATR(_Symbol, PERIOD_CURRENT, 14);
   if(CopyBuffer(h, 0, 0, 1, buf) <= 0) return 0.0;
   return buf[0];
}

double GetPriorSessionPOC()
{
   datetime today = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 00:00");
   datetime priorStart = today - 86400 + SESSION_START_HOUR * 3600 + SESSION_START_MIN * 60;
   datetime priorEnd   = today - 86400 + 11 * 3600 + 30 * 60;
   double poc[1]; ArraySetAsSeries(poc, true);
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", priorStart, priorEnd), 0, 0, 1, poc) <= 0) return 0.0;
   return poc[0];
}

double GetSessionVWAP()
{
   double vw[1]; ArraySetAsSeries(vw, true);
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VWAP"), 0, 0, 1, vw) <= 0) return 0.0;
   return vw[0];
}

bool FreshBullishFVG(double &mid)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
      if(High[i + 2] < Low[i])
      {
         mid = (High[i + 2] + Low[i]) / 2.0;
         return true;
      }
   }
   return false;
}

bool FreshBearishFVG(double &mid)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
      if(Low[i + 2] > High[i])
      {
         mid = (Low[i + 2] + High[i]) / 2.0;
         return true;
      }
   }
   return false;
}

bool PositiveOBVSlope()
{
   double obv[6]; ArraySetAsSeries(obv, true);
   int h = iOBV(_Symbol, PERIOD_CURRENT, PRICE_CLOSE);
   if(CopyBuffer(h, 0, 0, OBV_SLOPE_BARS + 1, obv) <= 0) return false;
   return (obv[0] > obv[OBV_SLOPE_BARS]);
}

bool NegativeOBVSlope()
{
   double obv[6]; ArraySetAsSeries(obv, true);
   int h = iOBV(_Symbol, PERIOD_CURRENT, PRICE_CLOSE);
   if(CopyBuffer(h, 0, 0, OBV_SLOPE_BARS + 1, obv) <= 0) return false;
   return (obv[0] < obv[OBV_SLOPE_BARS]);
}

bool VolumeBurst()
{
   double avgVol[1]; ArraySetAsSeries(avgVol, true);
   int h = iMA(_Symbol, PERIOD_CURRENT, 20, 0, MODE_SMA, VOLUME_TICK);
   if(CopyBuffer(h, 0, 0, 1, avgVol) <= 0) return false;
   return (iVolume(_Symbol, PERIOD_CURRENT, 0) >= avgVol[0] * MIN_VOL_MULT);
}

void OnTick()
{
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);

   if(!InTradeWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   double priorPOC = GetPriorSessionPOC();
   if(priorPOC <= 0.0) return;

   double vwap = GetSessionVWAP();
   if(vwap <= 0.0) return;

   if(!VolumeBurst()) return;

   bool bullishBias = (vwap > priorPOC + VWAP_BIAS_ATR * atr);
   bool bearishBias = (vwap < priorPOC - VWAP_BIAS_ATR * atr);
   if(!bullishBias && !bearishBias) return;

   double fvgMid = 0.0;

   // LONG: bullish session (VWAP above prior POC) and price retraces into prior POC.
   if(bullishBias && MathAbs(Close[0] - priorPOC) / atr <= POC_RETRACE_ATR && Close[0] > priorPOC)
   {
      if(FreshBullishFVG(fvgMid) && MathAbs(fvgMid - priorPOC) / atr <= FVG_OVERLAP_ATR && PositiveOBVSlope())
      {
         double sl = priorPOC - SL_ATR_MULT * atr;
         double tp = Close[0] + TP_ATR_MULT * atr;
         // OpenBuyOrder(sl, tp);
      }
   }

   // SHORT: bearish session (VWAP below prior POC) and price retraces up into prior POC.
   if(bearishBias && MathAbs(Close[0] - priorPOC) / atr <= POC_RETRACE_ATR && Close[0] < priorPOC)
   {
      if(FreshBearishFVG(fvgMid) && MathAbs(fvgMid - priorPOC) / atr <= FVG_OVERLAP_ATR && NegativeOBVSlope())
      {
         double sl = priorPOC + SL_ATR_MULT * atr;
         double tp = Close[0] - TP_ATR_MULT * atr;
         // OpenSellOrder(sl, tp);
      }
   }
}

