bool InTradeWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + BUFFER_MINUTES * 60 && t < end);
}

bool LiquidityGateOK()
{
   double curVol = (double)iVolume(_Symbol, PERIOD_CURRENT, 1);
   double avgVol = 0.0;
   for(int i = 2; i <= 21; i++)
      avgVol += (double)iVolume(_Symbol, PERIOD_CURRENT, i);
   avgVol /= 20.0;
   if(avgVol <= 0.0) return false;
   return (curVol >= VOLUME_RATIO_LIMIT * avgVol);
}

bool GetSessionVolumeProfile(datetime start, datetime end,
                             double &poc, double &val, double &vah)
{
   int vp = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(vp == INVALID_HANDLE) return false;
   double pocArr[1], valArr[1], vahArr[1];
   if(CopyBuffer(vp, 0, 0, 1, pocArr) <= 0) return false;
   if(CopyBuffer(vp, 1, 0, 1, valArr) <= 0) return false;
   if(CopyBuffer(vp, 2, 0, 1, vahArr) <= 0) return false;
   poc = pocArr[0]; val = valArr[0]; vah = vahArr[0];
   return (poc > 0.0 && val > 0.0 && vah > val);
}

bool GetBullishFVGMidInVA(double poc, double val, double vah,
                          double &mid, double &low, double &high)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(High[i + 2] < Low[i])
      {
         high = Low[i];
         low  = High[i + 2];
         mid  = (high + low) / 2.0;
         if(mid >= val && mid <= poc)
            return true;
      }
   }
   return false;
}

bool GetBearishFVGMidInVA(double poc, double val, double vah,
                          double &mid, double &low, double &high)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Low[i + 2] > High[i])
      {
         low  = High[i];
         high = Low[i + 2];
         mid  = (high + low) / 2.0;
         if(mid >= poc && mid <= vah)
            return true;
      }
   }
   return false;
}

double CVD(int fromShift, int lookback)
{
   double sum = 0.0;
   for(int i = fromShift; i < fromShift + lookback && i < Bars(_Symbol, PERIOD_CURRENT); i++)
      sum += (Close[i] - Open[i]) * (double)iVolume(_Symbol, PERIOD_CURRENT, i);
   return sum;
}

bool BullishCVDDivergence(int lookback)
{
   int lowShift = iLowest(_Symbol, PERIOD_CURRENT, MODE_LOW, lookback, 1);
   if(lowShift < 0) return false;
   double cvdAtLow = CVD(lowShift, lookback);
   double cvdNow   = CVD(0, lookback);
   return (Low[0] < Low[lowShift] && cvdNow > cvdAtLow);
}

bool BearishCVDDivergence(int lookback)
{
   int highShift = iHighest(_Symbol, PERIOD_CURRENT, MODE_HIGH, lookback, 1);
   if(highShift < 0) return false;
   double cvdAtHigh = CVD(highShift, lookback);
   double cvdNow     = CVD(0, lookback);
   return (High[0] > High[highShift] && cvdNow < cvdAtHigh);
}

void OnTick()
{
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);

   if(!InTradeWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = iATR(_Symbol, PERIOD_CURRENT, 14, 0);
   if(atr < MIN_ATR) return;

   if(!LiquidityGateOK()) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   datetime sessionEnd   = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 11:30");

   double poc = 0.0, val = 0.0, vah = 0.0;
   if(!GetSessionVolumeProfile(sessionStart, sessionEnd, poc, val, vah)) return;

   double bid = SymbolInfoDouble(_Symbol, SYMBOL_BID);
   double ask = SymbolInfoDouble(_Symbol, SYMBOL_ASK);

   double fvgMid = 0.0, fvgLow = 0.0, fvgHigh = 0.0;

   // Long: completed bar reclaimed Value Area Low; bullish FVG inside Value Area; CVD positive divergence
   bool longFVG      = GetBullishFVGMidInVA(poc, val, vah, fvgMid, fvgLow, fvgHigh);
   bool valReclaim   = (Low[1] < val && Close[1] > val && Close[0] > val);
   bool cvdBull      = BullishCVDDivergence(CVD_LOOKBACK);
   bool priceInBull  = (ask <= fvgHigh && ask >= fvgLow);

   if(longFVG && valReclaim && cvdBull && priceInBull)
   {
      double sl = MathMin(Low[1], Low[0]) - SL_ATR_MULT * atr;
      double tp = poc;
      // OpenBuyOrder(sl, tp);
   }

   // Short: completed bar rejected Value Area High; bearish FVG inside Value Area; CVD negative divergence
   bool shortFVG     = GetBearishFVGMidInVA(poc, val, vah, fvgMid, fvgLow, fvgHigh);
   bool vahReject    = (High[1] > vah && Close[1] < vah && Close[0] < vah);
   bool cvdBear      = BearishCVDDivergence(CVD_LOOKBACK);
   bool priceInBear  = (bid >= fvgLow && bid <= fvgHigh);

   if(shortFVG && vahReject && cvdBear && priceInBear)
   {
      double sl = MathMax(High[1], High[0]) + SL_ATR_MULT * atr;
      double tp = poc;
      // OpenSellOrder(sl, tp);
   }
}

