double CumulativeDelta(int startShift, int count)
{
   double delta = 0.0;
   for(int i = startShift; i < startShift + count; i++)
   {
      long vol = iVolume(_Symbol, _Period, i);
      if(Close[i] > Open[i])
         delta += vol;
      else if(Close[i] < Open[i])
         delta -= vol;
   }
   return(delta);
}

bool RecentBullishFVGBelowPOC(double poc, double atr, double &fvgLow, double &fvgHigh, int &ageBars)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, _Period)) break;
      if(High[i + 2] < Low[i])
      {
         double mid = (High[i + 2] + Low[i]) / 2.0;
         if(High[i + 2] < poc && MathAbs(mid - poc) / atr <= 1.5)
         {
            fvgLow = High[i + 2];
            fvgHigh = Low[i];
            ageBars = i;
            return(true);
         }
      }
   }
   return(false);
}

bool RecentBearishFVGAbovePOC(double poc, double atr, double &fvgLow, double &fvgHigh, int &ageBars)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, _Period)) break;
      if(Low[i + 2] > High[i])
      {
         double mid = (Low[i + 2] + High[i]) / 2.0;
         if(Low[i + 2] > poc && MathAbs(mid - poc) / atr <= 1.5)
         {
            fvgLow = High[i];
            fvgHigh = Low[i + 2];
            ageBars = i;
            return(true);
         }
      }
   }
   return(false);
}

void OnTick()
{
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);

   if(!InTradeWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   double poc = GetSessionPOC(sessionStart, TimeCurrent());
   double vwap = GetSessionVWAP();
   if(poc <= 0.0 || vwap <= 0.0) return;

   // Only trade a stable POC auction; avoid rapidly migrating developing POC.
   datetime refTime = TimeCurrent() - 15 * 60;
   if(refTime < sessionStart + BUFFER_MINUTES * 60) return;
   double pocRef = GetSessionPOC(sessionStart, refTime);
   if(MathAbs(poc - pocRef) / atr > POC_STABILITY_ATR) return;

   // POC/VWAP agreement is required; otherwise POC is not a fair magnet.
   if(MathAbs(poc - vwap) / atr > POC_VWAP_ALIGN_ATR) return;

   // HTF macro slope gate: do not fade into a strong H4 trend.
   double h4ema50 = iMA(_Symbol, PERIOD_H4, 50, 0, MODE_EMA, PRICE_CLOSE, 0);
   double h4ema50Prev = iMA(_Symbol, PERIOD_H4, 50, 0, MODE_EMA, PRICE_CLOSE, 1);
   double h4Slope = (h4ema50 - h4ema50Prev) / atr;

   double recentDelta = CumulativeDelta(1, DELTA_PERIOD);
   double priorDelta = CumulativeDelta(DELTA_PERIOD + 1, DELTA_PERIOD);

   int swingLowIdx = iLowest(_Symbol, _Period, MODE_LOW, SWING_LOOKBACK, 1);
   int swingHighIdx = iHighest(_Symbol, _Period, MODE_HIGH, SWING_LOOKBACK, 1);

   double fvgLow = 0.0, fvgHigh = 0.0;
   int ageBars = 0;

   // LONG: local swing low sweep, fresh bullish FVG below POC, and demand-side delta turn.
   bool bullishFVG = RecentBullishFVGBelowPOC(poc, atr, fvgLow, fvgHigh, ageBars);
   if(Low[0] < Low[swingLowIdx] && Close[0] > Low[swingLowIdx] && Close[0] < poc &&
      Close[0] >= fvgLow && Close[0] <= fvgHigh &&
      bullishFVG && recentDelta > 0.0 && recentDelta > priorDelta &&
      h4Slope >= H4_SLOPE_ATR_LIMIT)
   {
      double sl = Close[0] - SL_ATR_MULT * atr;
      double tp = Close[0] + TP_ATR_MULT * atr;
      trade.Buy(0.01, _Symbol, 0, sl, tp, "DE40_VPPOC_Auction_Exhaustion");
   }

   // SHORT: local swing high sweep, fresh bearish FVG above POC, and supply-side delta turn.
   bool bearishFVG = RecentBearishFVGAbovePOC(poc, atr, fvgLow, fvgHigh, ageBars);
   if(High[0] > High[swingHighIdx] && Close[0] < High[swingHighIdx] && Close[0] > poc &&
      Close[0] >= fvgLow && Close[0] <= fvgHigh &&
      bearishFVG && recentDelta < 0.0 && recentDelta < priorDelta &&
      h4Slope <= -H4_SLOPE_ATR_LIMIT)
   {
      double sl = Close[0] + SL_ATR_MULT * atr;
      double tp = Close[0] - TP_ATR_MULT * atr;
      trade.Sell(0.01, _Symbol, 0, sl, tp, "DE40_VPPOC_Auction_Exhaustion");
   }
}

