MQL5 skeleton:

input int SESSION_START_HOUR=9;
input int SESSION_START_MIN=30;
input int SESSION_BUFFER_MIN=5;
input int NO_NEW_ENTRY_HOUR=10;
input int NO_NEW_ENTRY_MIN=45;
input double MIN_ATR=15.0;
input int MAX_DAILY_LOSSES=2;
input int REGIME_LOOKBACK=20;
input double REGIME_R2_MAX=0.20;
input double REGIME_ADX_MAX=18.0;
input double REGIME_SLOPE_ATR_MAX=0.10;
input int LIQ_VOL_LOOKBACK=20;
input double LIQ_VOL_MULT=1.5;
input double POC_EXT_MIN_ATR=0.40;
input double POC_EXT_MAX_ATR=1.50;
input double POC_DOMINANCE_MIN=1.2;
input int DELTA_BARS=3;

int dailyLosses=0;
datetime lastDay=0;

bool InTradeWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime noNew = StringToTime(TimeToString(t, TIME_DATE) + " 10:45");
   return (t >= start + SESSION_BUFFER_MIN * 60 && t < noNew);
}

double LRSlope(int period)
{
   double xMean = (period - 1.0) / 2.0;
   double yMean = 0.0;
   for(int i = 0; i < period; i++) yMean += Close[i];
   yMean /= period;
   double num = 0.0, den = 0.0;
   for(int i = 0; i < period; i++)
   {
      double x = i;
      num += (x - xMean) * (Close[i] - yMean);
      den += (x - xMean) * (x - xMean);
   }
   if(den == 0.0) return 0.0;
   return num / den;
}

double LRR2(int period)
{
   double xMean = (period - 1.0) / 2.0;
   double yMean = 0.0;
   for(int i = 0; i < period; i++) yMean += Close[i];
   yMean /= period;
   double slope = LRSlope(period);
   double intercept = yMean - slope * xMean;
   double ssTot = 0.0, ssRes = 0.0;
   for(int i = 0; i < period; i++)
   {
      double yPred = slope * i + intercept;
      ssTot += (Close[i] - yMean) * (Close[i] - yMean);
      ssRes += (Close[i] - yPred) * (Close[i] - yPred);
   }
   if(ssTot == 0.0) return 0.0;
   return 1.0 - ssRes / ssTot;
}

double GetBarDelta(int shift)
{
   double range = High[shift] - Low[shift];
   if(range <= 0) return 0.0;
   double buyFrac = (Close[shift] - Low[shift]) / range;
   double vol = (double)iVolume(_Symbol, PERIOD_CURRENT, shift);
   return vol * (2.0 * buyFrac - 1.0);
}

double GetCumDelta(int bars)
{
   double d = 0.0;
   for(int i = 0; i < bars; i++) d += GetBarDelta(i);
   return d;
}

double GetSessionPOC(datetime start, datetime end)
{
   double poc[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end), 0, 0, 1, poc) <= 0) return 0.0;
   return poc[0];
}

double GetPOCVolume(datetime start, datetime end)
{
   double vol[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end), 1, 0, 1, vol) <= 0) return 0.0;
   return vol[0];
}

double GetPriceVolumeAtCurrent(datetime start, datetime end)
{
   double vol[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end), 2, 0, 1, vol) <= 0) return 0.0;
   return vol[0];
}

void OnTick()
{
   if(!InTradeWindow(TimeCurrent())) return;

   datetime today = StringToTime(TimeToString(TimeCurrent(), TIME_DATE));
   if(lastDay != today)
   {
      dailyLosses = 0;
      lastDay = today;
   }
   if(dailyLosses >= MAX_DAILY_LOSSES) return;

   double atr = iATR(_Symbol, PERIOD_CURRENT, 14, 0);
   if(atr < MIN_ATR) return;

   double slope = LRSlope(REGIME_LOOKBACK);
   double r2 = LRR2(REGIME_LOOKBACK);
   double adx = iADX(_Symbol, PERIOD_CURRENT, 14, PRICE_CLOSE, MODE_MAIN, 0);
   if(adx > REGIME_ADX_MAX || r2 > REGIME_R2_MAX || MathAbs(slope) / atr > REGIME_SLOPE_ATR_MAX) return;

   double avgVol = iMA(_Symbol, PERIOD_CURRENT, LIQ_VOL_LOOKBACK, 0, MODE_SMA, VOLUME_TICK, 1);
   double curVol = (double)iVolume(_Symbol, PERIOD_CURRENT, 0);
   if(curVol < LIQ_VOL_MULT * avgVol) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   double poc = GetSessionPOC(sessionStart, TimeCurrent());
   if(poc <= 0) return;

   double pocVol = GetPOCVolume(sessionStart, TimeCurrent());
   double priceVol = GetPriceVolumeAtCurrent(sessionStart, TimeCurrent());
   if(pocVol <= 0 || priceVol <= 0) return;
   if(pocVol < POC_DOMINANCE_MIN * MathMax(priceVol, 1.0)) return;

   double ext = MathAbs(Close[0] - poc) / atr;
   if(ext < POC_EXT_MIN_ATR || ext > POC_EXT_MAX_ATR) return;

   double delta3 = GetCumDelta(DELTA_BARS);

   // Long fade: price below POC, bearish bar, but buyers absorbing
   if(Close[0] < poc && Close[0] < Open[0] && delta3 > 0)
   {
      double sl = Low[0] - 0.5 * atr;
      double tp = poc;
      // OpenBuyOrder(sl, tp)
   }
   // Short fade: price above POC, bullish bar, but sellers absorbing
   else if(Close[0] > poc && Close[0] > Open[0] && delta3 < 0)
   {
      double sl = High[0] + 0.5 * atr;
      double tp = poc;
      // OpenSellOrder(sl, tp)
   }
}

// OnTradeTransaction or dedicated loss counter should increment dailyLosses when a closed deal has negative profit.
void OnTradeTransaction(const MqlTradeTransaction& trans, const MqlTradeRequest& request, const MqlTradeResult& result)
{
   if(trans.type == TRADE_TRANSACTION_DEAL_ADD)
   {
      long deal = trans.deal;
      if(HistoryDealSelect(deal))
      {
         double profit = HistoryDealGetDouble(deal, DEAL_PROFIT);
         if(profit < 0) dailyLosses++;
      }
   }
}

