//+------------------------------------------------------------------+
// Module_1_DE40_VPPOC - Value Area Boundary Rejection + Fair Value Mitigation
// Orthogonal: no 2.0 ATR POC fade, no session high/low sweep, no FVG-at-POC
//+------------------------------------------------------------------+
input int    SESSION_START_HOUR   = 9;
input int    SESSION_START_MIN    = 30;
input int    BUFFER_MINUTES       = 5;
input int    NO_NEW_ENTRY_HOUR    = 10;
input int    NO_NEW_ENTRY_MIN     = 50;
input double MIN_ATR              = 12.0;
input double MAX_SPREAD_POINTS    = 15;
input int    FVG_MAX_AGE_BARS     = 6;
input int    PROBE_WINDOW         = 6;
input double WICK_ATR             = 0.25;
input double VOL_PROBE_RATIO      = 1.30;
input double VOL_CURB_RATIO       = 0.70;
input double ADX_MAX              = 20.0;
input double SL_ATR_MULT          = 1.2;

bool InTradeWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t,TIME_DATE)+" 09:30");
   datetime noNew = StringToTime(TimeToString(t,TIME_DATE)+" 10:50");
   return (t >= start + BUFFER_MINUTES*60 && t < noNew);
}

double GetATR()
{
   int h = iATR(_Symbol,_Period,14);
   double buf[1]; ArraySetAsSeries(buf,true);
   if(CopyBuffer(h,0,0,1,buf)<=0) return 0.0;
   return buf[0];
}

double GetADX()
{
   int h = iADX(_Symbol,_Period,14,PRICE_CLOSE,MODE_MAIN,0);
   double buf[1]; ArraySetAsSeries(buf,true);
   if(CopyBuffer(h,0,0,1,buf)<=0) return 100.0;
   return buf[0];
}

double GetMedianVolume(int lookback)
{
   double vols[];
   ArrayResize(vols,lookback);
   for(int i=0;i<lookback;i++) vols[i] = (double)iVolume(_Symbol,_Period,i+1);
   ArraySort(vols);
   if(lookback%2==1) return vols[lookback/2];
   return (vols[lookback/2-1]+vols[lookback/2])/2.0;
}

bool GetValueArea(datetime start, datetime end, double &poc, double &vah, double &val)
{
   int vp = iCustom(_Symbol,_Period,"VolumeProfile",start,end);
   double pocBuf[1], vahBuf[1], valBuf[1];
   ArraySetAsSeries(pocBuf,true); ArraySetAsSeries(vahBuf,true); ArraySetAsSeries(valBuf,true);
   if(CopyBuffer(vp,0,0,1,pocBuf)<=0) return false;
   if(CopyBuffer(vp,1,0,1,vahBuf)<=0) return false;
   if(CopyBuffer(vp,2,0,1,valBuf)<=0) return false;
   poc=pocBuf[0]; vah=vahBuf[0]; val=valBuf[0];
   return true;
}

bool BullishBoundaryFVG(double val, double atr, double &mid)
{
   for(int i=1; i<=FVG_MAX_AGE_BARS; i++)
   {
      if(i+2 >= Bars(_Symbol,_Period)) break;
      if(High[i+2] < Low[i])
      {
         double fvgHigh = High[i+2];
         double fvgLow = Low[i];
         if(fvgHigh <= val && MathAbs(fvgHigh-val)/atr <= 0.25)
         {
            mid = (fvgHigh+fvgLow)/2.0;
            return true;
         }
      }
   }
   return false;
}

bool BearishBoundaryFVG(double vah, double atr, double &mid)
{
   for(int i=1; i<=FVG_MAX_AGE_BARS; i++)
   {
      if(i+2 >= Bars(_Symbol,_Period)) break;
      if(Low[i+2] > High[i])
      {
         double fvgLow = Low[i+2];
         double fvgHigh = High[i];
         if(fvgLow >= vah && MathAbs(fvgLow-vah)/atr <= 0.25)
         {
            mid = (fvgLow+fvgHigh)/2.0;
            return true;
         }
      }
   }
   return false;
}

bool LiquidityClock()
{
   double last5=0, prior5=0;
   for(int i=1; i<=5; i++) last5 += (double)iVolume(_Symbol,_Period,i);
   for(int i=6; i<=10; i++) prior5 += (double)iVolume(_Symbol,_Period,i);
   if(prior5 <= 0.0) return true;
   return (last5 >= prior5*0.70);
}

void OnTick()
{
   if(!InTradeWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol,SYMBOL_SPREAD)>MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   double adx = GetADX();
   if(adx > ADX_MAX) return;

   if(!LiquidityClock()) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(),TIME_DATE)+" 09:30");
   datetime sessionEnd   = StringToTime(TimeToString(TimeCurrent(),TIME_DATE)+" 11:30");

   double poc, vah, val;
   if(!GetValueArea(sessionStart, sessionEnd, poc, vah, val)) return;
   if(MathAbs(vah-val)/atr < 0.5) return;

   double medianVol = GetMedianVolume(15);

   // Long: failed downside excursion below VAL, boundary FVG below VAL mitigated,
   // price reclaims VAL and is inside the value area.
   for(int p=1; p<=PROBE_WINDOW; p++)
   {
      if(Low[p] < val && Close[p] > val && Close[p] < poc)
      {
         double wick = (val - Low[p])/atr;
         if(wick < WICK_ATR) continue;

         double probeVol = (double)iVolume(_Symbol,_Period,p);
         if(probeVol < medianVol*VOL_PROBE_RATIO) continue;

         double curVol = (double)iVolume(_Symbol,_Period,0);
         if(curVol > probeVol*VOL_CURB_RATIO) continue;

         double mid;
         if(!BullishBoundaryFVG(val, atr, mid)) continue;

         if(Low[1] <= mid && Close[1] > val && Close[1] < poc)
         {
            double sl = val - SL_ATR_MULT*atr;
            double tp = poc;
            // OpenBuyOrder(sl, tp);
            return;
         }
      }
   }

   // Short: failed upside excursion above VAH, boundary FVG above VAH mitigated,
   // price reclaims VAH and is inside the value area.
   for(int p=1; p<=PROBE_WINDOW; p++)
   {
      if(High[p] > vah && Close[p] < vah && Close[p] > poc)
      {
         double wick = (High[p] - vah)/atr;
         if(wick < WICK_ATR) continue;

         double probeVol = (double)iVolume(_Symbol,_Period,p);
         if(probeVol < medianVol*VOL_PROBE_RATIO) continue;

         double curVol = (double)iVolume(_Symbol,_Period,0);
         if(curVol > probeVol*VOL_CURB_RATIO) continue;

         double mid;
         if(!BearishBoundaryFVG(vah, atr, mid)) continue;

         if(High[1] >= mid && Close[1] < vah && Close[1] > poc)
         {
            double sl = vah + SL_ATR_MULT*atr;
            double tp = poc;
            // OpenSellOrder(sl, tp);
            return;
         }
      }
   }
}

