   int vp = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(vp == INVALID_HANDLE) return false;
   if(CopyBuffer(vp, 0, 0, 1, pocArr) <= 0) return false;
   if(CopyBuffer(vp, 1, 0, 1, vahArr) <= 0) return false;
   if(CopyBuffer(vp, 2, 0, 1, valArr) <= 0) return false;
   poc = pocArr[0];
   vah = vahArr[0];
   val = valArr[0];
   return (poc > 0 && vah > val && vah > poc && poc > val);
}

bool BullishFVG(int shift, double &mid)
{
