bool BearishFVG(int shift, double &mid)
{
   if(shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   if(Low[shift + 2] > High[shift])
   {
      mid = (Low[shift + 2] + High[shift]) / 2.0;
      return true;
   }
   return false;
}

bool HasBullishVAFVG(double val, double poc)
{
   double mid;
   double lowerBound = val;
   double upperBound = val + 0.35 * (poc - val);
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      if(BullishFVG(i, mid))
      {
         if(mid >= lowerBound && mid <= upperBound)
            return true;
      }
   }
   return false;
