bool HasBearishVAFVG(double vah, double poc)
{
   double mid;
   double upperBound = vah;
   double lowerBound = vah - 0.35 * (vah - poc);
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      if(BearishFVG(i, mid))
      {
         if(mid <= upperBound && mid >= lowerBound)
            return true;
      }
   }
   return false;
}

bool IsProfileStable(datetime sessionStart, double atr)
{
   datetime tNow = TimeCurrent();
   datetime tPast = tNow - STABILITY_BARS * PeriodSeconds(PERIOD_CURRENT);
   if(tPast < sessionStart + OPENING_BUFFER_MIN * 60)
