   if(Low[s] < val && Close[s] > val && Close[s] > Open[s] && Close[s] < poc)
   {
      if(HasBullishVAFVG(val, poc))
      {
         double sl = val - SL_ATR_MULT * atr;
         double tp = poc; // POC reversion target
         // OpenBuyOrder(sl, tp);
      }
   }
   // Short: rejected sweep of upper value area + fresh bearish FVG in upper value area
   else if(High[s] > vah && Close[s] < vah && Close[s] < Open[s] && Close[s] > poc)
   {
      if(HasBearishVAFVG(vah, poc))
      {
         double sl = vah + SL_ATR_MULT * atr;
         double tp = poc; // POC reversion target
         // OpenSellOrder(sl, tp);
      }
   }
}

Replace the static POC fade with a Value-Area Boundary Reclaim + boundary FVG mitigation entry. Preserve the validated 09:30 UTC opening buffer. Require a minimum profile maturity of 20 minutes after the buffer, a minimum Value Area width of 0.5 ATR, spread protection, and a DXY 20-EMA intermarket filter. Exact MQL5 logic:

input int    SESSION_START_HOUR      = 9;
input int    SESSION_START_MIN       = 30;
input int    BUFFER_MINUTES          = 5;
input int    MIN_PROFILE_MATURITY_MIN= 20;
input double MIN_ATR                 = 15.0;
input double MIN_VALUE_AREA_ATR      = 0.50;
input int    FVG_MAX_AGE_BARS        = 12;
input double FVG_VA_OVERLAP_ATR      = 0.25;
input double SL_ATR_MULT             = 1.5;
input double TP_ATR_MULT             = 2.5;
input int    MAX_SPREAD_POINTS       = 12;

double GetATR()
{
   double buf[1];
   if(CopyBuffer(iATR(_Symbol, PERIOD_CURRENT, 14), 0, 0, 1, buf) <= 0)
      return 0.0;
   return buf[0];
}

bool InTradeSession(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + BUFFER_MINUTES * 60 && t < end);
}

bool GetValueArea(datetime start, datetime end,
                  double &poc, double &vah, double &val)
{
   double p[1], h[1], l[1];
   int handle = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(handle == INVALID_HANDLE) return false;
   if(CopyBuffer(handle, 0, 0, 1, p) <= 0) return false;
   if(CopyBuffer(handle, 1, 0, 1, h) <= 0) return false;
   if(CopyBuffer(handle, 2, 0, 1, l) <= 0) return false;
   poc = p[0]; vah = h[0]; val = l[0];
   return (poc > 0.0 && vah > val);
}

bool HasRecentBullishFVG(double level, double atr)
{
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(High[i + 2] < Low[i])  // bullish FVG
      {
         double mid = (High[i + 2] + Low[i]) / 2.0;
         if(MathAbs(mid - level) / atr <= FVG_VA_OVERLAP_ATR)
            return true;
      }
   }
   return false;
}

bool HasRecentBearishFVG(double level, double atr)
{
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Low[i + 2] > High[i])  // bearish FVG
      {
         double mid = (Low[i + 2] + High[i]) / 2.0;
         if(MathAbs(mid - level) / atr <= FVG_VA_OVERLAP_ATR)
            return true;
      }
   }
   return false;
}

void OnTick()
{
   if(!InTradeSession(TimeCurrent())) return;

   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   datetime maturityTime  = sessionStart + (BUFFER_MINUTES + MIN_PROFILE_MATURITY_MIN) * 60;
   if(TimeCurrent() < maturityTime) return;

   double poc = 0.0, vah = 0.0, val = 0.0;
   if(!GetValueArea(sessionStart, TimeCurrent(), poc, vah, val)) return;

   if((vah - val) / atr < MIN_VALUE_AREA_ATR) return;

   double dxyClose = iClose("USDX", PERIOD_CURRENT, 0);
   double dxyEma20 = iMA("USDX", PERIOD_CURRENT, 20, 0, MODE_EMA, PRICE_CLOSE, 0);
   bool dollarStrong = (dxyClose > dxyEma20);

   bool bullishReclaim = (Low[0] < val && Close[0] > val && Close[0] > Open[0]);
   bool bearishReclaim = (High[0] > vah && Close[0] < vah && Close[0] < Open[0]);

   if(bullishReclaim && !dollarStrong && HasRecentBullishFVG(val, atr))
   {
      double sl = Low[0] - SL_ATR_MULT * atr;
      double tp = poc + TP_ATR_MULT * atr;
      // OpenBuyOrder(sl, tp)
   }
   else if(bearishReclaim && dollarStrong && HasRecentBearishFVG(vah, atr))
   {
      double sl = High[0] + SL_ATR_MULT * atr;
      double tp = poc - TP_ATR_MULT * atr;
      // OpenSellOrder(sl, tp)
   }
}

Replace the distance-based POC fade with a stationary value-area edge-reversion model. Preserve only the 09:30 UTC opening buffer. Filter out trending/migrating POC regimes by requiring the session POC to be flat within 0.15 ATR over the last 12 bars. Enter only when price violates the Value Area High/Low and closes back inside, with a fresh FVG formed at or near that value-area edge and an above-average volume spike. This changes the causal logic from 'price is far from POC' to 'price has been rejected at the value-area edge and is returning to the session POC with fair-value mitigation nearby'.

Exact MQL5 logic:

input int    SESSION_START_HOUR = 9;
input int    SESSION_START_MIN  = 30;
input int    BUFFER_MINUTES     = 5;
input int    SESSION_END_HOUR   = 11;
input int    SESSION_END_MIN    = 30;
input double FLAT_POC_ATR       = 0.15;
input int    FVG_MAX_AGE_BARS   = 5;
input double FVG_EDGE_BUFFER_ATR = 0.25;
input double VOLUME_SPIKE_MULT  = 1.3;
input double MIN_ATR            = 12.0;

bool InTradeSession(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + BUFFER_MINUTES*60 && t < end);
}

double GetATR()
{
   double buf[1];
   ArraySetAsSeries(buf, true);
   if(CopyBuffer(iATR(_Symbol, PERIOD_CURRENT, 14), 0, 0, 1, buf) <= 0) return 0.0;
   return buf[0];
}

datetime SessionStart(datetime t)
{
   return StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
}

double GetSessionPOC(datetime start, datetime end)
{
   double poc[1];
   ArraySetAsSeries(poc, true);
   int h = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(h == INVALID_HANDLE) return 0.0;
   if(CopyBuffer(h, 0, 0, 1, poc) <= 0) return 0.0;
   return poc[0];
}

double GetValueAreaHigh(datetime start, datetime end)
{
   double vah[1];
   int h = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(h == INVALID_HANDLE) return 0.0;
   if(CopyBuffer(h, 1, 0, 1, vah) <= 0) return 0.0; // buffer 1 = VAH
   return vah[0];
}

double GetValueAreaLow(datetime start, datetime end)
{
   double val[1];
   int h = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(h == INVALID_HANDLE) return 0.0;
   if(CopyBuffer(h, 2, 0, 1, val) <= 0) return 0.0; // buffer 2 = VAL
   return val[0];
}

double AverageVolume(int period)
{
   double sum = 0.0;
   for(int i=0; i<period; i++) sum += (double)iVolume(_Symbol, PERIOD_CURRENT, i);
   return sum / period;
}

bool FreshBullishFVG(int maxAge, double &fvgLow, double &fvgHigh)
{
   for(int i=1; i<=maxAge; i++)
   {
      if(i+2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(High[i+2] < Low[i])
      {
         fvgLow  = High[i+2];
         fvgHigh = Low[i];
         return true;
      }
   }
   return false;
}

bool FreshBearishFVG(int maxAge, double &fvgLow, double &fvgHigh)
{
   for(int i=1; i<=maxAge; i++)
   {
      if(i+2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Low[i+2] > High[i])
      {
         fvgLow  = High[i];
         fvgHigh = Low[i+2];
         return true;
      }
   }
   return false;
}

void OnTick()
{
   if(!InTradeSession(TimeCurrent())) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   datetime s = SessionStart(TimeCurrent());
   if(TimeCurrent() < s + BUFFER_MINUTES*60) return;

   double pocNow = GetSessionPOC(s, TimeCurrent());
   datetime refTime = TimeCurrent() - 12 * PeriodSeconds(PERIOD_CURRENT);
   if(refTime < s + BUFFER_MINUTES*60) return;

   double pocRef = GetSessionPOC(s, refTime);
   double vah = GetValueAreaHigh(s, TimeCurrent());
   double val = GetValueAreaLow(s, TimeCurrent());

   if(pocNow <= 0 || pocRef <= 0 || vah <= 0 || val <= 0) return;

   // Stationary auction filter: block if POC is migrating.
   if(MathAbs(pocNow - pocRef) / atr > FLAT_POC_ATR) return;

   double avgVol = AverageVolume(20);
   double vol0 = (double)iVolume(_Symbol, PERIOD_CURRENT, 0);
   bool volumeSpike = (vol0 > avgVol * VOLUME_SPIKE_MULT);

   double fvgLow = 0.0, fvgHigh = 0.0;
   bool bullishFVG = FreshBullishFVG(FVG_MAX_AGE_BARS, fvgLow, fvgHigh);
   bool bearishFVG = FreshBearishFVG(FVG_MAX_AGE_BARS, fvgLow, fvgHigh);

   // Long: price below POC, downside wick beyond VAL and close back inside VAL,
   // fresh bullish FVG near the lower value area.
   if(bullishFVG && Close[0] < pocNow && Close[0] > val && Low[0] < val && Close[0] > Open[0] && volumeSpike)
   {
      double fvgCenter = (fvgLow + fvgHigh) / 2.0;
      bool fvgAtLowerEdge = (fvgCenter >= val - FVG_EDGE_BUFFER_ATR * atr && fvgCenter <= val + FVG_EDGE_BUFFER_ATR * atr);
      if(fvgAtLowerEdge)
      {
         double sl = fvgLow - 0.5 * atr;
         double tp = pocNow;
         // Execute long: SL below FVG low, TP at session POC
      }
   }

   // Short: price above POC, upside wick beyond VAH and close back inside VAH,
   // fresh bearish FVG near the upper value area.
   if(bearishFVG && Close[0] > pocNow && Close[0] < vah && High[0] > vah && Close[0] < Open[0] && volumeSpike)
   {
      double fvgCenter = (fvgLow + fvgHigh) / 2.0;
      bool fvgAtUpperEdge = (fvgCenter >= vah - FVG_EDGE_BUFFER_ATR * atr && fvgCenter <= vah + FVG_EDGE_BUFFER_ATR * atr);
      if(fvgAtUpperEdge)
      {
         double sl = fvgHigh + 0.5 * atr;
         double tp = pocNow;
         // Execute short: SL above FVG high, TP at session POC
      }
   }
}

Use the validated 09:30 UTC opening buffer. Trade only in the direction of the developing session VWAP/POC skew. Require a fresh FVG within 0.20 ATR of the developing POC. Enter only when price fills the FVG and closes back through its midpoint with a reversal candle. Add a dynamic liquidity gate: current 5-minute volume must be at least 70% of the trailing 10-bar average; spread must be <= 12 points. No static 2 ATR extension, no session high/low sweep, no stale 24-hour FVG. Exact MQL5 logic below.

input int    SESSION_START_HOUR = 9;
input int    SESSION_START_MIN  = 30;
input int    BUFFER_MINUTES     = 5;
input int    NO_NEW_ENTRY_HOUR  = 11;
input int    NO_NEW_ENTRY_MIN   = 30;
input double MIN_ATR            = 12.0;
input int    MAX_SPREAD         = 12;
input double VOLUME_RATIO_MIN   = 0.70;
input double SKEW_ATR           = 0.10;
input double FVG_POC_BAND_ATR   = 0.20;
input int    FVG_MAX_AGE_BARS   = 6;
input double SL_ATR_MULT        = 1.2;
input double TP_ATR_MULT        = 1.6;

datetime SessionStart(datetime t) {
   return StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
}

datetime SessionEnd(datetime t) {
   return StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
}

bool InTradeWindow(datetime t) {
   datetime start = SessionStart(t);
   datetime end   = SessionEnd(t);
   return (t >= start + BUFFER_MINUTES * 60 && t < end);
}

double GetATR() {
   double buf[1];
   if(CopyBuffer(iATR(_Symbol, PERIOD_CURRENT, 14), 0, 0, 1, buf) <= 0) return 0.0;
   return buf[0];
}

double GetSessionPOC(datetime start, datetime end) {
   double poc[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end), 0, 0, 1, poc) <= 0) return 0.0;
   return poc[0];
}

double GetVWAP() {
   double vw[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VWAP"), 0, 0, 1, vw) <= 0) return 0.0;
   return vw[0];
}

double VolumeRatio() {
   double cur = (double)iVolume(_Symbol, PERIOD_CURRENT, 0);
   double sum = 0.0;
   for(int i = 1; i <= 10; i++) sum += (double)iVolume(_Symbol, PERIOD_CURRENT, i);
   if(sum <= 0.0) return 1.0;
   return cur / (sum / 10.0);
}

bool BullishFVG(int shift, double &mid) {
   if(shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   mid = (High[shift + 2] + Low[shift]) / 2.0;
   return (High[shift + 2] < Low[shift]);
}

bool BearishFVG(int shift, double &mid) {
   if(shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   mid = (Low[shift + 2] + High[shift]) / 2.0;
   return (Low[shift + 2] > High[shift]);
}

bool HasBullishFVGNearPOC(double poc, double atr, double &fvgMid) {
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++) {
      if(BullishFVG(i, fvgMid)) {
         if(MathAbs(fvgMid - poc) / atr <= FVG_POC_BAND_ATR && fvgMid <= poc + 0.05 * atr)
            return true;
      }
   }
   return false;
}

bool HasBearishFVGNearPOC(double poc, double atr, double &fvgMid) {
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++) {
      if(BearishFVG(i, fvgMid)) {
         if(MathAbs(fvgMid - poc) / atr <= FVG_POC_BAND_ATR && fvgMid >= poc - 0.05 * atr)
            return true;
      }
   }
   return false;
}

void OnTick() {
   if(!InTradeWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD) return;
   if(VolumeRatio() < VOLUME_RATIO_MIN) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   datetime start = SessionStart(TimeCurrent());
   double poc = GetSessionPOC(start, TimeCurrent());
   double vwap = GetVWAP();
   if(poc <= 0.0 || vwap <= 0.0) return;

   double skew = (vwap - poc) / atr;

   if(skew > SKEW_ATR) {
      double fvgMid = 0.0;
      if(HasBullishFVGNearPOC(poc, atr, fvgMid)) {
         bool mitigated = (Low[0] <= fvgMid && Close[0] > fvgMid && Close[0] > Open[0]);
         if(mitigated) {
            double sl = poc - SL_ATR_MULT * atr;
            double tp = Close[0] + TP_ATR_MULT * atr;
            // OpenBuyOrder(sl, tp);
         }
      }
   } else if(skew < -SKEW_ATR) {
      double fvgMid = 0.0;
      if(HasBearishFVGNearPOC(poc, atr, fvgMid)) {
         bool mitigated = (High[0] >= fvgMid && Close[0] < fvgMid && Close[0] < Open[0]);
         if(mitigated) {
            double sl = poc + SL_ATR_MULT * atr;
            double tp = Close[0] - TP_ATR_MULT * atr;
            // OpenSellOrder(sl, tp);
         }
      }
   }
}

Replace the static POC/VWAP fade with a dynamic Value Area Auction Failure Reversion strategy. Keep only the validated 09:30 UTC opening buffer. Do not fade extension from a fixed anchor. Instead: 1) compute developing session Volume Profile POC/VAH/VAL; 2) require the developing POC to be stable—if POC migration exceeds 0.10 ATR over 15 bars, block fading because the fair value is repricing; 3) require a failed value-area breakout: price pierces VAH/VAL by at least 0.25 ATR and closes back inside the value area; 4) require a subsequent retest of the developing POC with wick-through and close back on the retest side; 5) require an unfilled FVG inside the value area, but not tied to 0.15 ATR POC proximity; 6) require volume-confirmed absorption on the retest bar, using a simple tick-volume spike rather than OBV/MFI. Exact MQL5 logic:

input int    SESSION_START_HOUR   = 9;
input int    SESSION_START_MIN    = 30;
input int    OPENING_BUFFER_MIN   = 5;
input int    SESSION_END_HOUR     = 11;
input int    SESSION_END_MIN      = 30;
input double MIN_ATR              = 12.0;
input double VALUE_AREA_EXCESS_ATR = 0.25;
input double VALUE_AREA_RETEST_ATR = 0.10;
input double POC_MIGRATION_STABILITY_ATR = 0.10;
input int    FVG_MAX_AGE_BARS     = 6;
input double VOLUME_SPIKE_MULT    = 1.3;
input double MAX_SPREAD_POINTS    = 15;

bool InTradeWindow(datetime t) {
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + OPENING_BUFFER_MIN*60 && t < end);
}

double GetATR() {
   double atr[];
   ArraySetAsSeries(atr, true);
   if(CopyBuffer(iATR(_Symbol, _Period, 14), 0, 0, 1, atr) <= 0) return 0.0;
   return atr[0];
}

double GetSessionPOC(datetime start, datetime end) {
   double poc[1];
   if(CopyBuffer(iCustom(_Symbol, _Period, "VolumeProfile", start, end), 0, 0, 1, poc) <= 0) return 0.0;
   return poc[0];
}

double GetSessionVAH(datetime start, datetime end) {
   double vah[1];
   if(CopyBuffer(iCustom(_Symbol, _Period, "VolumeProfile", start, end), 2, 0, 1, vah) <= 0) return 0.0;
   return vah[0];
}

double GetSessionVAL(datetime start, datetime end) {
   double val[1];
   if(CopyBuffer(iCustom(_Symbol, _Period, "VolumeProfile", start, end), 3, 0, 1, val) <= 0) return 0.0;
   return val[0];
}

bool HasBullishFVGInValueArea(double vah, double val, double atr) {
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++) {
      if(i + 2 >= Bars(_Symbol, _Period)) break;
      if(High[i + 2] < Low[i]) {
         double mid = (High[i + 2] + Low[i]) / 2.0;
         if(mid >= val - 0.25 * atr && mid <= vah + 0.25 * atr) return true;
      }
   }
   return false;
}

bool HasBearishFVGInValueArea(double vah, double val, double atr) {
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++) {
      if(i + 2 >= Bars(_Symbol, _Period)) break;
      if(Low[i + 2] > High[i]) {
         double mid = (Low[i + 2] + High[i]) / 2.0;
         if(mid >= val - 0.25 * atr && mid <= vah + 0.25 * atr) return true;
      }
   }
   return false;
}

bool BullishAbsorptionBar() {
   double avgVol = iMA(_Symbol, _Period, 20, 0, MODE_SMA, PRICE_TICK, 0);
   return (Close[0] > Open[0] && Close[0] > (High[0] + Low[0]) / 2.0 && (double)iVolume(_Symbol, _Period, 0) > VOLUME_SPIKE_MULT * avgVol);
}

bool BearishAbsorptionBar() {
   double avgVol = iMA(_Symbol, _Period, 20, 0, MODE_SMA, PRICE_TICK, 0);
   return (Close[0] < Open[0] && Close[0] < (High[0] + Low[0]) / 2.0 && (double)iVolume(_Symbol, _Period, 0) > VOLUME_SPIKE_MULT * avgVol);
}

void OnTick() {
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);
   ArraySetAsSeries(Open, true);

   if(!InTradeWindow(TimeCurrent())) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   long spread = SymbolInfoInteger(_Symbol, SYMBOL_SPREAD);
   if(spread > MAX_SPREAD_POINTS) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   datetime now = TimeCurrent();
   if(now < sessionStart + OPENING_BUFFER_MIN * 60) return;

   double pocNow = GetSessionPOC(sessionStart, now);
   double pocPrev = GetSessionPOC(sessionStart, now - 15 * PeriodSeconds(_Period));
   if(pocNow <= 0.0 || pocPrev <= 0.0) return;

   double migration = (pocNow - pocPrev) / atr;
   if(MathAbs(migration) > POC_MIGRATION_STABILITY_ATR) return; // POC is repricing; do not fade

   double vah = GetSessionVAH(sessionStart, now);
   double val = GetSessionVAL(sessionStart, now);
   if(vah <= 0.0 || val <= 0.0) return;

   bool bullishFailedAuction = (Low[0] < val - VALUE_AREA_EXCESS_ATR * atr && Close[0] > val);
   bool bearishFailedAuction = (High[0] > vah + VALUE_AREA_EXCESS_ATR * atr && Close[0] < vah);

   bool bullishRetest = (Low[0] <= pocNow - VALUE_AREA_RETEST_ATR * atr && Close[0] > pocNow && Close[0] > Open[0]);
   bool bearishRetest = (High[0] >= pocNow + VALUE_AREA_RETEST_ATR * atr && Close[0] < pocNow && Close[0] < Open[0]);

   bool bullFVG = HasBullishFVGInValueArea(vah, val, atr);
   bool bearFVG = HasBearishFVGInValueArea(vah, val, atr);

   if(bullishFailedAuction && bullishRetest && bullFVG && BullishAbsorptionBar()) {
      double sl = val - 1.0 * atr;
      double tp = vah;
      // OpenBuyOrder(sl, tp);
   }
   else if(bearishFailedAuction && bearishRetest && bearFVG && BearishAbsorptionBar()) {
      double sl = vah + 1.0 * atr;
      double tp = val;
      // OpenSellOrder(sl, tp);
   }
}

Exact MQL5 logic: Use trend-aligned Fair Value Mitigation at the VP POC, not extension fading. 1) 09:35-11:15 UTC window with spread guard. 2) ATR floor. 3) Long bias: EMA20 > EMA50, ADX > 20, +DI > -DI. Short bias: mirror. 4) Find an unmitigated FVG within 0.35 ATR of the developing session POC, max age 6 bars. 5) Wait for a rejection at the FVG midpoint: lower/upper wick >= 0.25 ATR, close back beyond the midpoint, close in the bias direction, and Volume[0] > 1.25 * Volume[1]. 6) Stop below/above FVG boundary, target 1.75R. Code:

#property strict

input int SESSION_START_HOUR=9;
input int SESSION_START_MIN=30;
input int BUFFER_MINUTES=5;
input int NO_NEW_ENTRY_HOUR=11;
input int NO_NEW_ENTRY_MIN=15;
input double MIN_ATR=12.0;
input double MAX_SPREAD=15.0;
input int FVG_MAX_AGE_BARS=6;
input double FVG_POC_OVERLAP_ATR=0.35;
input double REJECTION_WICK_ATR=0.25;
input double VOLUME_SPIKE_RATIO=1.25;
input int ADX_PERIOD=14;
input double ADX_MIN=20.0;
input int EMA_FAST=20;
input int EMA_SLOW=50;
