bool FindBullishFVGAtPOC(double poc,double atr,double &mid,double &lower,double &upper){
 for(int i=1;i<=FVG_MAX_AGE_BARS;i++){
 double m,l,u;
 if(BullishFVG(i,m,l,u)){
 if(MathAbs(m-poc)/atr <= FVG_POC_OVERLAP_ATR){ mid=m; lower=l; upper=u; return true; }
 }
 }
 return false;
