 if(MathAbs(m-poc)/atr <= FVG_POC_OVERLAP_ATR){ mid=m; lower=l; upper=u; return true; }
 }
 }
 return false;
}

bool IsLongBias(){
 return (GetEMA(EMA_FAST,0) > GetEMA(EMA_SLOW,0) && GetADX(0) > ADX_MIN && GetADX(1) > GetADX(2));
}

bool IsShortBias(){
 return (GetEMA(EMA_FAST,0) < GetEMA(EMA_SLOW,0) && GetADX(0) > ADX_MIN && GetADX(2) > GetADX(1));
}

bool BullishRejection(double fvgMid,double atr){
 if(Close[0] <= Open[0] || Close[0] <= fvgMid || Low[0] >= fvgMid) return false;
 double lowerWick=(Open[0] < Close[0] ? Open[0] : Close[0])-Low[0];
 if(lowerWick < REJECTION_WICK_ATR*atr) return false;
 if((double)Volume[0] <= (double)Volume[1]*VOLUME_SPIKE_RATIO) return false;
 return true;
}

bool BearishRejection(double fvgMid,double atr){
 if(Close[0] >= Open[0] || Close[0] >= fvgMid || High[0] <= fvgMid) return false;
 double upperWick=High[0]-(Open[0] > Close[0] ? Open[0] : Close[0]);
 if(upperWick < REJECTION_WICK_ATR*atr) return false;
 if((double)Volume[0] <= (double)Volume[1]*VOLUME_SPIKE_RATIO) return false;
 return true;
}

void OnTick(){
 ArraySetAsSeries(Open,true);
 ArraySetAsSeries(High,true);
 ArraySetAsSeries(Low,true);
