 if(BullishRejection(mid,atr)){
 double sl=lower-SL_ATR_MULT*atr;
 double tp=Close[0]+TP_ATR_MULT*atr;
 // Execute BUY
 }
 }
 else if(IsShortBias() && FindBearishFVGAtPOC(poc,atr,mid,lower,upper)){
 if(BearishRejection(mid,atr)){
 double sl=upper+SL_ATR_MULT*atr;
 double tp=Close[0]-TP_ATR_MULT*atr;
 // Execute SELL
 }
 }
}

The following exact MQL5 repair logic replaces the old fade with a trend-aligned VPOC value-area retest, confirmed by Chaikin Money Flow, and targets an unfilled FVG on the profit side. It enforces the validated 09:30 UTC opening buffer and does not repeat any debunked entry logic.

input int    SESSION_START_HOUR   = 9;
input int    SESSION_START_MIN    = 30;
input int    BUFFER_MINUTES       = 5;
input int    SESSION_END_HOUR     = 11;
input int    SESSION_END_MIN      = 30;
input double MIN_ATR              = 12.0;
input double RETEST_ZONE_ATR      = 0.15;
input double EXCURSION_ATR        = 0.75;
input double CMF_LEVEL            = 0.05;
input double H4_SLOPE_ATR_MIN     = 0.05;
input int    FVG_MAX_AGE_BARS     = 24;
input double FVG_MIN_DIST_ATR     = 0.5;
input double SL_ATR_MULT          = 0.5;

bool InTradeWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + BUFFER_MINUTES*60 && t < end);
}

double GetATR()
{
   double a[1];
   if(CopyBuffer(iATR(_Symbol, PERIOD_CURRENT, 14), 0, 0, 1, a) <= 0) return 0.0;
   return a[0];
}

double GetH4Bias()
{
   double ema = iMA(_Symbol, PERIOD_H4, 50, 0, MODE_EMA, PRICE_CLOSE, 0);
   double emaPrev = iMA(_Symbol, PERIOD_H4, 50, 0, MODE_EMA, PRICE_CLOSE, 1);
   double atrH4 = iATR(_Symbol, PERIOD_H4, 14, 0);
   if(atrH4 <= 0.0) return 0.0;
   double slope = (ema - emaPrev) / atrH4;
   if(slope > H4_SLOPE_ATR_MIN) return 1.0;
   if(slope < -H4_SLOPE_ATR_MIN) return -1.0;
   return 0.0;
}

double GetCMF()
{
   double c[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "ChaikinMoneyFlow", 20), 0, 0, 1, c) <= 0) return 0.0;
   return c[0];
}

bool GetSessionValueArea(datetime start, datetime end, double &poc, double &vah, double &val)
{
   int vp = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   double p[1], h[1], l[1];
   if(CopyBuffer(vp, 0, 0, 1, p) <= 0) return false;
   if(CopyBuffer(vp, 3, 0, 1, h) <= 0) return false;
   if(CopyBuffer(vp, 4, 0, 1, l) <= 0) return false;
   poc = p[0];
   vah = h[0];
   val = l[0];
   return (poc > 0.0 && vah > val);
}

double GetBullishTargetFVG(double entry, double atr)
{
   double best = EMPTY_VALUE;
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(High[i + 2] < Low[i])
      {
         double mid = (High[i + 2] + Low[i]) / 2.0;
         if(mid > entry + FVG_MIN_DIST_ATR * atr)
         {
            if(best == EMPTY_VALUE || mid < best) best = mid;
         }
      }
   }
   return best;
}

double GetBearishTargetFVG(double entry, double atr)
{
   double best = EMPTY_VALUE;
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Low[i + 2] > High[i])
      {
         double mid = (Low[i + 2] + High[i]) / 2.0;
         if(mid < entry - FVG_MIN_DIST_ATR * atr)
         {
            if(best == EMPTY_VALUE || mid > best) best = mid;
         }
      }
   }
   return best;
}

void OnTick()
{
   if(!InTradeWindow(TimeCurrent())) return;
   double atr = GetATR();
   if(atr < MIN_ATR) return;
   double bias = GetH4Bias();
   if(bias == 0.0) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   double poc, vah, val;
   if(!GetSessionValueArea(sessionStart, TimeCurrent(), poc, vah, val)) return;
   if(poc <= 0.0 || vah <= 0.0 || val <= 0.0) return;
   if(poc > vah || poc < val) return;
   if((vah - val) / atr < 1.0) return;

   double cmf = GetCMF();
   bool belowPOC = false, abovePOC = false;
   for(int i = 1; i <= 20; i++)
   {
      if(Low[i] < poc - EXCURSION_ATR * atr) belowPOC = true;
      if(High[i] > poc + EXCURSION_ATR * atr) abovePOC = true;
   }

   double entry = Close[0];
   if(bias == 1.0 && belowPOC && cmf > CMF_LEVEL)
   {
      if(MathAbs(entry - poc) <= RETEST_ZONE_ATR * atr)
      {
         double tp = GetBullishTargetFVG(entry, atr);
         if(tp > 0.0)
         {
            double sl = val - SL_ATR_MULT * atr;
            Print("Module_1 BUY: entry=", entry, " sl=", sl, " tp=", tp);
            // OpenBuyOrder(sl, tp);
         }
      }
   }
   else if(bias == -1.0 && abovePOC && cmf < -CMF_LEVEL)
   {
      if(MathAbs(entry - poc) <= RETEST_ZONE_ATR * atr)
      {
         double tp = GetBearishTargetFVG(entry, atr);
         if(tp > 0.0)
         {
            double sl = vah + SL_ATR_MULT * atr;
            Print("Module_1 SELL: entry=", entry, " sl=", sl, " tp=", tp);
            // OpenSellOrder(sl, tp);
         }
      }
   }
}

