input double ENTRY_EXT_ATR_MAX    = 3.0;
input int    FVG_MAX_AGE_BARS     = 6;
input double MIN_VOLUME_RATIO     = 0.80;
input int    MAX_SPREAD_POINTS    = 12;

bool InTradeWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime noNew = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + OPENING_BUFFER_MIN * 60 && t < noNew);
}

double GetATR()
{
   int h = iATR(_Symbol, PERIOD_CURRENT, 14);
   if(h == INVALID_HANDLE) return 0.0;
   double buf[1]; ArraySetAsSeries(buf, true);
   if(CopyBuffer(h, 0, 0, 1, buf) <= 0) { IndicatorRelease(h); return 0.0; }
   IndicatorRelease(h);
   return buf[0];
}

double GetADX()
{
   int h = iADX(_Symbol, PERIOD_CURRENT, 14, PRICE_CLOSE);
   if(h == INVALID_HANDLE) return 100.0;
   double buf[1]; ArraySetAsSeries(buf, true);
   if(CopyBuffer(h, 0, 0, 1, buf) <= 0) { IndicatorRelease(h); return 100.0; }
   IndicatorRelease(h);
   return buf[0];
}

double GetSessionPOC(datetime start, datetime end)
{
   int h = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(h == INVALID_HANDLE) return 0.0;
   double poc[1]; ArraySetAsSeries(poc, true);
   if(CopyBuffer(h, 0, 0, 1, poc) <= 0) { IndicatorRelease(h); return 0.0; }
   IndicatorRelease(h);
   return poc[0];
}

double GetSessionVWAP(datetime start)
{
   int h = iCustom(_Symbol, PERIOD_CURRENT, "VWAP", start);
   if(h == INVALID_HANDLE) return 0.0;
   double vw[1]; ArraySetAsSeries(vw, true);
   if(CopyBuffer(h, 0, 0, 1, vw) <= 0) { IndicatorRelease(h); return 0.0; }
   IndicatorRelease(h);
   return vw[0];
}

double AverageTickVolume(int period)
{
   double sum = 0.0;
   for(int i = 0; i < period; i++)
      sum += (double)iVolume(_Symbol, PERIOD_CURRENT, i);
   return sum / period;
}

bool HasRecentBearishFVG(double &mid)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      // Bearish FVG: Low[i+2] > High[i] (gap up leaving a supply imbalance)
      if(Low[i + 2] > High[i])
      {
         mid = (Low[i + 2] + High[i]) / 2.0;
         return true;
      }
   }
   return false;
}

bool HasRecentBullishFVG(double &mid)
{
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      // Bullish FVG: High[i+2] < Low[i] (gap down leaving a demand imbalance)
      if(High[i + 2] < Low[i])
      {
         mid = (High[i + 2] + Low[i]) / 2.0;
         return true;
      }
   }
   return false;
}

void OnTick()
{
   if(!InTradeWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   double adx = GetADX();
   if(adx > MAX_ADX) return;

   double avgVol = AverageTickVolume(20);
   if(iVolume(_Symbol, PERIOD_CURRENT, 0) < MIN_VOLUME_RATIO * avgVol) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   if(TimeCurrent() < sessionStart + OPENING_BUFFER_MIN * 60) return;

   double pocNow = GetSessionPOC(sessionStart, TimeCurrent());
   double vwap   = GetSessionVWAP(sessionStart);
   if(pocNow <= 0.0 || vwap <= 0.0) return;

   datetime refTime = TimeCurrent() - POC_STABILITY_BARS * PeriodSeconds(PERIOD_CURRENT);
   if(refTime < sessionStart + OPENING_BUFFER_MIN * 60) return;

   double pocRef = GetSessionPOC(sessionStart, refTime);
   if(pocRef <= 0.0) return;

   double pocDrift = (pocNow - pocRef) / atr;
   if(MathAbs(pocDrift) > POC_STABILITY_ATR) return;

   double extension = (Close[0] - pocNow) / atr;

   double fvgMid = 0.0;
   bool hasFVG = false;

   // SHORT fade: price extended above stable POC, fresh bearish FVG between POC and price.
   if(extension >= ENTRY_EXT_ATR_MIN && extension <= ENTRY_EXT_ATR_MAX)
   {
      hasFVG = HasRecentBearishFVG(fvgMid);
      if(hasFVG && fvgMid > pocNow && fvgMid < Close[0])
      {
         if(Close[0] < Open[0] && Close[0] < vwap)
         {
            double sl = Close[0] + 1.5 * atr;
            double tp = pocNow + 0.25 * atr;
            // OpenSellOrder(sl, tp);
         }
      }
   }
   // LONG fade: price extended below stable POC, fresh bullish FVG between price and POC.
   else if(extension <= -ENTRY_EXT_ATR_MIN && extension >= -ENTRY_EXT_ATR_MAX)
   {
      hasFVG = HasRecentBullishFVG(fvgMid);
      if(hasFVG && fvgMid < pocNow && fvgMid > Close[0])
      {
         if(Close[0] > Open[0] && Close[0] > vwap)
         {
            double sl = Close[0] - 1.5 * atr;
            double tp = pocNow - 0.25 * atr;
            // OpenBuyOrder(sl, tp);
         }
      }
   }
}

input int SESSION_START_HOUR = 9;
input int SESSION_START_MIN = 30;
input int BUFFER_MINUTES = 5;
input double MIN_ATR = 12.0;
input double POC_STABILITY_ATR = 0.20;
input double POC_CENTRALITY_MIN = 0.25;
input double POC_CENTRALITY_MAX = 0.75;
input double ENTRY_EXT_MIN_ATR = 0.75;
input double ENTRY_EXT_MAX_ATR = 2.25;
input int FVG_MAX_AGE_BARS = 8;
input double FVG_POC_OVERLAP_ATR = 0.20;
input double VOL_POC_MULT = 1.25;
input int LR_PERIOD = 20;
input double LR_R2_MAX = 0.55;
input double LR_NORM_SLOPE_MAX = 0.07;

bool InTradeWindow(datetime t)
