double SMA(double arr[], int size)
{
   if(size <= 0) return 0.0;
   double sum = 0.0;
   for(int i = 0; i < size; i++)
      sum += arr[i];
   return sum / size;
}

bool IsPOCStable(datetime start, double atr)
{
