   if(ref < start + BUFFER_MINUTES * 60) return false;
   double pocNow = GetSessionPOC(start, TimeCurrent());
   double pocRef = GetSessionPOC(start, ref);
   if(pocNow <= 0.0 || pocRef <= 0.0) return false;
   return (MathAbs(pocNow - pocRef) / atr < POC_STABILITY_ATR);
}

bool HasRecentBullishFVG(double poc, double atr, double &mid)
