   double sessionLow = Low[iLowest(_Symbol, PERIOD_CURRENT, MODE_LOW, bars, 0)];
   double range = sessionHigh - sessionLow;
   if(range < 2.0 * atr) return;

   double centrality = (poc - sessionLow) / range;
   if(centrality < POC_CENTRALITY_MIN || centrality > POC_CENTRALITY_MAX) return;

   if(!IsPOCStable(sessionStart, atr)) return;

   double extension = MathAbs(Close[0] - poc) / atr;
   if(extension < ENTRY_EXT_MIN_ATR || extension > ENTRY_EXT_MAX_ATR) return;

   double lrSlope = LinearRegressionSlope(LR_PERIOD);
   double lrR2 = LinearRegressionR2(LR_PERIOD);
   double normSlope = MathAbs(lrSlope) / atr;
   if(lrR2 > LR_R2_MAX && normSlope > LR_NORM_SLOPE_MAX) return;

   double dxySlope = 0.0;
   double dxy0 = iClose("USDX", PERIOD_H1, 0);
   double dxy4 = iClose("USDX", PERIOD_H1, 4);
   if(dxy0 > 0 && dxy4 > 0) dxySlope = (dxy0 - dxy4) / 4.0;
   double dxyBeta = -0.75; // Replace with live DXY_Beta custom indicator if available.
