double GetDeltaDivergence(int lookback=10)
{
   double current = (Close[0]-Open[0]) * (double)iVolume(_Symbol,_Period,0);
   double sum = 0.0;
   for(int i=1;i<=lookback;i++)
      sum += (Close[i]-Open[i]) * (double)iVolume(_Symbol,_Period,i);
   double avg = sum/lookback;
   double atr = GetATR();
   if(atr <= 0.0) return 0.0;
   return (current - avg)/atr;
