      if(BearishFVG(i,mid))
         if(mid >= vaLow && mid <= vaHigh && MathAbs(mid-poc)/vaWidth <= Inp_FVG_VA_Proximity)
            return true;
   }
   return false;
}

void OnTick()
{
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);

   if(!InTradeWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol,SYMBOL_SPREAD) > 15) return;

   double atr = GetATR();
   if(atr < Inp_MinATR) return;

   double adx = iADX(_Symbol,_Period,14,PRICE_CLOSE,MODE_MAIN,0);
   if(adx > Inp_MaxADX) return;

   double slope = LinearRegressionSlope(20);
   double r2 = LinearRegressionR2(20);
   double normSlope = MathAbs(slope)/atr;
   if(r2 > Inp_MaxLR_R2 || normSlope > Inp_MaxLR_Slope_Norm) return;

   datetime start = SessionStart(TimeCurrent());
   double poc = GetSessionPOC(start, TimeCurrent());
   double vwap = GetSessionVWAP();
   if(poc <= 0.0 || vwap <= 0.0) return;

   double vaHigh = GetValueAreaHigh(start, TimeCurrent());
   double vaLow = GetValueAreaLow(start, TimeCurrent());
   double vaWidth = vaHigh - vaLow;
   if(vaWidth <= 0.0 || vaWidth > Inp_VA_Width_Max_ATR*atr) return;

   double deltaDiv = GetDeltaDivergence();
   double dxyBeta = iCustom(_Symbol,PERIOD_H1,"DXY_Beta",0,0);
   double dxyMom = iCustom(_Symbol,PERIOD_H1,"DXY_Momentum",0,0);

   bool longSignal = false;
   bool shortSignal = false;

   if(Low[0] < vaLow && Close[0] > vaLow &&
      deltaDiv > Inp_DeltaDivergenceMin &&
      HasBullishFVGInsideVA(vaLow, vaHigh, poc, atr))
   {
      // Block DE40 longs against a dollar rally only when price is above POC in this inverse regime
      if(!(dxyBeta < -0.75 && dxyMom > 0.0 && Close[0] > poc))
         longSignal = true;
   }

   if(High[0] > vaHigh && Close[0] < vaHigh &&
      deltaDiv < -Inp_DeltaDivergenceMin &&
      HasBearishFVGInsideVA(vaLow, vaHigh, poc, atr))
   {
      // Block DE40 shorts against a dollar drop only when price is below POC in this inverse regime
      if(!(dxyBeta < -0.75 && dxyMom < 0.0 && Close[0] < poc))
         shortSignal = true;
   }

   if(longSignal)
   {
      double stop = Low[0] - 0.5*atr;
      double target = poc; // primary reversion target; use next HVN if available
      // SendBuyOrder(stop, target);
   }
   else if(shortSignal)
   {
      double stop = High[0] + 0.5*atr;
      double target = poc; // primary reversion target; use next HVN if available
      // SendSellOrder(stop, target);
   }
}

