double GetDeltaSum(int period) {
   double sum = 0.0;
   for(int i=0; i<period; i++) {
      double range = High[i] - Low[i];
      if(range > 0)
         sum += (Close[i] - Open[i]) * TickVolume[i] / range;
   }
   return sum;
