   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(TickVolume, true);

   if(!InTradeSession(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   // Previous day's session POC as stable fair value anchor
   datetime todayStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   datetime prevStart = todayStart - 86400; // previous day same time (DST may need adjustment)
   datetime prevEnd = prevStart + 2*3600;
   double prevPOC = GetSessionPOC(prevStart, prevEnd);
   if(prevPOC <= 0.0) return;

   double currentVWAP = GetSessionVWAP();
   if(currentVWAP <= 0.0) return;

   double ext = (Close[0] - prevPOC) / atr;
   double deltaSum = GetDeltaSum(DELTA_PERIOD);

   // Long: price is below previous day's POC by at least 1.5 ATR, current VWAP is above price,
   // a recent bullish FVG below prev POC has been mitigated, and cumulative delta is positive.
   bool longCondition = (ext < -ENTRY_EXT_ATR && currentVWAP > Close[0]);
   double fvgMid = 0.0;
   bool bullishFVG = GetBullishFVG(prevPOC, atr, fvgMid);
   bool longFVGMitigated = (bullishFVG && Low[0] < fvgMid && Close[0] > fvgMid);
   if(longCondition && longFVGMitigated && deltaSum > DELTA_THRESHOLD) {
      double sl = Low[0] - SL_ATR_MULT * atr;
      double tp = prevPOC; // revert to previous day's POC
      // OpenBuyOrder(sl, tp);
   }

   // Short: price is above previous day's POC by at least 1.5 ATR, current VWAP is below price,
   // a recent bearish FVG above prev POC has been mitigated, and cumulative delta is negative.
   bool shortCondition = (ext > ENTRY_EXT_ATR && currentVWAP < Close[0]);
   bool bearishFVG = GetBearishFVG(prevPOC, atr, fvgMid);
   bool shortFVGMitigated = (bearishFVG && High[0] > fvgMid && Close[0] < fvgMid);
   if(shortCondition && shortFVGMitigated && deltaSum < -DELTA_THRESHOLD) {
      double sl = High[0] + SL_ATR_MULT * atr;
      double tp = prevPOC; // revert to previous day's POC
      // OpenSellOrder(sl, tp);
   }
}

