bool BullishFVG(int shift, double &mid)
{
   if(shift < 0 || shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   if(High[shift + 2] < Low[shift])
   {
      mid = (High[shift + 2] + Low[shift]) / 2.0;
      return true;
   }
   return false;
}

bool BearishFVG(int shift, double &mid)
{
   if(shift < 0 || shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   if(Low[shift + 2] > High[shift])
   {
      mid = (Low[shift + 2] + High[shift]) / 2.0;
      return true;
   }
   return false;
}

bool HasRecentBullishFVGAtPrice(int maxAge, double refPrice, double atr, double tolATR, double &mid)
{
   for(int i = 1; i <= maxAge; i++)
   {
      double m = 0.0;
      if(BullishFVG(i, m) && MathAbs(m - refPrice) / atr <= tolATR)
      {
         mid = m;
         return true;
      }
   }
   return false;
}

bool HasRecentBearishFVGAtPrice(int maxAge, double refPrice, double atr, double tolATR, double &mid)
{
   for(int i = 1; i <= maxAge; i++)
   {
      double m = 0.0;
      if(BearishFVG(i, m) && MathAbs(m - refPrice) / atr <= tolATR)
      {
         mid = m;
         return true;
      }
   }
   return false;
}

