   for(int i=0; i<count; i++) sum += (double)iVolume(_Symbol, PERIOD_CURRENT, i);
   return sum / count;
}

bool FindBullishFVG(int &shift, double &mid, double &upper, double &lower)
{
   for(int i=1; i<FVG_MAX_AGE_BARS; i++)
   {
      if(i+2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(High[i+2] < Low[i])
      {
         shift = i;
         upper = Low[i];
         lower = High[i+2];
         mid = (upper + lower) / 2.0;
         return true;
      }
   }
   return false;
}

bool FindBearishFVG(int &shift, double &mid, double &upper, double &lower)
{
   for(int i=1; i<FVG_MAX_AGE_BARS; i++)
   {
      if(i+2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Low[i+2] > High[i])
      {
         shift = i;
         upper = Low[i+2];
         lower = High[i];
         mid = (upper + lower) / 2.0;
         return true;
      }
   }
   return false;
