void OnTick()
{
   if(!InTradeWindow(TimeCurrent())) return;

   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   double pocNow = GetSessionPOC(sessionStart, TimeCurrent());
   if(pocNow <= 0.0) return;

   datetime refTime = TimeCurrent() - 3 * PeriodSeconds(PERIOD_CURRENT);
   if(refTime < sessionStart + BUFFER_MINUTES * 60) refTime = sessionStart + BUFFER_MINUTES * 60;
   double pocRef = GetSessionPOC(sessionStart, refTime);
   if(pocRef <= 0.0) return;

   double migration = (pocNow - pocRef) / atr;
   double avgVol = GetAvgTickVolume(20);
   double currentVol = (double)iVolume(_Symbol, PERIOD_CURRENT, 0);
   if(avgVol <= 0) return;

   double volAbove = 0.0, volBelow = 0.0;
   for(int i=0; i<20; i++)
   {
      if(Close[i] > pocNow) volAbove += (double)iVolume(_Symbol, PERIOD_CURRENT, i);
      else if(Close[i] < pocNow) volBelow += (double)iVolume(_Symbol, PERIOD_CURRENT, i);
   }
   double skewUp = (volAbove + volBelow > 0) ? (volAbove / (volAbove + volBelow)) : 0.5;

   int shift = 0;
   double mid = 0.0, upper = 0.0, lower = 0.0;

   if(migration > POC_MIGRATION_ATR && skewUp > 0.55)
   {
      if(FindBullishFVG(shift, mid, upper, lower))
      {
         if(MathAbs(mid - pocNow) / atr <= FVG_OVERLAP_ATR)
         {
            if(Low[0] <= mid && Close[0] > mid && Close[0] > Open[0] && currentVol > avgVol * VOLUME_RATIO)
            {
               double sl = lower - 0.25 * atr;
               if(sl >= Close[0]) sl = Close[0] - 0.5 * atr;
               double tp = Close[0] + TP_ATR_MULT * atr;
               // ExecuteBuy(sl, tp)
            }
         }
      }
   }
   else if(migration < -POC_MIGRATION_ATR && skewUp < 0.45)
   {
      if(FindBearishFVG(shift, mid, upper, lower))
      {
         if(MathAbs(mid - pocNow) / atr <= FVG_OVERLAP_ATR)
         {
            if(High[0] >= mid && Close[0] < mid && Close[0] < Open[0] && currentVol > avgVol * VOLUME_RATIO)
            {
               double sl = upper + 0.25 * atr;
               if(sl <= Close[0]) sl = Close[0] + 0.5 * atr;
               double tp = Close[0] - TP_ATR_MULT * atr;
               // ExecuteSell(sl, tp)
            }
         }
      }
   }
}

Replace the static distance-to-POC fade with a balanced-VPOC absorption engine. The exact MQL5 logic is below. It uses VPOC plateau (not migration), value-area rotation, cumulative delta absorption, and FVG mitigation at POC.

input int SESSION_START_HOUR = 9;
input int SESSION_START_MIN = 30;
input int OPENING_BUFFER_MIN = 5;
input int SESSION_END_HOUR = 11;
input int SESSION_END_MIN = 30;
input double MIN_ATR = 12.0;
input double POC_PLATEAU_ATR = 0.08;
input int DELTA_ABSORPTION_BARS = 5;
input int FVG_MAX_AGE_BARS = 12;
input double FVG_POC_PROX_ATR = 0.20;
input double SL_ATR = 1.2;
input double TP_ATR = 2.0;
input int MAX_SPREAD_POINTS = 15;
input int MIN_TICK_VOL_15M = 1000;

datetime SessionStart(datetime t) { return StringToTime(TimeToString(t, TIME_DATE) + " 09:30"); }
datetime SessionEnd(datetime t)   { return StringToTime(TimeToString(t, TIME_DATE) + " 11:30"); }

bool InTradeWindow(datetime t)
{
   return(t >= SessionStart(t) + OPENING_BUFFER_MIN * 60 && t < SessionEnd(t));
}

double GetATR()
{
   double b[1]; ArraySetAsSeries(b,true);
   int h = iATR(_Symbol, PERIOD_CURRENT, 14);
   if(CopyBuffer(h, 0, 0, 1, b) <= 0) return 0.0;
   return b[0];
}

double GetPOC(datetime start, datetime end)
{
   double b[1]; ArraySetAsSeries(b,true);
   int h = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(h == INVALID_HANDLE || CopyBuffer(h, 0, 0, 1, b) <= 0) return 0.0;
   return b[0];
}

double GetVAH(datetime start, datetime end)
{
   double b[1]; ArraySetAsSeries(b,true);
   int h = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(h == INVALID_HANDLE || CopyBuffer(h, 2, 0, 1, b) <= 0) return 0.0;
   return b[0];
}

double GetVAL(datetime start, datetime end)
{
   double b[1]; ArraySetAsSeries(b,true);
   int h = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(h == INVALID_HANDLE || CopyBuffer(h, 3, 0, 1, b) <= 0) return 0.0;
   return b[0];
}

double GetADX()
{
   double b[1]; ArraySetAsSeries(b,true);
   int h = iADX(_Symbol, PERIOD_CURRENT, 14, PRICE_CLOSE, MODE_MAIN, 0);
   if(CopyBuffer(h, 0, 0, 1, b) <= 0) return 100.0;
   return b[0];
}

double GetCumulativeDelta(int lookback)
{
   int h = iCustom(_Symbol, PERIOD_CURRENT, "OrderFlowDelta");
   double sum = 0.0;
   if(h != INVALID_HANDLE)
   {
      for(int i=0; i<lookback; i++)
      {
         double b[1]; ArraySetAsSeries(b,true);
         if(CopyBuffer(h, 0, i, 1, b) > 0) sum += b[0];
      }
      return sum;
   }
   // Fallback: signed tick-volume proxy if OrderFlowDelta is unavailable.
   for(int i=0; i<lookback; i++)
   {
      double body = Close[i] - Open[i];
      long vol = iVolume(_Symbol, PERIOD_CURRENT, i);
      if(body > 0) sum += (double)vol;
      else if(body < 0) sum -= (double)vol;
   }
   return sum;
}

bool LiquidEnough()
{
   long vol15 = 0;
   for(int i=0; i<15; i++) vol15 += iVolume(_Symbol, PERIOD_CURRENT, i);
   if(vol15 < MIN_TICK_VOL_15M) return false;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return false;
   return true;
}

void OnTick()
{
   ArraySetAsSeries(Close,true);
   ArraySetAsSeries(Open,true);
   ArraySetAsSeries(High,true);
   ArraySetAsSeries(Low,true);

   if(!InTradeWindow(TimeCurrent())) return;
   if(!LiquidEnough()) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   // Balanced auction gate: no mean reversion in a directional regime.
   if(GetADX() >= 20.0) return;

   datetime sessionStart = SessionStart(TimeCurrent());
   datetime now = TimeCurrent();

   double pocNow = GetPOC(sessionStart, now);
   double pocPrev = GetPOC(sessionStart, now - 6 * PeriodSeconds(PERIOD_CURRENT));
   if(pocNow <= 0.0 || pocPrev <= 0.0) return;

   // VPOC plateau: fade only when POC is stable, not migrating.
   if(MathAbs(pocNow - pocPrev) / atr > POC_PLATEAU_ATR) return;

   double vah = GetVAH(sessionStart, now);
   double val = GetVAL(sessionStart, now);
   if(vah <= 0.0 || val <= 0.0) return;

   // Price must remain inside the value area: rotation, not breakout.
   if(Close[0] > vah || Close[0] < val) return;

   double delta = GetCumulativeDelta(DELTA_ABSORPTION_BARS);

   bool bullishSignal = false;
   bool bearishSignal = false;

   // Long: absorption below POC, close back above POC, and bullish FVG near POC.
   if(Low[0] < pocNow - 0.15 * atr && Close[0] > pocNow && delta > 0.0)
   {
      for(int i=1; i<FVG_MAX_AGE_BARS && i+2<Bars(_Symbol, PERIOD_CURRENT); i++)
      {
         if(High[i+2] < Low[i])
         {
            double fvgMid = (High[i+2] + Low[i]) / 2.0;
            if(MathAbs(fvgMid - pocNow) / atr <= FVG_POC_PROX_ATR)
            {
               bullishSignal = true;
               break;
            }
         }
      }
   }

   // Short: absorption above POC, close back below POC, and bearish FVG near POC.
   if(High[0] > pocNow + 0.15 * atr && Close[0] < pocNow && delta < 0.0)
   {
      for(int i=1; i<FVG_MAX_AGE_BARS && i+2<Bars(_Symbol, PERIOD_CURRENT); i++)
      {
         if(Low[i+2] > High[i])
         {
            double fvgMid = (Low[i+2] + High[i]) / 2.0;
            if(MathAbs(fvgMid - pocNow) / atr <= FVG_POC_PROX_ATR)
            {
               bearishSignal = true;
               break;
            }
         }
      }
   }

   if(bullishSignal)
   {
      double sl = Low[0] - SL_ATR * atr;
      double tp = Close[0] + TP_ATR * atr;
      // OpenBuyOrder(sl, tp);
   }
   else if(bearishSignal)
   {
      double sl = High[0] + SL_ATR * atr;
      double tp = Close[0] - TP_ATR * atr;
      // OpenSellOrder(sl, tp);
   }
}

