bool VolumeContraction()
{
   double vol5 = 0.0, vol20 = 0.0;
   for(int i = 1; i <= 5; i++)  vol5  += iVolume(_Symbol, PERIOD_CURRENT, i);
   for(int i = 1; i <= 20; i++) vol20 += iVolume(_Symbol, PERIOD_CURRENT, i);
   vol5  /= 5.0;
   vol20 /= 20.0;
   if(vol20 <= 0.0) return false;
   return (vol5 < RETRACE_VOL_RATIO * vol20);
