   {
      double sl = ibPoc + SL_ATR_MULT * atr;
      double tp = Close[0] - TP_ATR_MULT * atr;
      // OpenSellOrder(sl, tp);
   }
}

The exact MQL5 logic below replaces the old static POC fade with a VPOC dislocation continuation model. It first requires a prior-session POC shift of at least 0.35 ATR, then waits for price to retrace into the breakaway FVG located strictly between the two POCs. Entry is taken only when the retracement occurs with above-average tick volume. The target is the new current POC, not the old anchor. The 09:30 UTC opening buffer is preserved.

input int    SESSION_START_HOUR   = 9;
input int    SESSION_START_MIN    = 30;
input int    BUFFER_MINUTES       = 5;       // HIGH-CONFIDENCE VALIDATED FIX
input int    NO_NEW_ENTRY_HOUR    = 11;
input int    NO_NEW_ENTRY_MIN     = 10;      // late-session adverse selection guard
input double MIN_ATR              = 12.0;
input double MIGRATION_ATR        = 0.35;    // prior-session VPOC shift threshold
input double FVG_BUFFER_ATR       = 0.10;    // breakaway FVG must be away from both POCs
input double VOLUME_RETEST_MULT   = 1.5;     // retracement absorption volume
input double SL_ATR_MULT          = 1.0;
input double TP_ATR_MULT          = 1.5;
input int    FVG_MAX_AGE_BARS     = 36;      // relatively fresh breakaway FVG
input int    MAX_SPREAD_POINTS    = 15;

bool InTradeWindow(datetime t) {
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime noNew = StringToTime(TimeToString(t, TIME_DATE) + " 11:10");
   return (t >= start + BUFFER_MINUTES*60 && t < noNew);
}

double GetATR() { return iATR(_Symbol, _Period, 14, 0); }

double GetSessionPOC(datetime start, datetime end) {
   double poc[1];
   if(CopyBuffer(iCustom(_Symbol, _Period, "VolumeProfile", start, end), 0, 0, 1, poc) <= 0) return 0.0;
   return poc[0];
}

double GetPreviousSessionPOC() {
   datetime prevStart = StringToTime(TimeToString(TimeCurrent() - 86400, TIME_DATE) + " 09:30");
   datetime prevEnd   = StringToTime(TimeToString(TimeCurrent() - 86400, TIME_DATE) + " 11:30");
   return GetSessionPOC(prevStart, prevEnd);
}

double GetCurrentSessionPOC() {
   datetime start = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   return GetSessionPOC(start, TimeCurrent());
}

void OnTick() {
   if(!InTradeWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   double pocPrev = GetPreviousSessionPOC();
   double pocNow  = GetCurrentSessionPOC();
   if(pocPrev <= 0.0 || pocNow <= 0.0) return;

   double migration = (pocNow - pocPrev)/atr;
   bool bullishShift = migration > MIGRATION_ATR;
