bool IsBullishFVGUnmitigated(int shift) {
   if(shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   if(High[shift + 2] >= Low[shift]) return false;
   double fvgLow = Low[shift];
   double fvgHigh = High[shift + 2];
   for(int j = shift - 1; j >= 1; j--) {
      if(Low[j] <= fvgHigh && High[j] >= fvgLow) return false; // already mitigated
   }
   return true;
}

bool IsBearishFVGUnmitigated(int shift) {
   if(shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   if(Low[shift + 2] <= High[shift]) return false;
   double fvgHigh = High[shift];
   double fvgLow = Low[shift + 2];
   for(int j = shift - 1; j >= 1; j--) {
      if(Low[j] <= fvgHigh && High[j] >= fvgLow) return false; // already mitigated
   }
   return true;
}

bool HasBullishFVGInLowerValueArea(double val, double atr) {
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++) {
      if(IsBullishFVGUnmitigated(i)) {
         double mid = (High[i + 2] + Low[i]) / 2.0;
         if(mid >= val && mid <= val + VA_REENTRY_ATR * atr) return true;
      }
   }
   return false;
}

bool HasBearishFVGInUpperValueArea(double vah, double atr) {
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++) {
      if(IsBearishFVGUnmitigated(i)) {
         double mid = (Low[i + 2] + High[i]) / 2.0;
         if(mid <= vah && mid >= vah - VA_REENTRY_ATR * atr) return true;
      }
   }
   return false;
}

double GetCumulativeDeltaSlope(int period = 5) {
   int h = iCustom(_Symbol, PERIOD_CURRENT, "CumulativeDelta");
   if(h == INVALID_HANDLE) return 0.0;
   double d0[1], dN[1];
   if(CopyBuffer(h, 0, 0, 1, d0) <= 0) return 0.0;
   if(CopyBuffer(h, 0, period, 1, dN) <= 0) return 0.0;
   return (d0[0] - dN[0]) / MathMax(GetATR(), 1.0);
}

bool BlockMacroLong() {
   double dxyBeta = iCustom(_Symbol, PERIOD_H1, "DXY_Beta", 0, 0);
   double dxyMom  = iCustom(_Symbol, PERIOD_H1, "DXY_Momentum", 0, 0);
   return (dxyBeta < -0.75 && dxyMom > 0.0); // DXY rally hurts DE40 longs
}

bool BlockMacroShort() {
   double dxyBeta = iCustom(_Symbol, PERIOD_H1, "DXY_Beta", 0, 0);
   double dxyMom  = iCustom(_Symbol, PERIOD_H1, "DXY_Momentum", 0, 0);
   return (dxyBeta < -0.75 && dxyMom < 0.0); // DXY drop hurts DE40 shorts
}

void OnTick() {
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);
   ArraySetAsSeries(Open, true);

   if(!InTradeSession()) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   double adx = iADX(_Symbol, PERIOD_CURRENT, 14, PRICE_CLOSE, MODE_MAIN, 0);
   if(adx > 25.0) return; // avoid strong directional auctions

   double poc = GetSessionPOC();
   double vah = GetSessionVAH();
   double val = GetSessionVAL();
   if(poc <= 0.0 || vah <= 0.0 || val <= 0.0) return;

   if(!IsPOCStable(atr)) return;

   int startShift = iBarShift(_Symbol, PERIOD_CURRENT, GetSessionStart(), false);
   double sessionHigh = High[iHighest(_Symbol, PERIOD_CURRENT, MODE_HIGH, startShift, 1)];
   double sessionLow  = Low[iLowest(_Symbol, PERIOD_CURRENT, MODE_LOW, startShift, 1)];

   if(!IsProfileBalanced(vah, val, sessionHigh, sessionLow)) return;

   double deltaSlope = GetCumulativeDeltaSlope();

   // Long: failed auction below VAL, close back inside value, bullish FVG in lower VA, positive delta slope.
   if(Low[0] < val && Close[0] > val && Close[0] > Open[0]) {
      if(BlockMacroLong()) return;
      if(deltaSlope <= DELTA_SLOPE_MIN) return;
      if(!HasBullishFVGInLowerValueArea(val, atr)) return;
      double sl = val - 1.2 * atr;
      double tp = poc + 0.8 * atr;
      // ExecuteBuy(sl, tp);
   }

   // Short: failed auction above VAH, close back inside value, bearish FVG in upper VA, negative delta slope.
   if(High[0] > vah && Close[0] < vah && Close[0] < Open[0]) {
      if(BlockMacroShort()) return;
      if(deltaSlope >= -DELTA_SLOPE_MIN) return;
      if(!HasBearishFVGInUpperValueArea(vah, atr)) return;
      double sl = vah + 1.2 * atr;
      double tp = poc - 0.8 * atr;
      // ExecuteSell(sl, tp);
   }
}

Implement new VPPOC logic with: (1) Validated 09:30 UTC opening buffer. (2) Liquidity decay filter: recent 15-minute average volume must be at least 70% of the opening 15-minute average. (3) Session Volume Profile POC stationarity: rolling standard deviation of POC over the last six M5 bars must be <= 0.20 ATR, so we only fade when the fair value anchor is stable. (4) Price must be in a genuine low-volume node: Volume Profile percentile at current price must be <= 0.35. (5) Price must be 1.5 to 3.0 ATR away from POC. (6) A Fair Value Gap must exist inside the low-volume-node bridge between current price and POC, with direction opposing the excursion. (7) Effort-vs-result local exhaustion must be present: last completed candle shows lower volume and smaller range than the prior opposing candle while closing back through its midpoint. (8) H4 50-EMA slope gates direction: long only if H4 50-EMA is rising, short only if falling. (9) Stop beyond recent 3-bar extreme or 1.2 ATR, target POC or next high-volume node.

Exact MQL5 logic:
input int SESSION_START_HOUR = 9;
input int SESSION_START_MIN = 30;
input int OPENING_BUFFER_MIN = 5;
input double MIN_ATR = 15.0;
input double POC_STABILITY_ATR = 0.20;
input double MIN_EXT_ATR = 1.5;
input double MAX_EXT_ATR = 3.0;
input double LVN_PERCENTILE = 0.35;
input int FVG_MAX_AGE_BARS = 12;
input double VOLUME_RANGE_DECAY = 0.85;
input int H4_EMA_PERIOD = 50;

bool InTradeSession(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + OPENING_BUFFER_MIN * 60 && t < end);
}

double GetATR()
{
   double a[1];
   if(CopyBuffer(iATR(_Symbol, PERIOD_CURRENT, 14), 0, 0, 1, a) <= 0) return 0.0;
   return a[0];
}

double GetH4EMA(int shift)
{
   double e[1];
   if(CopyBuffer(iMA(_Symbol, PERIOD_H4, H4_EMA_PERIOD, 0, MODE_EMA, PRICE_CLOSE, shift), 0, 0, 1, e) <= 0) return 0.0;
   return e[0];
}

double GetSessionPOC(datetime start, datetime end)
{
   double p[1];
   int vpHandle = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(vpHandle == INVALID_HANDLE) return 0.0;
   if(CopyBuffer(vpHandle, 0, 0, 1, p) <= 0) return 0.0;
   return p[0];
}

double GetVolumePercentileAtPrice(double price, datetime start, datetime end)
{
   int vpHandle = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(vpHandle == INVALID_HANDLE) return 1.0;
   double prices[1000];
   double percentile[1000];
   ArraySetAsSeries(prices, true);
   ArraySetAsSeries(percentile, true);
   if(CopyBuffer(vpHandle, 1, 0, 1000, prices) <= 0) return 1.0;
   if(CopyBuffer(vpHandle, 3, 0, 1000, percentile) <= 0) return 1.0;
   int idx = -1;
   double minDist = DBL_MAX;
   for(int i = 0; i < ArraySize(prices); i++)
   {
      if(prices[i] == 0.0) continue;
      double d = MathAbs(prices[i] - price);
      if(d < minDist)
      {
         minDist = d;
         idx = i;
      }
   }
   if(idx < 0) return 1.0;
   return percentile[idx];
}

double GetPOCStability(datetime start, int bars)
{
   double pocs[6];
   int count = 0;
   for(int i = 0; i < bars && i < 6; i++)
   {
      datetime end = TimeCurrent() - i * PeriodSeconds(PERIOD_CURRENT);
      if(end < start + OPENING_BUFFER_MIN * 60) break;
      double poc = GetSessionPOC(start, end);
      if(poc > 0.0)
      {
         pocs[count] = poc;
         count++;
      }
   }
   if(count < 3) return 999.0;
   double mean = 0.0;
   for(int i = 0; i < count; i++) mean += pocs[i];
   mean /= count;
   double var = 0.0;
   for(int i = 0; i < count; i++) var += (pocs[i] - mean) * (pocs[i] - mean);
   var /= count;
   double atr = GetATR();
   if(atr <= 0.0) return 999.0;
   return MathSqrt(var) / atr;
}

bool HasBullishFVGWithinBridge(double poc, double currentPrice, double atr, double &mid)
{
   double lower = MathMin(poc, currentPrice);
   double upper = MathMax(poc, currentPrice);
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(High[i + 2] < Low[i])
      {
         double fvgMid = (High[i + 2] + Low[i]) / 2.0;
         if(fvgMid >= lower && fvgMid <= upper)
         {
            mid = fvgMid;
            return true;
         }
      }
   }
   return false;
}

bool HasBearishFVGWithinBridge(double poc, double currentPrice, double atr, double &mid)
{
   double lower = MathMin(poc, currentPrice);
   double upper = MathMax(poc, currentPrice);
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Low[i + 2] > High[i])
      {
         double fvgMid = (Low[i + 2] + High[i]) / 2.0;
         if(fvgMid >= lower && fvgMid <= upper)
         {
            mid = fvgMid;
            return true;
         }
      }
   }
   return false;
}

bool EffortResultBuyExhaustion()
{
   return (Low[1] <= Low[2] && Close[1] > Open[1] && Close[1] > Low[1] + 0.5 * (High[1] - Low[1])
           && Volume[1] < Volume[2] * VOLUME_RANGE_DECAY
           && (High[1] - Low[1]) < (High[2] - Low[2]) * VOLUME_RANGE_DECAY);
}

bool EffortResultSellExhaustion()
{
   return (High[1] >= High[2] && Close[1] < Open[1] && Close[1] < High[1] - 0.5 * (High[1] - Low[1])
           && Volume[1] < Volume[2] * VOLUME_RANGE_DECAY
           && (High[1] - Low[1]) < (High[2] - Low[2]) * VOLUME_RANGE_DECAY);
}

void OnTick()
{
   if(!InTradeSession(TimeCurrent())) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   datetime start = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");

   double openVol = 0.0;
   int openBars = 3;
   for(int i = 0; i < openBars; i++)
      openVol += iVolume(_Symbol, PERIOD_CURRENT, iBarShift(_Symbol, PERIOD_CURRENT, start, false) - i);
   openVol /= openBars;

   double recentVol = 0.0;
   int recentBars = 3;
   for(int i = 1; i <= recentBars; i++)
      recentVol += iVolume(_Symbol, PERIOD_CURRENT, i);
   recentVol /= recentBars;

   if(openVol > 0.0 && recentVol < 0.70 * openVol) return;

   double poc = GetSessionPOC(start, TimeCurrent());
   if(poc <= 0.0) return;

   double stability = GetPOCStability(start, 6);
   if(stability > POC_STABILITY_ATR) return;

   double dist = (Close[0] - poc) / atr;
   double absDist = MathAbs(dist);
   if(absDist < MIN_EXT_ATR || absDist > MAX_EXT_ATR) return;

   double percentile = GetVolumePercentileAtPrice(Close[0], start, TimeCurrent());
   if(percentile > LVN_PERCENTILE) return;

   double h4ema0 = GetH4EMA(0);
   double h4ema1 = GetH4EMA(1);
   bool h4Bull = (h4ema0 > h4ema1);
   bool h4Bear = (h4ema0 < h4ema1);

   double fvgMid = 0.0;

   if(Close[0] < poc && h4Bull)
   {
      if(HasBullishFVGWithinBridge(poc, Close[0], atr, fvgMid) && EffortResultBuyExhaustion())
      {
         double sl = MathMin(Low[iLowest(_Symbol, PERIOD_CURRENT, MODE_LOW, 3, 1)], Close[0] - 1.2 * atr);
         double tp = poc;
         // trade.Buy(0.01, _Symbol, 0, sl, tp, "DE40_VPPOC_Long");
      }
   }
   else if(Close[0] > poc && h4Bear)
   {
      if(HasBearishFVGWithinBridge(poc, Close[0], atr, fvgMid) && EffortResultSellExhaustion())
      {
         double sl = MathMax(High[iHighest(_Symbol, PERIOD_CURRENT, MODE_HIGH, 3, 1)], Close[0] + 1.2 * atr);
         double tp = poc;
         // trade.Sell(0.01, _Symbol, 0, sl, tp, "DE40_VPPOC_Short");
      }
   }
}

// =============================================================
// Module_1_DE40_VPPOC - Healed: Value Area Failed Auction +
// Value Area Embedded FVG Mitigation + Tick Volume Absorption
// =============================================================
input int    InpSessionStartHour      = 9;
input int    InpSessionStartMin       = 30;
input int    InpSessionEndHour        = 11;
input int    InpSessionEndMin         = 30;
input int    InpBufferMinutes         = 5;       // validated 09:30 buffer
input int    InpMaxSpreadPoints       = 12;
input double InpMinATR                = 10.0;
input double InpValueAreaMinATR       = 0.35;    // min POC-to-VAH/VAL distance
input double InpValueAreaMaxATR       = 2.5;     // max Value Area width
input double InpSkewLong              = 0.62;    // POC_skew >= this: long-only
input double InpSkewShort             = 0.38;    // POC_skew <= this: short-only
input int    InpFVGMaxAgeBars         = 8;       // recent FVGs only
input double InpAbsorptionVolMult     = 1.6;     // current volume vs 20-bar avg
input double InpSLBufferATR           = 0.25;    // stop buffer beyond failed auction wick
input double InpMinDistanceATR        = 0.30;    // min entry-to-POC distance

// -------------------------------------------------------------
bool IsWithinSession(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
   return (t >= start + InpBufferMinutes * 60 && t < end);
}

// -------------------------------------------------------------
// Adjust buffer indices to your VolumeProfile custom indicator.
// Assumed: 0 = POC, 1 = Value Area High, 2 = Value Area Low
// -------------------------------------------------------------
double GetSessionValueProfile(datetime start, datetime end, int bufferIndex)
{
   int h = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   double buf[1];
   if(CopyBuffer(h, bufferIndex, 0, 1, buf) <= 0) return 0.0;
   return buf[0];
}

// -------------------------------------------------------------
// Bearish FVG formed by the down-move away from POC.
// It must be inside the session Value Area and currently being filled.
// -------------------------------------------------------------
bool FindValueAreaBearishFVG(double val, double vah, double &mid)
{
   for(int i = 1; i <= InpFVGMaxAgeBars; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;

      double gapTop    = Low[i + 2];      // upper edge of the bearish imbalance
      double gapBottom = High[i];          // lower edge

      if(gapTop > gapBottom)
      {
         double gapMid = (gapTop + gapBottom) / 2.0;
         if(gapMid >= val && gapMid <= vah)
         {
            // Price has entered the gap and is mitigating it now
            if(Close[0] >= gapBottom && Close[0] <= gapTop)
            {
               mid = gapMid;
               return true;
            }
         }
      }
   }
   return false;
}

// -------------------------------------------------------------
// Bullish FVG formed by the up-move away from POC.
// -------------------------------------------------------------
bool FindValueAreaBullishFVG(double val, double vah, double &mid)
{
   for(int i = 1; i <= InpFVGMaxAgeBars; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;

      double gapTop    = Low[i];          // upper edge of the bullish imbalance
      double gapBottom = High[i + 2];     // lower edge

      if(gapTop > gapBottom)
      {
         double gapMid = (gapTop + gapBottom) / 2.0;
         if(gapMid >= val && gapMid <= vah)
         {
            if(Close[0] >= gapBottom && Close[0] <= gapTop)
            {
               mid = gapMid;
               return true;
            }
         }
      }
   }
   return false;
}

