void OnTick()
{
   if(!IsWithinSession(TimeCurrent())) return;

   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > InpMaxSpreadPoints) return;

   double atr = iATR(_Symbol, PERIOD_CURRENT, 14, 0);
   if(atr < InpMinATR) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   datetime sessionEnd   = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 11:30");

   double poc = GetSessionValueProfile(sessionStart, TimeCurrent(), 0);
   double vah = GetSessionValueProfile(sessionStart, TimeCurrent(), 1);
   double val = GetSessionValueProfile(sessionStart, TimeCurrent(), 2);

   if(poc <= 0.0 || vah <= val) return;

   double valueAreaWidth = vah - val;
   if(valueAreaWidth < InpValueAreaMinATR * atr) return;
   if(valueAreaWidth > InpValueAreaMaxATR * atr) return;

   double pocSkew = (poc - val) / valueAreaWidth;

   bool allowLong  = (pocSkew >= InpSkewLong)  || (pocSkew > InpSkewShort && pocSkew < InpSkewLong);
   bool allowShort = (pocSkew <= InpSkewShort) || (pocSkew > InpSkewShort && pocSkew < InpSkewLong);

   double volumeSMA = iMA(_Symbol, PERIOD_CURRENT, 20, 0, MODE_SMA, VOLUME_TICK, 1);
   double currentVolume = (double)iVolume(_Symbol, PERIOD_CURRENT, 0);
   double absorptionRatio = currentVolume / MathMax(volumeSMA, 1.0);

   // LONG: failed auction below Value Area Low, closed back inside,
   //       filling a bearish FVG that lives inside the Value Area.
   if(allowLong && Low[0] < val && Close[0] > val)
   {
      double fvgMid = 0.0;
      if(FindValueAreaBearishFVG(val, vah, fvgMid))
      {
         if(absorptionRatio >= InpAbsorptionVolMult)
         {
            double sl = Low[0] - InpSLBufferATR * atr;
            double tp = poc;
            if(tp - Close[0] > InpMinDistanceATR * atr)
            {
               // OpenBuyOrder(sl, tp);
            }
         }
      }
   }

   // SHORT: failed auction above Value Area High, closed back inside,
   //        filling a bullish FVG that lives inside the Value Area.
   if(allowShort && High[0] > vah && Close[0] < vah)
   {
      double fvgMid = 0.0;
      if(FindValueAreaBullishFVG(val, vah, fvgMid))
      {
         if(absorptionRatio >= InpAbsorptionVolMult)
         {
            double sl = High[0] + InpSLBufferATR * atr;
            double tp = poc;
            if(Close[0] - tp > InpMinDistanceATR * atr)
            {
               // OpenSellOrder(sl, tp);
            }
         }
      }
   }
}

// -------------------------------------------------------------
// NOTE: Buffer indices for VolumeProfile must be matched to the
// actual custom indicator output. The structural logic above is
// the self-healing core; do not add the debunked OLS/DXY, OBV/MFI,
// session high/low sweep, or VPOC migration conditions.
// -------------------------------------------------------------

input int    SESSION_START_HOUR = 9;
input int    SESSION_START_MIN  = 30;
input int    BUFFER_MINUTES     = 5;
input int    NO_NEW_ENTRY_HOUR  = 10;
input int    NO_NEW_ENTRY_MIN   = 45;
input double MIN_ATR            = 15.0;
input double PRIOR_POC_ALIGN_ATR = 0.35;
input double IB_RANGE_ATR_MAX   = 0.50;
input double PIN_WICK_BODY_RATIO = 1.5;
input int    FVG_MAX_AGE_BARS   = 5;
input double VOLUME_PERCENTILE  = 0.70;
input int    MAX_SPREAD_POINTS  = 15;

datetime SessionStart(datetime t) {
   return StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
}
datetime NoNewTime(datetime t) {
   return StringToTime(TimeToString(t, TIME_DATE) + " 10:45");
}
bool InTradeWindow(datetime t) {
   return (t >= SessionStart(t) + BUFFER_MINUTES*60 && t < NoNewTime(t));
}
double GetATR() {
   return iATR(_Symbol, PERIOD_CURRENT, 14, 0);
}
double GetSessionPOC(datetime start, datetime end) {
   double poc[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end), 0, 0, 1, poc) <= 0)
      return 0.0;
   return poc[0];
}
double GetPriorDayPOC(datetime t) {
   datetime prevStart = StringToTime(TimeToString(t, TIME_DATE) + " 09:30") - 86400;
   datetime prevEnd   = StringToTime(TimeToString(t, TIME_DATE) + " 11:30") - 86400;
   return GetSessionPOC(prevStart, prevEnd);
}
void GetInitialBalanceHighLow(datetime start, int minutes, double &ibHigh, double &ibLow) {
   datetime ibEnd = start + minutes*60;
   int startShift = iBarShift(_Symbol, PERIOD_CURRENT, start);
   int endShift   = iBarShift(_Symbol, PERIOD_CURRENT, ibEnd);
   int count = startShift - endShift + 1;
   if(count <= 0) return;
   ibHigh = High[iHighest(_Symbol, PERIOD_CURRENT, MODE_HIGH, count, endShift)];
   ibLow  = Low[iLowest(_Symbol, PERIOD_CURRENT, MODE_LOW, count, endShift)];
}
bool BullishPinBar() {
   double body = MathAbs(Close[1] - Open[1]);
   double lowerWick = MathMin(Open[1], Close[1]) - Low[1];
   double upperWick = High[1] - MathMax(Open[1], Close[1]);
   return (Close[1] > Open[1] && lowerWick >= PIN_WICK_BODY_RATIO * MathMax(body, 0.01) && upperWick <= 0.3 * lowerWick);
}
bool BearishPinBar() {
   double body = MathAbs(Close[1] - Open[1]);
   double lowerWick = MathMin(Open[1], Close[1]) - Low[1];
   double upperWick = High[1] - MathMax(Open[1], Close[1]);
   return (Close[1] < Open[1] && upperWick >= PIN_WICK_BODY_RATIO * MathMax(body, 0.01) && lowerWick <= 0.3 * upperWick);
}
bool HasRecentBullishFVG() {
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++) {
      if(High[i+2] < Low[i]) return true;
   }
   return false;
}
bool HasRecentBearishFVG() {
   for(int i = 1; i <= FVG_MAX_AGE_BARS; i++) {
      if(Low[i+2] > High[i]) return true;
   }
   return false;
}
bool IsVolumeAbovePercentile(double vol) {
   datetime start = SessionStart(TimeCurrent());
   int startShift = iBarShift(_Symbol, PERIOD_CURRENT, start);
   int currentShift = iBarShift(_Symbol, PERIOD_CURRENT, TimeCurrent());
   int count = startShift - currentShift + 1;
   if(count < 3) return false;
   double vols[];
   ArrayResize(vols, count);
   for(int i = 0; i < count; i++)
      vols[i] = (double)iVolume(_Symbol, PERIOD_CURRENT, i);
   ArraySort(vols);
   int idx = (int)MathFloor((1.0 - VOLUME_PERCENTILE) * count);
   return vol > vols[idx];
}
void OnTick() {
   if(!InTradeWindow(TimeCurrent())) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   datetime start = SessionStart(TimeCurrent());
   double pocCurrent = GetSessionPOC(start, TimeCurrent());
   double pocPrior = GetPriorDayPOC(TimeCurrent());
   if(pocCurrent <= 0.0 || pocPrior <= 0.0) return;

