   if((ibHigh - ibLow) / atr > IB_RANGE_ATR_MAX) return;

   double lastVol = (double)iVolume(_Symbol, PERIOD_CURRENT, 1);
   if(!IsVolumeAbovePercentile(lastVol)) return;

   if(BullishPinBar() && Low[1] < pocCurrent && Close[1] > pocCurrent && HasRecentBullishFVG()) {
      double sl = Low[1] - 0.5 * atr;
      double tp = pocCurrent + 1.5 * atr;
