input double MIN_ATR              = 15.0;
input double MAX_SPREAD_POINTS    = 15;
input double VOLUME_CONFIRM_MULT  = 1.25;
input int    FVG_MAX_AGE_BARS     = 3;
input double LVN_INTENSITY_MAX    = 0.50;
input double POC_VWAP_ANCHOR_ATR  = 0.25;
input double SL_ATR_MULT          = 1.5;
input double TP_ATR_MULT          = 2.0;

bool InTradeWindow(datetime t)
{
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime noNew = StringToTime(TimeToString(t, TIME_DATE) + " 10:30");
   return (t >= start + BUFFER_MINUTES * 60 && t < noNew);
}

double GetATR()
{
   double buf[1];
   if(CopyBuffer(iATR(_Symbol, PERIOD_CURRENT, 14), 0, 0, 1, buf) <= 0) return 0.0;
   return buf[0];
}

double GetADX()
{
   double buf[1];
   if(CopyBuffer(iADX(_Symbol, PERIOD_CURRENT, 14, PRICE_CLOSE, MODE_MAIN, 0), 0, 0, 1, buf) <= 0) return 100.0;
   return buf[0];
}

double GetSessionPOC(datetime start, datetime end)
{
   double poc[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end), 0, 0, 1, poc) <= 0) return 0.0;
   return poc[0];
}

double GetVWAP()
{
   double vw[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VWAP"), 0, 0, 1, vw) <= 0) return 0.0;
   return vw[0];
}

double GetVolumeIntensityAtPrice(double price, datetime start)
{
   int handle = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, TimeCurrent());
   double volAtPoc[1], volAtPrice[1];
   if(CopyBuffer(handle, 1, 0, 1, volAtPoc) <= 0) return 1.0;
   if(CopyBuffer(handle, 2, 0, 1, volAtPrice) <= 0) return 1.0;
   if(volAtPoc[0] <= 0) return 1.0;
   return volAtPrice[0] / volAtPoc[0];
}

bool HasFreshBullishFVG(int shift, double &mid)
{
   if(shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   mid = (High[shift + 2] + Low[shift]) / 2.0;
   return (High[shift + 2] < Low[shift]);
}

bool HasFreshBearishFVG(int shift, double &mid)
{
   if(shift + 2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   mid = (Low[shift + 2] + High[shift]) / 2.0;
   return (Low[shift + 2] > High[shift]);
}

void OnTick()
{
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);
   ArraySetAsSeries(Volume, true);

   datetime now = TimeCurrent();
   if(!InTradeWindow(now)) return;
   if(SymbolInfoInteger(_Symbol, SYMBOL_SPREAD) > MAX_SPREAD_POINTS) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   double adx = GetADX();
   if(adx >= MAX_ADX_FOR_REVERSION) return;

   double avgVol = 0.0;
   for(int i = 1; i <= 20; i++) avgVol += (double)Volume[i];
   avgVol /= 20.0;
   if((double)Volume[0] < VOLUME_CONFIRM_MULT * avgVol) return;

   datetime sessionStart = StringToTime(TimeToString(now, TIME_DATE) + " 09:30");
   double poc = GetSessionPOC(sessionStart, now);
   double vwap = GetVWAP();
   if(poc <= 0.0 || vwap <= 0.0) return;

   double anchor = (MathAbs(poc - vwap) / atr < POC_VWAP_ANCHOR_ATR) ? poc : vwap;

   double dxyBeta = iCustom(_Symbol, PERIOD_H1, "DXY_Beta", 0, 0);
   double dxyMom  = iCustom(_Symbol, PERIOD_H1, "DXY_Momentum", 0, 0);
   bool blockLong  = (dxyBeta < -0.75 && dxyMom > 0.0);
   bool blockShort = (dxyBeta < -0.75 && dxyMom < 0.0);

   if(!blockLong && Low[0] < anchor && Close[0] > anchor && Close[0] > Open[0])
   {
      double fvgMid = 0.0;
      bool freshFVG = false;
      for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
      {
         if(HasFreshBullishFVG(i, fvgMid))
         {
            freshFVG = true;
            break;
         }
      }
      if(freshFVG && fvgMid < anchor && GetVolumeIntensityAtPrice(Close[0], sessionStart) < LVN_INTENSITY_MAX)
      {
         double sl = anchor - SL_ATR_MULT * atr;
         double tp = anchor + TP_ATR_MULT * atr;
         // trade.Buy(...);
      }
   }

   if(!blockShort && High[0] > anchor && Close[0] < anchor && Close[0] < Open[0])
   {
      double fvgMid = 0.0;
      bool freshFVG = false;
      for(int i = 1; i <= FVG_MAX_AGE_BARS; i++)
      {
         if(HasFreshBearishFVG(i, fvgMid))
         {
            freshFVG = true;
            break;
         }
      }
      if(freshFVG && fvgMid > anchor && GetVolumeIntensityAtPrice(Close[0], sessionStart) < LVN_INTENSITY_MAX)
      {
         double sl = anchor + SL_ATR_MULT * atr;
         double tp = anchor - TP_ATR_MULT * atr;
         // trade.Sell(...);
      }
   }
}

