bool GetSessionVolumeProfile(datetime start, datetime end, double &poc, double &vah, double &val)
{
   // Assumes VolumeProfile indicator with buffers: 0=POC, 1=VAH, 2=VAL
   int vpHandle = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(vpHandle == INVALID_HANDLE) return false;
   double bufPOC[1], bufVAH[1], bufVAL[1];
   if(CopyBuffer(vpHandle, 0, 0, 1, bufPOC) <= 0) return false;
   if(CopyBuffer(vpHandle, 1, 0, 1, bufVAH) <= 0) return false;
   if(CopyBuffer(vpHandle, 2, 0, 1, bufVAL) <= 0) return false;
