bool BullishFVGAtVAL(int shift, double &mid, double val, double atr)
{
   if(shift+2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   mid = (High[shift+2] + Low[shift]) / 2.0;
   return (High[shift+2] < Low[shift] && MathAbs(mid - val) / atr <= FVG_VA_OVERLAP_ATR);
