bool BearishFVGAtVAH(int shift, double &mid, double vah, double atr)
{
   if(shift+2 >= Bars(_Symbol, PERIOD_CURRENT)) return false;
   mid = (Low[shift+2] + High[shift]) / 2.0;
   return (Low[shift+2] > High[shift] && MathAbs(mid - vah) / atr <= FVG_VA_OVERLAP_ATR);
}

bool HasRecentBullishFVGAtVAL(double val, double atr)
{
