   double plusDI = iADX(_Symbol, PERIOD_CURRENT, 14, PRICE_CLOSE, MODE_PLUSDI, 0);
   double minusDI = iADX(_Symbol, PERIOD_CURRENT, 14, PRICE_CLOSE, MODE_MINUSDI, 0);
