   datetime sessionEnd = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 11:30");
   if(!GetSessionVolumeProfile(sessionStart, sessionEnd, poc, vah, val)) return;

   // Long: price breaks below Value Area Low and closes back inside; fresh bullish FVG near VAL; trend not strongly bearish.
   if(Low[0] < val && Close[0] > val && Close[0] > Open[0] && Close[0] < poc)
   {
      if(!IsBearishTrend() && HasRecentBullishFVGAtVAL(val, atr))
      {
         double sl = val - SL_ATR_MULT * atr;
         double tp = poc;
         double lot = 0.1; // use proper risk sizing
         trade.Buy(lot, _Symbol, 0.0, sl, tp, "VPPOC_VA_Long");
      }
   }
   // Short: price breaks above Value Area High and closes back inside; fresh bearish FVG near VAH; trend not strongly bullish.
   else if(High[0] > vah && Close[0] < vah && Close[0] < Open[0] && Close[0] > poc)
   {
      if(!IsBullishTrend() && HasRecentBearishFVGAtVAH(vah, atr))
      {
         double sl = vah + SL_ATR_MULT * atr;
         double tp = poc;
         double lot = 0.1;
         trade.Sell(lot, _Symbol, 0.0, sl, tp, "VPPOC_VA_Short");
      }
   }
}

