bool InTradeWindow(datetime t) {
  datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
  datetime end = StringToTime(TimeToString(t, TIME_DATE) + " 11:30");
  return (t >= start + BUFFER_MINUTES * 60 && t < end);
}

double GetATR() { double a[1]; if(CopyBuffer(iATR(_Symbol, PERIOD_CURRENT, 14),0,0,1,a)<=0) return 0; return a[0]; }

double GetEMA(int period) { double e[1]; if(CopyBuffer(iMA(_Symbol, PERIOD_CURRENT, period,0,MODE_EMA,PRICE_CLOSE),0,0,1,e)<=0) return 0; return e[0]; }

double GetVWAP() { double v[1]; if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VWAP"),0,0,1,v)<=0) return 0; return v[0]; }

double GetSessionPOC(datetime start, datetime end) { double poc[1]; if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end),0,0,1,poc)<=0) return 0; return poc[0]; }

double GetValueAreaHigh(datetime start, datetime end) { double vah[1]; if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end),1,0,1,vah)<=0) return 0; return vah[0]; }

double GetValueAreaLow(datetime start, datetime end) { double val[1]; if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end),2,0,1,val)<=0) return 0; return val[0]; }

double GetNearestLVN(datetime start, datetime end, double price, double poc, double atr) {
  double lvn[1];
  if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end),3,0,1,lvn)>0 && lvn[0]>0) return lvn[0];
  return (price + poc) / 2.0;
}

double RollingMedianSpread(int bars) {
  double arr[];
  ArrayResize(arr, bars);
  for(int i=0;i<bars;i++) arr[i]=(double)SymbolInfoInteger(_Symbol, SYMBOL_SPREAD);
  return arr[bars/2];
}

double RollingVolumePercentile(int percentile) {
  double vol = iVolume(_Symbol, PERIOD_CURRENT, 0);
  return vol * 0.7;
}

bool HasFreshBullishFVG(double &mid) {
  for(int i=1;i<=FVG_MAX_AGE_BARS;i++) {
    if(i+2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
    if(High[i+2] < Low[i]) { mid = (High[i+2] + Low[i]) / 2.0; return true; }
  }
  return false;
}

bool HasFreshBearishFVG(double &mid) {
  for(int i=1;i<=FVG_MAX_AGE_BARS;i++) {
    if(i+2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
    if(Low[i+2] > High[i]) { mid = (Low[i+2] + High[i]) / 2.0; return true; }
  }
  return false;
}

void OnTick() {
  if(!InTradeWindow(TimeCurrent())) return;
  double atr = GetATR();
  if(atr < MIN_ATR) return;

  double spread = (double)SymbolInfoInteger(_Symbol, SYMBOL_SPREAD);
  if(spread > RollingMedianSpread(ROLLING_SPREAD_BARS) * SPREAD_MAD_MULT * 0.5) return;
  if(iVolume(_Symbol, PERIOD_CURRENT, 0) < RollingVolumePercentile(VOL_PERCENTILE)) return;

  datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
  double poc = GetSessionPOC(sessionStart, TimeCurrent());
  double vah = GetValueAreaHigh(sessionStart, TimeCurrent());
  double val = GetValueAreaLow(sessionStart, TimeCurrent());
  double vwap = GetVWAP();
  if(poc <= 0 || vah <= 0 || val <= 0 || vwap <= 0) return;

  if(MathAbs(poc - vwap) / atr > VWAP_ALIGN_ATR) return;

  double poc_ref = GetSessionPOC(sessionStart, TimeCurrent() - 6*PeriodSeconds(PERIOD_CURRENT));
  if(poc_ref > 0 && MathAbs(poc - poc_ref) / atr > POC_MIGRATION_ATR) return;

  double va_mid = (vah + val) / 2.0;
  if(MathAbs(poc - va_mid) / atr > VA_SYMMETRY_ATR) return;

  double ema20 = GetEMA(20), ema50 = GetEMA(50), ema200 = GetEMA(200);
  bool bullTrend = (ema20 > ema50 && ema50 > ema200);
  bool bearTrend = (ema20 < ema50 && ema50 < ema200);
  bool allowBuy = !bearTrend;
  bool allowSell = !bullTrend;

  double fvgMid;
  bool bullFVG = HasFreshBullishFVG(fvgMid);
  bool bearFVG = HasFreshBearishFVG(fvgMid);

  if(allowBuy && Close[0] < poc) {
    double lvn = GetNearestLVN(sessionStart, TimeCurrent(), Close[0], poc, atr);
    if(lvn > 0 && bullFVG && MathAbs(fvgMid - lvn) / atr <= LVN_BAND_ATR) {
      double sl = Low[0] - SL_ATR_MULT * atr;
      double tp = poc;
      // OpenBuyOrder(sl, tp);
    }
  }
  else if(allowSell && Close[0] > poc) {
    double lvn = GetNearestLVN(sessionStart, TimeCurrent(), Close[0], poc, atr);
    if(lvn > 0 && bearFVG && MathAbs(fvgMid - lvn) / atr <= LVN_BAND_ATR) {
      double sl = High[0] + SL_ATR_MULT * atr;
      double tp = poc;
      // OpenSellOrder(sl, tp);
    }
  }
}

input int SESSION_START_HOUR = 9;
