bool GetSessionHighLow(datetime start, datetime end, double &hi, double &lo)
{
   hi = -DBL_MAX; lo = DBL_MAX;
   bool found = false;
   for(int i = Bars(_Symbol, PERIOD_CURRENT)-1; i >= 0; i--)
   {
      datetime t = Time[i];
      if(t < start) continue;
      if(t > end) break;
      if(High[i] > hi) hi = High[i];
      if(Low[i]  < lo) lo = Low[i];
      found = true;
   }
   return found;
}

void BuildVolumeProfile(datetime start, datetime end, double sessionHigh, double sessionLow, int binCount, double &bins[], double &vols[])
{
   ArrayResize(bins, binCount);
   ArrayResize(vols, binCount);
   ArrayInitialize(vols, 0.0);
   if(sessionHigh <= sessionLow) return;
   double binSize = (sessionHigh - sessionLow) / binCount;
   for(int b = 0; b < binCount; b++)
      bins[b] = sessionLow + (b + 0.5) * binSize;

   for(int i = Bars(_Symbol, PERIOD_CURRENT)-1; i >= 0; i--)
   {
      datetime t = Time[i];
      if(t < start) continue;
      if(t > end) break;
      int bin = (int)MathFloor((Close[i] - sessionLow) / binSize);
      if(bin < 0) bin = 0;
      if(bin >= binCount) bin = binCount - 1;
      vols[bin] += TickVolume[i];
   }
}

int GetPOCIndex(double &vols[], int binCount)
{
   int maxIdx = 0;
   double maxVol = -1.0;
   for(int b = 0; b < binCount; b++)
   {
      if(vols[b] > maxVol)
      {
         maxVol = vols[b];
         maxIdx = b;
      }
   }
   return maxIdx;
}

int CountHighVolumeNodes(double &vols[], int binCount, double maxVol, double threshold)
{
   int count = 0;
   for(int b = 0; b < binCount; b++)
      if(vols[b] > threshold * maxVol)
         count++;
   return count;
}

bool PriceCrossedLVN(double price, double poc, double &bins[], double &vols[], double maxVol, double lvnFrac)
{
   int b1 = ArrayBsearch(bins, MathMin(price, poc));
   int b2 = ArrayBsearch(bins, MathMax(price, poc));
   if(b1 > b2) { int tmp = b1; b1 = b2; b2 = tmp; }
   for(int b = b1; b <= b2; b++)
      if(vols[b] < lvnFrac * maxVol)
         return true;
   return false;
}

bool IsFVGInsideLVN(double fvgMid, double &bins[], double &vols[], double maxVol, double lvnFrac)
{
   int b = ArrayBsearch(bins, fvgMid);
   if(b < 0 || b >= ArraySize(vols)) return false;
   if(vols[b] < lvnFrac * maxVol) return true;
   if(b > 0 && vols[b-1] < lvnFrac * maxVol) return true;
   if(b < ArraySize(vols)-1 && vols[b+1] < lvnFrac * maxVol) return true;
   return false;
}

bool FindRecentBullishFVG(double &mid)
{
   for(int i = 1; i < FVG_MAX_AGE_BARS; i++)
