bool VolumeContraction()
{
   double avg = 0.0;
   int count = 0;
   for(int i = 1; i <= 20; i++)
   {
      if(i >= Bars(_Symbol, PERIOD_CURRENT)) break;
      avg += TickVolume[i];
      count++;
   }
   if(count == 0) return false;
   avg /= count;
   return (TickVolume[0] < VOLUME_CONTRACTION_RATIO * avg);
}

void OnTick()
{
   ArraySetAsSeries(Time, true);
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);
   ArraySetAsSeries(TickVolume, true);

   if(!InTradeWindow(TimeCurrent())) return;

   double atr = GetATR();
   if(atr < 12.0) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   double sessionHigh, sessionLow;
   if(!GetSessionHighLow(sessionStart, TimeCurrent(), sessionHigh, sessionLow)) return;

   double bins[];
   double vols[];
   BuildVolumeProfile(sessionStart, TimeCurrent(), sessionHigh, sessionLow, BIN_COUNT, bins, vols);

   int pocIdx = GetPOCIndex(vols, BIN_COUNT);
   double maxVol = vols[pocIdx];
   if(maxVol <= 0.0) return;

   int highVolNodes = CountHighVolumeNodes(vols, BIN_COUNT, maxVol, 0.5);
   if(highVolNodes < 2) return; // no two-way auction

   double poc = bins[pocIdx];
   double pocPercentile = (poc - sessionLow) / (sessionHigh - sessionLow);
   bool blockLongs = (pocPercentile < MIN_POC_PERCENTILE_LOW);
