            double sl = Close[0] - SL_ATR_MULT * atr;
            double tp = poc;
            // OpenLongPosition(sl, tp);
         }
      }
   }
   else if(!blockShorts && Close[0] > poc)
   {
      if(PriceCrossedLVN(Close[0], poc, bins, vols, maxVol, LVN_VOLUME_FRACTION))
      {
         if(FindRecentBearishFVG(fvgMid) && IsFVGInsideLVN(fvgMid, bins, vols, maxVol, LVN_VOLUME_FRACTION))
         {
            double sl = Close[0] + SL_ATR_MULT * atr;
            double tp = poc;
            // OpenShortPosition(sl, tp);
         }
      }
   }
}

