bool GetSessionValueArea(datetime start, datetime end,
                        double &poc, double &vah, double &val)
{
   // Assumes a custom VolumeProfile indicator with buffers:
   // 0 = POC, 1 = VAH, 2 = VAL. Adjust to your vendor's mapping.
   int vp = iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end);
   if(vp == INVALID_HANDLE) return false;
   double pocBuf[1], vahBuf[1], valBuf[1];
   ArraySetAsSeries(pocBuf, true);
   ArraySetAsSeries(vahBuf, true);
   ArraySetAsSeries(valBuf, true);
   if(CopyBuffer(vp, 0, 0, 1, pocBuf) <= 0) return false;
   if(CopyBuffer(vp, 1, 0, 1, vahBuf) <= 0) return false;
   if(CopyBuffer(vp, 2, 0, 1, valBuf) <= 0) return false;
   poc = pocBuf[0];
   vah = vahBuf[0];
   val = valBuf[0];
   return true;
}

bool HasFreshBullishFVG(int maxAgeBars, double &mid)
{
   for(int i = 1; i <= maxAgeBars; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(High[i + 2] < Low[i])  // bullish imbalance
      {
         mid = (High[i + 2] + Low[i]) / 2.0;
         return true;
      }
   }
   return false;
}

bool HasFreshBearishFVG(int maxAgeBars, double &mid)
{
   for(int i = 1; i <= maxAgeBars; i++)
   {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Low[i + 2] > High[i])  // bearish imbalance
