void OnTick()
{
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);
   ArraySetAsSeries(Open, true);
   ArraySetAsSeries(TickVolume, true);

   if(!InTradeWindow(TimeCurrent())) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   // Volume participation filter: avoid off-hours illiquidity clusters.
   double avgTickVolume = 0.0;
   for(int i = 1; i <= 20; i++)
      avgTickVolume += (double)TickVolume[i];
   avgTickVolume /= 20.0;
   if(avgTickVolume <= 0.0) return;
   if((double)TickVolume[0] < MIN_PARTICIPATION * avgTickVolume) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   double poc, vah, val;
   if(!GetSessionValueArea(sessionStart, TimeCurrent(), poc, vah, val))
      return;

   // Balanced profile gate 1: POC must be stable, not migrating.
   datetime refTime = TimeCurrent() - 3 * PeriodSeconds(PERIOD_CURRENT);
   if(refTime < sessionStart + BUFFER_MINUTES * 60) return;
   double pocRef, vahRef, valRef;
   if(!GetSessionValueArea(sessionStart, refTime, pocRef, vahRef, valRef))
      return;
   double migration = (poc - pocRef) / atr;
   if(MathAbs(migration) > MAX_POC_MIGRATION) return;

   // Balanced profile gate 2: value area wide enough and symmetric around POC.
   double width = (vah - val) / atr;
   if(width < MIN_VALUE_WIDTH_ATR) return;
   double upperSpan = vah - poc;
   double lowerSpan = poc - val;
   double denom = upperSpan + lowerSpan;
   if(denom < atr * 0.1) return;
   double skew = (upperSpan - lowerSpan) / denom;
   if(MathAbs(skew) > MAX_PROFILE_SKEW) return;

   // Higher-timeframe trend filter: do not fade a confirmed H1 trend.
   double ema20H1 = iMA(_Symbol, PERIOD_H1, 20, 0, MODE_EMA, PRICE_CLOSE, 0);
   double ema50H1 = iMA(_Symbol, PERIOD_H1, 50, 0, MODE_EMA, PRICE_CLOSE, 0);
   bool h1Bull = (ema20H1 > ema50H1);
   bool h1Bear = (ema20H1 < ema50H1);

   // Signal: price below POC -> look for bullish FVG retracement inside value area.
   // Price above POC -> look for bearish FVG retracement inside value area.
   double fvgMid = 0.0;
   bool longSetup = false;
   bool shortSetup = false;

   if(Close[0] < poc && HasFreshBullishFVG(FVG_MAX_AGE_BARS, fvgMid))
   {
      // Fair value mitigation: price must have retraced close to the FVG midpoint.
      if(MathAbs(Close[0] - fvgMid) / atr <= 0.10 && fvgMid >= val && fvgMid <= vah)
         longSetup = true;
   }
   else if(Close[0] > poc && HasFreshBearishFVG(FVG_MAX_AGE_BARS, fvgMid))
   {
      if(MathAbs(Close[0] - fvgMid) / atr <= 0.10 && fvgMid >= val && fvgMid <= vah)
         shortSetup = true;
   }

   if(longSetup && !h1Bear)
   {
      double sl = MathMin(Low[0], Close[0]) - SL_ATR_MULT * atr;
      double tp = poc; // target POC reversion
      // OpenBuyOrder(sl, tp);
   }
   else if(shortSetup && !h1Bull)
   {
      double sl = MathMax(High[0], Close[0]) + SL_ATR_MULT * atr;
      double tp = poc; // target POC reversion
      // OpenSellOrder(sl, tp);
   }
}

