double LinearRegressionSlope(int period)
{
   double xMean = (period - 1.0) / 2.0;
   double yMean = 0.0;
   for(int i = 0; i < period; i++) yMean += Close[i];
   yMean /= period;
   double num = 0.0, den = 0.0;
   for(int i = 0; i < period; i++)
   {
      double x = i;
      num += (x - xMean) * (Close[i] - yMean);
      den += (x - xMean) * (x - xMean);
   }
   if(den == 0.0) return 0.0;
   return num / den;
}

double LinearRegressionR2(int period)
{
   double xMean = (period - 1.0) / 2.0;
   double yMean = 0.0;
   for(int i = 0; i < period; i++) yMean += Close[i];
   yMean /= period;
   double slope = LinearRegressionSlope(period);
   double intercept = yMean - slope * xMean;
   double ssTot = 0.0, ssRes = 0.0;
   for(int i = 0; i < period; i++)
   {
      double yPred = slope * i + intercept;
      ssTot += (Close[i] - yMean) * (Close[i] - yMean);
      ssRes += (Close[i] - yPred) * (Close[i] - yPred);
   }
   if(ssTot == 0.0) return 0.0;
   return 1.0 - ssRes / ssTot;
}

