   double now[1], prev[1];
   int h = iCustom(_Symbol, _Period, "CumulativeVolumeDelta");
   if(CopyBuffer(h, 0, 0, 1, now) <= 0 || CopyBuffer(h, 0, 1, 1, prev) <= 0) return 0.0;
   return (now[0] - prev[0]) / MathMax(iATR(_Symbol, _Period, 14, 0), 0.1);
}

bool IsFreshBullishFVG(int shift, double &mid) {
   if(shift < 1 || shift > FVG_MAX_AGE_BARS) return false;
   mid = (High[shift + 2] + Low[shift]) / 2.0;
   return (High[shift + 2] < Low[shift]);
}

bool IsFreshBearishFVG(int shift, double &mid) {
   if(shift < 1 || shift > FVG_MAX_AGE_BARS) return false;
   mid = (Low[shift + 2] + High[shift]) / 2.0;
   return (Low[shift + 2] > High[shift]);
}

void OnTick() {
   ArraySetAsSeries(High, true);
   ArraySetAsSeries(Low, true);
   ArraySetAsSeries(Close, true);
   if(!InTradeWindow(TimeCurrent())) return;
   if(PositionsTotal() > 0) return;
   double atr = iATR(_Symbol, _Period, 14, 0);
   if(atr < MIN_ATR) return;

   datetime start = SessionStart(TimeCurrent());
   double poc = GetSessionPOC(start, TimeCurrent());
   double vah = GetSessionVAH(start, TimeCurrent());
   double val = GetSessionVAL(start, TimeCurrent());
   if(poc <= 0.0 || vah <= 0.0 || val <= 0.0 || vah <= val) return;

   double delta = CVDDeltaNormalized();
   bool buying = delta > MIN_DELTA_ATR;
   bool selling = delta < -MIN_DELTA_ATR;

   if(Close[0] < poc && Low[0] < val && Close[0] > val && buying) {
      double mid;
      bool fvgOk = false;
      for(int i = 1; i <= FVG_MAX_AGE_BARS; i++) {
         if(IsFreshBullishFVG(i, mid) && mid > val - VAL_TOUCH_ATR * atr && mid < poc) { fvgOk = true; break; }
      }
      if(fvgOk) {
         double sl = val - SL_ATR_MULT * atr;
         double tp = poc;
         // OpenBuyOrder(sl, tp);
      }
   }
   if(Close[0] > poc && High[0] > vah && Close[0] < vah && selling) {
      double mid;
      bool fvgOk = false;
      for(int i = 1; i <= FVG_MAX_AGE_BARS; i++) {
         if(IsFreshBearishFVG(i, mid) && mid < vah + VAL_TOUCH_ATR * atr && mid > poc) { fvgOk = true; break; }
      }
      if(fvgOk) {
         double sl = vah + SL_ATR_MULT * atr;
         double tp = poc;
         // OpenSellOrder(sl, tp);
      }
   }
}

Replace the static POC-extension fade with a balanced-auction, value-area sweep-and-reclaim, fair-value-mitigation engine. Keep the 09:30 UTC session and 5-minute opening buffer. Require: (1) market regime is rotational: CHOP > 52 and ADX < 20; (2) the rolling session POC is stable relative to the first 30 minutes: |POC_now - POC_ref| / ATR < 0.10; (3) price is in a Low Volume Node at entry; (4) previous closed bar sweeps the value area edge and closes back inside: long Low[1] < VAL and Close[1] > VAL, short High[1] > VAH and Close[1] < VAH; (5) previous bar is a reversal candle with volume > 1.2 x average; (6) a fresh unmitigated FVG exists within 6 bars whose midpoint lies between VAL and POC for longs, or between POC and VAH for shorts. Stop loss beyond the sweep extreme; target POC or opposite value area edge.

Exact MQL5 logic:

input int   SESSION_START_HOUR   = 9;
input int   SESSION_START_MIN    = 30;
input int   BUFFER_MINUTES       = 5;
input double MIN_ATR             = 12.0;
input double CHOP_MIN            = 52.0;
input double ADX_MAX             = 20.0;
input double POC_STABILITY_ATR   = 0.10;
input double LVN_VOL_RATIO       = 0.30;
input int    FVG_MAX_AGE_BARS    = 6;
input double SL_ATR_MULT         = 1.0;
input double TP_ATR_MULT         = 2.0;
input double VOLUME_MIN_MULT     = 1.2;

bool InTradeWindow(datetime t) {
   datetime start = StringToTime(TimeToString(t, TIME_DATE) + " 09:30");
   datetime end   = start + 2 * 3600; // 11:30
   return (t >= start + BUFFER_MINUTES * 60 && t < end);
}

double GetATR() {
   return iATR(_Symbol, PERIOD_CURRENT, 14, 0);
}

double GetChoppiness() {
   return iCustom(_Symbol, PERIOD_CURRENT, "ChoppinessIndex", 14, 0);
}

double GetADX() {
   return iADX(_Symbol, PERIOD_CURRENT, 14, PRICE_CLOSE, MODE_MAIN, 0);
}

double GetSessionPOC(datetime start, datetime end) {
   double buf[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end), 0, 0, 1, buf) <= 0)
      return 0.0;
   return buf[0];
}

double GetValueAreaHigh(datetime start, datetime end) {
   double buf[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end), 1, 0, 1, buf) <= 0)
      return 0.0;
   return buf[0];
}

double GetValueAreaLow(datetime start, datetime end) {
   double buf[1];
   if(CopyBuffer(iCustom(_Symbol, PERIOD_CURRENT, "VolumeProfile", start, end), 2, 0, 1, buf) <= 0)
      return 0.0;
   return buf[0];
}

bool IsLVN(double price, datetime start, datetime end) {
   double poc = GetSessionPOC(start, end);
   if(poc <= 0) return false;
   // Custom VolumeProfile should provide volume-at-price; mapping to price bucket required.
   double volPOC = GetVolumeAtPOC(start, end);
   double volAtPrice = GetVolumeAtPrice(price, start, end);
   if(volPOC <= 0) return false;
   return (volAtPrice / volPOC) < LVN_VOL_RATIO;
}

bool HasBullishFVG(int fromShift, int maxBars, double lowBound, double highBound) {
   for(int i = fromShift; i < fromShift + maxBars; i++) {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(High[i + 2] < Low[i]) {
         double mid = (High[i + 2] + Low[i]) / 2.0;
         if(mid > lowBound && mid < highBound) return true;
      }
   }
   return false;
}

bool HasBearishFVG(int fromShift, int maxBars, double lowBound, double highBound) {
   for(int i = fromShift; i < fromShift + maxBars; i++) {
      if(i + 2 >= Bars(_Symbol, PERIOD_CURRENT)) break;
      if(Low[i + 2] > High[i]) {
         double mid = (Low[i + 2] + High[i]) / 2.0;
         if(mid > lowBound && mid < highBound) return true;
      }
   }
   return false;
}

void OnTick() {
   if(!InTradeWindow(TimeCurrent())) return;

   double atr = GetATR();
   if(atr < MIN_ATR) return;

   double chop = GetChoppiness();
   double adx = GetADX();
   if(chop < CHOP_MIN || adx > ADX_MAX) return;

   datetime sessionStart = StringToTime(TimeToString(TimeCurrent(), TIME_DATE) + " 09:30");
   datetime refEnd = sessionStart + 30 * 60; // first 30 minutes
   double pocRef = GetSessionPOC(sessionStart, refEnd);
   double pocNow = GetSessionPOC(sessionStart, TimeCurrent());
   double vah = GetValueAreaHigh(sessionStart, TimeCurrent());
   double val = GetValueAreaLow(sessionStart, TimeCurrent());
   if(pocRef <= 0 || pocNow <= 0 || vah <= 0 || val <= 0) return;

   if(MathAbs(pocNow - pocRef) / atr > POC_STABILITY_ATR) return; // balanced auction only

   double volAvg = iMA(_Symbol, PERIOD_CURRENT, 20, 0, MODE_SMA, VOLUME_TICK, 1);
   double volLast = (double)iVolume(_Symbol, PERIOD_CURRENT, 1);
   if(volLast < VOLUME_MIN_MULT * volAvg) return;

   bool longSetup = (Low[1] < val && Close[1] > val && Close[1] > Open[1]);
   bool shortSetup = (High[1] > vah && Close[1] < vah && Close[1] < Open[1]);

   if(longSetup && IsLVN(Close[1], sessionStart, TimeCurrent()) && HasBullishFVG(1, FVG_MAX_AGE_BARS, val, pocNow)) {
      double sl = Low[1] - SL_ATR_MULT * atr;
      double tp = Close[0] + TP_ATR_MULT * atr; // or session POC target
      // ExecuteBuy(sl, tp)
   } else if(shortSetup && IsLVN(Close[1], sessionStart, TimeCurrent()) && HasBearishFVG(1, FVG_MAX_AGE_BARS, pocNow, vah)) {
      double sl = High[1] + SL_ATR_MULT * atr;
      double tp = Close[0] - TP_ATR_MULT * atr;
      // ExecuteSell(sl, tp)
   }
}

